insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (3, 17, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1029) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أُسَامَةَ بْنِ شَرِيكٍ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ الْأَعْرَابَ يَسْأَلُونَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَعَلَيْنَا حَرَجٌ فِي كَذَا؟ أَعَلَيْنَا حَرَجٌ فِي كَذَا؟ فَقَالَ لَهُمْ: "عِبَادَ اللهِ، وَضَعَ اللهُ الْحَرَجَ إِلَّا مَنِ اقْتَرَضَ مِنْ عِرْضِ أَخِيهِ شَيْئًا، فَذَاكَ الَّذِي حَرِجَ". فَقَالُوا: يَا رَسُولَ اللهِ، هَلْ عَلَيْنَا جُنَاحٌ أَنْ لَا نَتَدَاوَى؟ قَالَ: "تَدَاوَوْا عِبَادَ اللهِ، فَإِنَّ اللهَ سُبْحَانَهُ لَمْ يَضَعْ دَاءً إِلَّا وَضَعَ مَعَهُ شِفَاءً، إِلَّا الْهَرَمَ". قَالُوا: يَا رَسُولَ اللهِ، مَا خَيْرُ مَا أُعْطِيَ الْعَبْدُ؟ قَالَ: "خُلُقٌ حَسَنٌ". (د,ت,جه)', 'ഉസാമതുബ്നു ശരീക്(റ): കുറച്ച് അഅ്റാബികൾ ഇന്ന കാര്യം ചെയ്യുന്നതിൽ പ്രശ്നമുണ്ടോ, ഈ കാര്യം ചെയ്യുന്നതിൽ പ്രശ്നമുണ്ടോ എന്ന് നബി(സ)യോട് ചോദിക്കുന്നതായി ഞാൻ കണ്ടു. നബി(സ) അവരോട് പറഞ്ഞു: "ദൈവദാസരേ, തന്റെ സഹോദരനെ അഭിമാനഹത്യ ചെയ്തവനൊഴികെ അല്ലാഹു ബുദ്ധിമുട്ട് നീക്കിക്കൊടുത്തിരിക്കുന്നു. അതാണ് ബുദ്ധിമുട്ടാക്കിയത്." അപ്പോൾ അവർ ചോദിച്ചു: റസൂലേ, ഞങ്ങൾ ചികിത്സ തേടാതിരിക്കുന്നതിൽ വല്ല പ്രശ്നവുമുണ്ടോ? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ അടിമകളേ, നിങ്ങൾ ചികിത്സ തേടുക. കാരണം അല്ലാഹു ഒരു രോഗത്തെയും ചികിത്സ കൂടാതെ ഉണ്ടാക്കിയിട്ടില്ല, വാർധക്യമൊഴികെ." അപ്പോൾ അവർ ചോദിച്ചു: റസൂലേ, ഒരടിമക്ക് നൽകപ്പെട്ട ഏറ്റവും നല്ല വസ്തു ഏതാണ്? നബി(സ) പറഞ്ഞു: "സൽസ്വഭാവം." (ദ,തു,ജ)', 'أُسَامَةَ بْنِ شَرِيكٍ', 'ഉസാമതുബ്നു ശരീക്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا أَنْزَلَ اللهُ دَاءً إِلَّا أَنْزَلَ لَهُ دَوَاءً". (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു രോഗത്തെയും മരുന്നില്ലാതെ അല്ലാഹു ഇറക്കിയിട്ടില്ല." (ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا أَنْزَلَ اللهُ دَاءً إِلَّا أَنْزَلَ لَهُ شِفَاءً". (خ,د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ചികിത്സ കൂടാതെയുള്ള ഒരു രോഗത്തെയും അല്ലാഹു ഇറക്കിയിട്ടില്ല." (ബു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أُسَامَةَ بْنِ شَرِيكٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ كَأَنَّمَا عَلَى رُءُوسِهِمُ الطَّيْرُ، فَسَلَّمْتُ ثُمَّ قَعَدْتُ، فَجَاءَ الْأَعْرَابُ مِنْ هَا هُنَا وَهَا هُنَا، فَقَالُوا: يَا رَسُولَ اللهِ، أَنَتَدَاوَى؟ فَقَالَ: "تَدَاوَوْا، فَإِنَّ اللهَ عَزَّ وَجَلَّ لَمْ يَضَعْ دَاءً إِلَّا وَضَعَ لَهُ دَوَاءً، غَيْرَ دَاءٍ وَاحِدٍ: الْهَرَمُ". (د,ت,جه)', 'ഉസാമതുബ്നു ശരീക്(റ): ഞാൻ നബി(സ)യുടെയും സ്വഹാബികളുടെയും അടുക്കലേക്ക് ചെന്നു. സ്വഹാബികൾ തങ്ങളുടെ തലകൾക്കു മുകളിൽ പക്ഷിയിരിക്കുന്നതു പോലെ (നിശബ്ദർ) ആയിരുന്നു. ഞാൻ സലാം ചൊല്ലി അവിടെയിരുന്നു. അന്നേരം വ്യത്യസ്ത സ്ഥലങ്ങളിൽ നിന്ന് ചില അഅ്റാബികൾ അങ്ങോട്ട് വന്നു. അവർ ചോദിച്ചു: നബിയേ, ഞങ്ങൾ ചികിത്സ തേടട്ടെയോ? നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ചികിത്സ തേടിക്കോളൂ. കാരണം അല്ലാഹു ഒരു രോഗത്തെയും അതിനുള്ള ചികിത്സ കൂടാതെ വെച്ചിട്ടില്ല, ഒന്നൊഴികെ. അത് വാർധക്യമാണ്." (ദ,തു,ജ)', 'أُسَامَةَ بْنِ شَرِيكٍ', 'ഉസാമതുബ്നു ശരീക്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 629, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أُسَامَةَ بْنِ شَرِيكٍ الثَّعْلَبِي رَضِيَ اللهُ عَنْهُ قَالَ: قَالَتِ الْأَعْرَابُ: يَا رَسُولَ اللهِ، أَلَا نَتَدَاوَى؟ قَالَ: "نَعَمْ، يَا عِبَادَ اللهِ تَدَاوَوْا، فَإِنَّ اللهَ لَمْ يَضَعْ دَاءً إِلَّا وَضَعَ لَهُ شِفَاءً – أَوْ قَالَ: دَوَاءً – إِلَّا دَاءً وَاحِدًا". قَالُوا: يَا رَسُولَ اللهِ، وَمَا هُوَ؟ قَالَ: "الْهَرَمُ". قَالَ ترمدي وَهَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'ഉസാമതുബ്നു ശരീക്കിസ്സഅ്ലബി(റ): കാട്ടറബികൾ ചോദിച്ചു: റസൂലേ, ഞങ്ങൾ ചികിത്സ തേടട്ടെയോ? നബി(സ) പറഞ്ഞു: "അതെ. നിങ്ങൾ ചികിത്സ തേടുക. കാരണം അല്ലാഹു ഒരു രോഗത്തെയും ശമനം കൂടാതെ - അല്ലെങ്കിൽ ചികിത്സ കൂടാതെ - വെച്ചിട്ടില്ല. ഒരു രോഗമൊഴികെ." അവർ ചോദിച്ചു: ഏതാണത്? നബി(സ) പറഞ്ഞു: "വാർധക്യം." (ദ,തു,ന,ജ)', 'أُسَامَةَ بْنِ شَرِيكٍ الثَّعْلَبِي', 'ഉസാമതുബ്നു ശരീക്കിസ്സഅ്ലബി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 630, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ يَعْمَرَ السَّعْدِي رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: يَا رَسُولَ اللهِ، أَرَأَيْتَ رُقًى نَسْتَرْقِيهَا، وَدَوَاءً نَتَدَاوَى بِهِ، وَتُقَاةً نَتَّقِيهَا، هَلْ تَرُدُّ مِنْ قَدَرِ اللهِ شَيْئًا؟ قَالَ: "هِيَ مِنْ قَدَرِ اللهِ". (ت,جه)', 'യഅ്മുറസ്സഅ്ദി(റ): ഞാൻ നബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ തിരുദൂതരേ, ഞങ്ങൾ മന്ത്രിക്കുന്ന മന്ത്രങ്ങളെക്കുറിച്ചും, ഞങ്ങൾ ഉപയോഗിക്കുന്ന മരുന്നുകളെക്കുറിച്ചും, രക്ഷക്കായി ഞങ്ങൾ ചെയ്യാറുള്ള മറ്റു രക്ഷാ കവചങ്ങളെക്കുറിച്ചും താങ്കളുടെ അഭിപ്രായമെന്താണ്? അവ അല്ലാഹുവിന്റെ വിധിയിൽനിന്ന് വല്ലതിനെയും തട്ടിക്കളയുമോ? നബി(സ) പറഞ്ഞു: "അവയും അല്ലാഹുവിന്റെ വിധിയിൽ പെട്ടതാണ്." (തു,ജ)', 'يَعْمَرَ السَّعْدِي', 'യഅ്മുറസ്സഅ്ദി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 630, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَتْ أُمُّ سَلَمَةَ: يَا رَسُولَ اللهِ، لَا يَزَالُ يُصِيبُكَ كُلَّ عَامٍ وَجَعٌ مِنَ الشَّاةِ الْمَسْمُومَةِ الَّتِي أَكَلْتَ، قَالَ: "مَا أَصَابَنِي شَيْءٌ مِنْهَا إِلَّا وَهُوَ مَكْتُوبٌ عَلَيَّ وَآدَمُ فِي طِينَتِهِ". [ز: في سنده ضعيف] (جه)', 'ഇബ്നുഉമർ(റ): ഉമ്മുസലമ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടന്ന് തിന്ന വിഷം കലർത്തപ്പെട്ട ആട് കാരണത്താൽ എല്ലാ വർഷവും അവിടത്തേക്ക് വേദനയുണ്ടാവുന്നുണ്ടല്ലോ? നബി(സ) പറഞ്ഞു: "ആദം നബി(അ) മണ്ണായിരുന്ന അവസ്ഥയിൽ എന്റെമേൽ എഴുതപ്പെട്ടതല്ലാതെ, അതിൽ നിന്ന് ഒന്നും എനിക്ക് ഏശുന്നില്ല." പരമ്പരയിൽ ഭംഗമുള്ള നിവേദകനുണ്ട്. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 630, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُوعَكُ، فَمَسِسْتُهُ بِيَدِي، فَقُلْتُ: يَا رَسُولَ اللهِ إِنَّكَ لَتُوعَكُ وَعْكًا شَدِيدًا؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَجَلْ، إِنِّي أُوعَكُ كَمَا يُوعَكُ رَجُلَانِ مِنْكُمْ". قَالَ: فَقُلْتُ: ذَلِكَ أَنَّ لَكَ أَجْرَيْنِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَجَلْ". ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ مُسْلِمٍ يُصِيبُهُ أَذًى، مِنْ مَرَضٍ فَمَا سِوَاهُ، إِلَّا حَطَّ اللهُ بِهِ سَيِّئَاتِهِ كَمَا تَحُطُّ الشَّجَرَةُ وَرَقَهَا". (ق)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബ(സ)യുടെ സന്നിധിയിൽ ഞാൻ പ്രവേശിച്ചു. അവിടുത്തേക്ക് ശക്തമായി പനിക്കുന്നുണ്ടായിരുന്നു. തിരുമേനി(സ)യുടെ പുണ്യശരീരത്തിൽ ഞാൻ കൈവെച്ചുനോക്കി. ഞാൻ പറഞ്ഞു: റസൂലേ, അവിടുത്തെ ശരീരത്തിൽ കഠിനമായ ചൂടുണ്ടല്ലോ. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അതെ, നിങ്ങളിൽ നിന്ന് രണ്ടുപേർക്ക് പനിക്കുന്നതിന് തുല്യമായി എനിക്ക് പനിക്കുന്നുണ്ട്." അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) പറയുന്നു: ഞാൻ ചോദിച്ചു: അതായത് അങ്ങേക്ക് രണ്ട് കൂലിയുണ്ടോ നബിയേ? നബി(സ) പറഞ്ഞു: "അതെ." പിന്നീട് നബി(സ) പറഞ്ഞു: "രോഗങ്ങളും സമാനമായ ബുദ്ധിമുട്ടുകളും അനുഭവിക്കുന്ന ഓരോ മുസ്ലിമിന്റെയും ദോഷങ്ങളെ, വൃക്ഷം അതിന്റെ ഇലകളെ കൊഴിക്കുന്നതു പോലെ അല്ലാഹു മായിച്ചുകളയുക തന്നെ ചെയ്യും." (ബു,മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 630, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ، وَلَا وَصَبٍ وَلَا هَمٍّ وَلَا حُزْنٍ وَلَا أَذًى وَلَا غَمٍّ. حَتَّى الشَّوْكَةِ يُشَاكُهَا، إِلَّا كَفَّرَ اللهُ بِهَا مِنْ خَطَايَاهُ". (خ)', 'അബൂസഇൗദുൽ ഖുദ്രി(റ), അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരു മുസ്ലിമിന് സംഭവിക്കുന്ന ഓരോ രോഗവും ക്ഷീണവും ദുഃഖവും വ്യസനവും വ്യഥയും ആധിയും അവന് തറക്കുന്ന മുള്ള് പോലും കാരണമായി അല്ലാഹു അവന്റെ ദോഷങ്ങൾ പൊറുക്കുന്നതാണ്." (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ، وَعَنْ أَبِي هُرَيْرَةَ', 'അബൂസഇൗദുൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَثَلُ الْمُؤْمِنِ كَمَثَلِ الْخَامَةِ مِنَ الزَّرْعِ، مِنْ حَيْثُ أَتَتْهَا الرِّيحُ كَفَأَتْهَا، فَإِذَا اعْتَدَلَتْ تَكَفَّأُ بِالْبَلَاءِ. وَالْفَاجِرُ كَالْأَرْزَةِ، صَمَّاءَ مُعْتَدِلَةً، حَتَّى يَقْصِمَهَا اللهُ إِذَا شَاءَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സത്യവിശ്വാസിയുടെ ഉപമ പുതുതായി വളർന്ന ഒരു ചെടിയാണ്. കാറ്റ് തട്ടിയാൽ അതങ്ങോട്ടുമിങ്ങോട്ടും ആടിക്കൊണ്ടിരിക്കും. കാറ്റ് അടങ്ങിയാൽ അത് നിവർന്നുനിൽക്കും. ദുർമാർഗ്ഗിയുടെ ഉപമ ''ഉർസത്ത്'' ചെടിയാണ്. അത് ഉറച്ചുതന്നെ നിൽക്കും. അവസാനം അല്ലാഹു ഉദ്ദേശിക്കുമ്പോൾ അതിനെ കടപുഴക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يُرِدِ اللهُ بِهِ خَيْرًا يُصِبْ مِنْهُ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "ആരെക്കൊണ്ടെങ്കിലും അല്ലാഹു നന്മ ഉദ്ദേശിച്ചിട്ടുണ്ടെങ്കിൽ അവനെ അല്ലാഹു പരീക്ഷിക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ أَحَدًا أَشَدَّ عَلَيْهِ الْوَجَعُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ആഇശ(റ): നബി(സ)യേക്കാളും കഠിനമായ വേദന സഹിച്ച ആരെയും ഞാൻ കണ്ടിട്ടില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا مَثَلُ الْمَرِيضِ إِذَا بَرَأَ وَصَحَّ، كَالْبَرْدَةِ تَقَعُ مِنَ السَّمَاءِ، فِي صَفَائِهَا وَلَوْنِهَا". (ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "സുഖം പ്രാപിക്കുകയും ആരോഗ്യവാനാവുകയും ചെയ്ത ഒരു രോഗിയുടെ ഉപമ, ആകാശത്തിൽ നിന്ന് വീണ ഒരു ഹിമക്കഷ്ണം പോലെയാണ്, അതിന്റെ വൃത്തിയിലും നിറത്തിലും." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: قَالَ جَاءَنِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي لَيْسَ بِرَاكِبِ بَغْلٍ وَلَا بِرْذَوْنٍ. (خ)', 'ജാബിർ(റ): തിരുമേനി(സ) എന്നെ സന്ദർശിക്കാൻ വന്നത് കോവർ കഴുതയുടെ പുറത്തോ കുതിരപ്പുറത്തോ കയറിയായിരുന്നില്ല (നടന്നായിരുന്നുവെന്ന് സാരം). (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 632, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْمُسْلِمَ إِذَا عَادَ أَخَاهُ الْمُسْلِمَ لَمْ يَزَلْ فِي خُرْفَةِ الْجَنَّةِ حَتَّى يَرْجِعَ". (م)', 'സൗബാൻ(റ): നബി(സ) പറഞ്ഞു: "ഒരു മുസ്ലിം തന്റെ സഹോദരനായ മറ്റൊരു മുസ്ലിമിനെ രോഗസന്ദർശനം നടത്തിയാൽ അവിടെ നിന്നും മടങ്ങുന്നത് വരെ അവൻ സ്വർഗീയ തോപ്പുകളിലായിരിക്കും." (മു)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 632, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ عَزَّ وَجَلَّ يَقُولُ يَوْمَ الْقِيَامَةِ: يَا ابْنَ آدَمَ مَرِضْتُ فَلَمْ تَعُدْنِي. قَالَ: يَا رَبِّ كَيْفَ أَعُودُكَ وَأَنْتَ رَبُّ الْعَالَمِينَ؟ قَالَ: أَمَا عَلِمْتَ أَنَّ عَبْدِي فُلَانًا مَرِضَ فَلَمْ تَعُدْهُ؟ أَمَا عَلِمْتَ أَنَّكَ لَوْ عُدْتَهُ لَوَجَدْتَنِي عِنْدَهُ؟ يَا ابْنَ آدَمَ اسْتَطْعَمْتُكَ فَلَمْ تُطْعِمْنِي. قَالَ: يَا رَبِّ وَكَيْفَ أُطْعِمُكَ وَأَنْتَ رَبُّ الْعَالَمِينَ؟ قَالَ: أَمَا عَلِمْتَ أَنَّهُ اسْتَطْعَمَكَ عَبْدِي فُلَانٌ فَلَمْ تُطْعِمْهُ؟ أَمَا عَلِمْتَ أَنَّكَ لَوْ أَطْعَمْتَهُ لَوَجَدْتَ ذَلِكَ عِنْدِي؟ [يَا] ابْنَ آدَمَ اسْتَسْقَيْتُكَ فَلَمْ تَسْقِنِي. قَالَ: يَا رَبِّ كَيْفَ أَسْقِيكَ وَأَنْتَ رَبُّ الْعَالَمِينَ؟ قَالَ: اسْتَسْقَاكَ عَبْدِي فُلَانٌ فَلَمْ تَسْقِهِ، أَمَا إِنَّكَ لَوْ سَقَيْتَهُ وَجَدْتَ ذَلِكَ عِنْدِي". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ അല്ലാഹു പറയും: ആദമിന്റെ പുത്രാ, ഞാൻ രോഗിയായപ്പോൾ നീയെന്നെ സന്ദർശിച്ചിട്ടില്ല. മനുഷ്യൻ പറയും: റബ്ബേ, ലോകരക്ഷിതാവായ നിന്നെ ഞാനെങ്ങനെ സന്ദർശിക്കാനാണ്? അല്ലാഹു പറയും: എന്റെ ഇന്നാലിന്ന അടിമ രോഗിയായതറിഞ്ഞിട്ടും നീയവനെ സന്ദർശിച്ചിട്ടില്ലല്ലോ? നീയവനെ സന്ദർശിച്ചിരുന്നെങ്കിൽ അവന്റടുക്കൽ എന്നെ കാണാമായിരുന്നുവെന്നത് നിനക്കറിയില്ലേ? ഹേ ആദമിന്റെ പുത്രാ, ഞാൻ നിന്നോട് ഭക്ഷണം തേടി. പക്ഷേ, നീയെന്നെ ഭക്ഷിപ്പിച്ചില്ല. മനുഷ്യൻ പറയും: എന്റെ റബ്ബേ, ഞാനെങ്ങനെ നിന്നെ ഭക്ഷിപ്പിക്കാനാണ്? നീ ലോകരക്ഷിതാവല്ലെയോ? അല്ലാഹു പറയും: എന്റെ ഇന്നാലിന്ന അടിമ നിന്നോട് ഭക്ഷണം തേടിയപ്പോൾ നീയവനെ ഭക്ഷിപ്പിച്ചിട്ടില്ലെന്ന് നിനക്കറിയില്ലേ? അവനെ നീ ഭക്ഷിപ്പിച്ചിരുന്നുവെങ്കിൽ അതിനെ നിനക്ക് എന്റെയടുക്കൽ ലഭിക്കുമായിരുന്നുവെന്ന് നിനക്കറിയില്ലേ? ഹേ, ആദമിന്റെ പുത്രാ, ഞാൻ നിന്നോട് വെള്ളം ചോദിച്ചു. പക്ഷേ, നീയെന്നെ കുടിപ്പിച്ചില്ല. മനുഷ്യൻ പറയും: എന്റെ റബ്ബേ, ലോകരക്ഷിതാവായ നിന്നെ ഞാനെങ്ങനെ കുടിപ്പിക്കാനാണ്? അല്ലാഹു പറയും: എന്റെ ഇന്നാലിന്ന അടിമ നിന്നോട് വെള്ളം ചോദിച്ചപ്പോൾ നീയവനെ കുടിപ്പിച്ചില്ലല്ലോ? നീയവനെ കുടിപ്പിച്ചിരുന്നുവെങ്കിൽ അതിനെ നിനക്ക് എന്റെയടുക്കൽ എത്തിക്കുമായിരുന്നില്ലേ? (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'يَا', null, 632, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَادَ رَجُلًا مِنْ وَعْكٍ كَانَ بِهِ، فَقَالَ: "أَبْشِرْ فَإِنَّ اللهَ يَقُولُ: هِيَ نَارِي، أُسَلِّطُهَا عَلَى عَبْدِي الْمُذْنِبِ، لِتَكُونَ حَظَّهُ مِنَ النَّارِ". (ت)', 'അബൂഹുറൈറ(റ): പനിയും വേദനയുമുള്ള ഒരാളെ നബി(സ) സന്ദർശിച്ചു. അപ്പോൾ അയാളോട് പറഞ്ഞു: "നീ സന്തോഷിക്കുക, കാരണം അല്ലാഹു പറയുന്നു: അത് എന്റെ തീയാണ്. ഞാനതിന് എന്റെ ദോശിയായ അടിമയുടെ മേൽ ആധിപത്യം നൽകും, അതവന്റെ നരകത്തിൽ നിന്നുള്ള ഓഹരിയാകാൻ വേണ്ടി." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 632, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَتَى مَرِيضًا أَوْ أُتِيَ بِهِ قَالَ: "أَذْهِبِ الْبَاسَ رَبَّ النَّاسِ، اشْفِ وَأَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا". (خ)', 'ആഇശ(റ): തിരുമേനി(സ) ഒരു രോഗിയുടെ അടുക്കൽ ചെന്നാൽ, അല്ലെങ്കിൽ അവിടുത്തെ സമീപത്തേക്ക് ഒരു രോഗിയെ കൊണ്ടുവന്നാൽ അവിടന്ന് ഇങ്ങനെ പ്രാർത്ഥിക്കുമായിരുന്നു: "മനുഷ്യരുടെ നാഥാ, ഈ അവശതയെ ദൂരീകരിക്കുകയും ഇദ്ദേഹത്തിന്റെ എല്ലാ രോഗങ്ങളെയും സുഖപ്പെടുത്തുകയും ചെയ്യേണമേ. രോഗം സുഖപ്പെടുത്തുന്നവൻ നീയാണ്. നിന്റേതല്ലാത്ത മറ്റൊരു ശിഫയില്ല. ഒരു രോഗത്തെയും ബാക്കിവെക്കാത്ത ശിഫ നൽകേണമേ." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 633, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ عَبْدٍ مُسْلِمٍ يَعُودُ مَرِيضًا لَمْ يَحْضُرْ أَجَلُهُ، فَيَقُولُ سَبْعَ مَرَّاتٍ: أَسْأَلُ اللهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ: أَنْ يَشْفِيَكَ، إِلَّا عُوفِيَ". (د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "മരണാസന്നനല്ലാത്ത ഒരു രോഗിയുടെ അടുക്കൽ ചെന്ന് ഏതെങ്കിലും ഒരു മുസ്ലിമായ അടിമ, മഹോന്നതനും ഉന്നത സിംഹാസനത്തിന്റെ രക്ഷാധികാരിയുമായ അല്ലാഹുവിനോട് നിനക്ക് ശമനം നൽകാൻ ഞാൻ ചോദിക്കുന്നു എന്ന് ഏഴ് പ്രാവശ്യം പറഞ്ഞാൽ, അവന് ശമനം നൽകപ്പെടാതിരിക്കില്ല." (ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 633, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَخَلْتُمْ عَلَى الْمَرِيضِ فَنَفِّسُوا لَهُ فِي أَجَلِهِ، فَإِنَّ ذَلِكَ لَا يَرُدُّ شَيْئًا، وَيُطَيِّبُ نَفْسَهُ". (ت,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ രോഗിയുടെയടുക്കൽ ചെന്നാൽ, അവന്റെ ദീർഘായുസ്സിന് വേണ്ടി പ്രാർത്ഥിക്കണം. തീർച്ചയായും അത് ഒന്നിനെയും തട്ടിക്കളയുകയില്ല, എന്നാൽ അവന്റെ മനസ്സിനെ അത് സന്തോഷിപ്പിക്കും." (തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 633, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ قَالَ لِبَعْضِ أَصْحَابِهِ: أَلَا أُرِيكَ امْرَأَةً مِنْ أَهْلِ الْجَنَّةِ، قَالَ: بَلَى، قَالَ: هَذِهِ الْمَرْأَةُ السَّوْدَاءُ أَتَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنِّي أُصْرَعُ، وَإِنِّي أَتَكَشَّفُ فَادْعُ اللهَ لِي، قَالَ: "إِنْ شِئْتِ صَبَرْتِ وَلَكِ الْجَنَّةُ، وَإِنْ شِئْتِ دَعَوْتُ اللهَ أَنْ يُعَافِيَكِ". فَقَالَتْ: إِنِّي أَصْبِرُ، فَقَالَتْ: إِنِّي أَتَكَشَّفُ، فَادْعُ اللهَ أَنْ لَا أَتَكَشَّفَ، فَدَعَا لَهَا. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹം തന്റെ കൂട്ടുകാരിലൊരാളോട് ചോദിച്ചു: സ്വർഗ്ഗാവകാശിയായ ഒരു സ്ത്രീയെ ഞാൻ കാണിച്ചുതരട്ടെയോ? അദ്ദേഹം പറഞ്ഞു: ശരി. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഈ കറുത്ത സ്ത്രീയാണത്. തിരുമേനി(സ)യുടെയടുക്കൽ വന്നിട്ട് അവർ പറഞ്ഞു: ഞാൻ ചിലപ്പോൾ അപസ്മാരമിളകി നിലത്തുവീഴും. എന്റെ വസ്ത്രം നീങ്ങി ശരീരം വെളിപ്പെടും. അവിടന്ന് എനിക്കുവേണ്ടി പ്രാർത്ഥിച്ചാലും! തിരുമേനി(സ) അരുളി: "നീ ക്ഷമ കൈക്കൊള്ളുന്ന പക്ഷം സ്വർഗ്ഗം കരസ്ഥമാക്കാം. അല്ലെങ്കിൽ നിന്റെ രോഗശമനത്തിനായി ഞാനല്ലാഹുവിനോട് പ്രാർത്ഥിക്കാം." അവർ പറഞ്ഞു: ഞാൻ ക്ഷമ കൈക്കൊള്ളാം. ശേഷം ആ സ്ത്രീ പറഞ്ഞു: പക്ഷേ, അബോധാവസ്ഥയിൽ എന്റെ ശരീരം വെളിപ്പെട്ടുപോകുന്നു. അങ്ങനെ ശരീരം വെളിപ്പെടുത്താതിരിക്കാനായി അങ്ങ് അല്ലാഹുവിനോട് പ്രാർത്ഥിച്ചാലും. അപ്പോൾ തിരുമേനി(സ) ആ സ്ത്രീക്കു വേണ്ടി പ്രാർത്ഥിച്ചു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 633, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ اللهَ تَعَالَى قَالَ: إِذَا ابْتَلَيْتُ عَبْدِي بِحَبِيبَتَيْهِ فَصَبَرَ عَوَّضْتُهُ مِنْهُمَا الْجَنَّةَ، يُرِيدُ عَيْنَيْهِ". (خ)', 'അനസുബ്നു മാലിക്(റ): തിരുമേനി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹു പറഞ്ഞു: ഞാൻ എന്റെ ദാസനെ അവന് ഏറ്റവും പ്രിയപ്പെട്ട രണ്ടു സാധനങ്ങളിൽ പരീക്ഷിക്കുകയും അവൻ ക്ഷമ കൈക്കൊള്ളുകയും ചെയ്താൽ അവ രണ്ടിനും പകരമായി അവനു നാം സ്വർഗ്ഗം നൽകും. പ്രിയപ്പെട്ട രണ്ടുസാധനങ്ങൾ എന്നത് കൊണ്ട് അല്ലാഹു ഉദ്ദേശിക്കുന്നത് അവന്റെ രണ്ടു കണ്ണുകളാണ്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 634, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُ الدَّوَاءِ الْقُرْآنُ". [ز: في إسناده ضعيف] (جه)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "മരുന്നുകളിൽ ഏറ്റവും ഉത്തമമായത് ഖുർആനാണ്." പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 634, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: هَجَّرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَهَجَّرْتُ، فَصَلَّيْتُ ثُمَّ جَلَسْتُ، فَالْتَفَتَ إِلَيَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "اشِكَمْتْ دَرْدْ". قلت: نعم، يا رسول الله. قال: "قُمْ فَصَلِّ، فَإِنَّ فِي الصَّلَاةِ شِفَاءً". [ز: في سنده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) നിസ്കരിക്കാനായി വേഗം പോയി, അപ്പോൾ ഞാനും വേഗം പോയി. അങ്ങനെ ഞാൻ നിസ്കരിച്ച് അവിടെ ഇരുന്നു. എന്നിട്ട് ഞാൻ നബി(സ)യുടെ ഭാഗത്തേക്ക് തിരിഞ്ഞു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "വയറിന് രോഗമുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ, തിരുദൂതരേ. നബി(സ) പറഞ്ഞു: "നീ എഴുന്നേറ്റ് നിസ്കരിക്കുക, കാരണം തീർച്ചയായും നിസ്കാരത്തിൽ രോഗശമനമുണ്ട്." പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 634, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ قَتَادَةَ بْنِ النُّعْمَانِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَحَبَّ اللهُ عَبْدًا حَمَاهُ الدُّنْيَا، كَمَا يَظَلُّ أَحَدُكُمْ يَحْمِي سَقِيمَهُ الْمَاءَ". قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ. (ت)', 'ഖതാദതുബ്നു നുഅ്മാൻ(റ): നബി(സ) പറഞ്ഞു: "ഒരു വ്യക്തിയെ അല്ലാഹു ഇഷ്ടപ്പെട്ടാൽ ദുൻയാവിനെ അല്ലാഹു അയാൾക്ക് ഒഴിവാക്കിക്കൊടുക്കും. നിങ്ങളിലൊരാൾ തന്റെ രോഗിയിൽ നിന്ന് വെള്ളം ഒഴിവാക്കുന്നതു പോലെ." (തു)', 'قَتَادَةَ بْنِ النُّعْمَانِ', 'ഖതാദതുബ്നു നുഅ്മാൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 634, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أُمِّ الْمُنْذِرِ بِنْتِ قَيْسٍ الْأَنْصَارِيَّةِ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ عَلِيٌّ رَضِيَ اللهُ عَنْهُ، وَعَلِيٌّ نَاقِهٌ، وَلَنَا دَوَالِي مُعَلَّقَةٌ، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ مِنْهَا، وَقَامَ عَلِيٌّ لِيَأْكُلَ، فَطَفِقَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لِعَلِيٍّ: "مَهْ، إِنَّكَ نَاقِهٌ". حَتَّى كَفَّ عَلِيٌّ رَضِيَ اللهُ عَنْهُ. قَالَتْ: وَصَنَعْتُ شَعِيرًا وَسِلْقًا فَجِئْتُ بِهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَلِيُّ، أَصِبْ مِنْ هَذَا فَهُوَ أَنْفَعُ لَكَ". (د,ت,جه)', 'ഉമ്മുൽമുൻദിർ ബിൻത് ഖൈസുൽ അൻസാരിയ(റ): നബി(സ)യും അലി(റ)വും എന്റടുക്കൽ വന്നു. അലി(റ) രോഗം ശമിച്ചയുടനെയുള്ള ക്ഷീണത്തിലായിരുന്നു. ഞങ്ങൾക്കുണ്ടായ ധാരാളം ഈത്തപ്പഴങ്ങളുള്ള കുലകൾ അവിടെയുണ്ടായിരുന്നു. അപ്പോൾ നബി(സ) അതിൽനിന്നും എടുത്ത് തിന്നാൻ ആഞ്ഞു. അലി(റ)വും തിന്നുവാൻ വേണ്ടി എഴുന്നേറ്റു. അപ്പോൾ നബി(സ) അലി(റ)വിനോട് പറഞ്ഞുതുടങ്ങി: "അരുത്, താങ്കൾ ക്ഷീണിതനാണ്." അപ്പോൾ അലി(റ) വിട്ടു നിന്നു. ശേഷം ഞാൻ ബാർലിയും ബീറ്റ്റൂട്ടും ഉണ്ടാക്കുകയും അത് കൊണ്ട്വരികയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അലീ, നിങ്ങൾ ഇതിൽ നിന്ന് ഭക്ഷിച്ചു കൊള്ളുക. ഇതാണ് നിങ്ങൾക്ക് ഏറ്റവും നല്ലത്." (ദ,തു,ജ)', 'أُمِّ الْمُنْذِرِ بِنْتِ قَيْسٍ الْأَنْصَارِيَّةِ', 'ഉമ്മുൽമുൻദിർ ബിൻത് ഖൈസുൽ അൻസാരിയ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 634, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ صُهَيْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَبَيْنَ يَدَيْهِ خُبْزٌ وَتَمْرٌ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ادْنُ فَكُلْ". فَأَخَذْتُ آكُلُ مِنَ التَّمْرِ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَأْكُلُ تَمْرًا وَبِكَ رَمَدٌ". قَالَ: فَقُلْتُ: إِنِّي أَمْضُغُ مِنْ نَاحِيَةٍ أُخْرَى. فَتَبَسَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'സ്വുഹൈബ്(റ): നബി(സ)യുടെ സന്നിധിയിലേക്ക് ഞാൻ ചെന്നു. അവിടെ കാരക്കയും റൊട്ടിയുമുണ്ടായിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അടുത്ത് വന്ന് ഇത് തിന്ന് കൊള്ളുക." ഞാൻ കാരക്ക തിന്നാൻ തുടങ്ങി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് ചെങ്കണ്ണ് ഉണ്ടായിട്ടും നിങ്ങൾ കാരക്ക ഭക്ഷിക്കുകയാണോ?" സ്വുഹൈബ്(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: ഞാൻ മറ്റേഭാഗം കൊണ്ടാണ് ചവക്കുന്നത്. അന്നേരം നബി(സ) പുഞ്ചിരി തൂകി. (ജ)', 'صُهَيْبٍ', 'സ്വുഹൈബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْعَجْوَةُ مِنَ الْجَنَّةِ، وَفِيهَا شِفَاءٌ مِنَ السُّمِّ. وَالْكَمْأَةُ مِنَ الْمَنِّ، وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ". (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അജ്വ ഈത്തപ്പഴം സ്വർഗ്ഗത്തിൽ നിന്നുള്ളതാണ്. അതിൽ വിഷത്തിന് ശമനമുണ്ട്. കറുത്ത കൂൺ മന്നിൽ (ബനൂഈസ്രാഈല്യർക്ക് അല്ലാഹു ഇറക്കിക്കൊടുത്ത വിഭവം) പെട്ടതാണ്. അതിന്റെ വെള്ളത്തിൽ കണ്ണേറിന് ശമനമുണ്ട്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي سَعِيدٍ وَجَابِرٍ رَضِيَ اللهُ عَنْهُمَا قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْكَمْأَةُ مِنَ الْمَنِّ، وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ. وَالْعَجْوَةُ مِنَ الْجَنَّةِ، وَهِيَ شِفَاءٌ مِنَ الْجَنَّةِ". (جه)', 'അബൂസഇൗദ്(റ), ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "കറുത്ത കൂൺ മന്നിൽ പെട്ടതാണ്. അതിന്റെ നീര് കണ്ണേറിന് ശമനമാണ്. അജ്വ സ്വർഗ്ഗത്തിൽ പെട്ടതാണ്. അത് ഭ്രാന്തിന് ശമനമാണ്." (ജ)', 'أَبِي سَعِيدٍ وَجَابِرٍ', 'അബൂസഇൗദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ سَعِيدِ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْكَمْأَةُ مِنَ الْمَنِّ الَّذِي أَنْزَلَ اللهُ عَلَى بَنِي إِسْرَائِيلَ، وَمَاؤُهَا شِفَاءُ الْعَيْنِ". (ق,ت,جه)', 'സഈദുബ്നു സൈദ്(റ): നബി(സ) പറഞ്ഞു: "കറുത്ത കൂൺ ബനൂഇസ്റാഇൗലിന് അല്ലാഹു ഇറക്കി കൊടുത്ത മന്നിൽ പെട്ടതാണ്. അതിന്റെ വെള്ളം കണ്ണേറിന് ശമനമാണ്." (ബു,മു,തു,ജ)', 'سَعِيدِ بْنِ زَيْدٍ', 'സഈദുബ്നു സൈദ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 635, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَتَحَدَّثُ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرْنَا الْكَمْأَةَ، فَقَالُوا: هُوَ جُدَرِيُّ الْأَرْضِ. فَنُمِيَ الْحَدِيثُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "الْكَمْأَةُ مِنَ الْمَنِّ، وَالْعَجْوَةُ مِنَ الْجَنَّةِ، وَهِيَ شِفَاءٌ مِنَ السُّمِّ". (ت,جه)', 'അബൂഹുറൈറ(റ): ഞങ്ങൾ നബി(സ)യുടെ അടുക്കൽ സംസാരിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. ഞങ്ങൾ കൂണിനെപ്പറ്റി സംസാരിച്ചു. അന്നേരം അവർ പറഞ്ഞു: അത് ഭൂമിയിൽ പൊട്ടിമുളക്കുന്നതാണ്. ഞങ്ങളുടെ സംസാരം നബി(സ)യുടെ അടുക്കലേക്കെത്തി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "കൂൺ മന്നിൽ പെട്ടതാണ്. അജ്വ സ്വർഗ്ഗത്തിൽ പെട്ടതാണ്. അത് വിഷത്തിന് ശമനമാണ്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 636, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ رَافِعِ بْنِ عَمْرٍو الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْعَجْوَةُ وَالصَّخْرَةُ مِنَ الْجَنَّةِ". (جه)', 'റാഫിഉബ്നു അംറിൽ മുസനി(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അജ്വയും സ്വഖ്റതും (ബൈത്തുൽ മുഖദ്ദസിലുള്ള പാറ) സ്വർഗ്ഗത്തിൽ നിന്നുള്ളതാണ്." (ജ)', 'رَافِعِ بْنِ عَمْرٍو الْمُزَنِيِّ', 'റാഫിഉബ്നു അംറിൽ മുസനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 636, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ قَتَادَةَ قَالَ: حُدِّثْتُ أَنَّ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَخَذْتُ ثَلَاثَةَ أَكْمُؤٍ أَوْ خَمْسًا أَوْ سَبْعًا، فَعَصَرْتُهُنَّ، فَجَعَلْتُ مَاءَهُنَّ فِي قَارُورَةٍ، فَكَحَلْتُ بِهِ جَارِيَةً لِي، فَبَرَأَتْ. (ت)', 'ഖതാദ(റ): എന്നോട് ഹദീസ് പറയപ്പെട്ടു: അബൂഹുറൈറ(റ) പറഞ്ഞു: ഞാൻ മൂന്നോ അഞ്ചോ ഏഴോ കൂണുകൾ എടുത്തു. എന്നിട്ട് അത് പിഴിഞ്ഞു. അതിന്റെ വെള്ളം ഒരു ഗ്ലാസിലാക്കി. എന്റെ അടിമസ്ത്രീക്ക് ഞാൻ അതുകൊണ്ട് സുറുമയിട്ട് കൊടുത്തു. അനന്തരം അവളുടെ രോഗം സുഖമായി. (തു)', 'قَتَادَةَ قَالَ', 'ഖതാദ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 636, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرِضْتُ مَرَضًا أَتَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي، فَوَضَعَ يَدَهُ بَيْنَ ثَدْيَيَّ حَتَّى وَجَدْتُ بَرْدَهَا عَلَى فُؤَادِي، فَقَالَ: "إِنَّكَ رَجُلٌ مَفْئُودٌ، ائْتِ الْحَارِثَ بْنَ كَلَدَةَ أَخَا ثَقِيفٍ، فَإِنَّهُ رَجُلٌ يَتَطَبَّبُ، فَلْيَأْخُذْ سَبْعَ تَمَرَاتٍ مِنْ عَجْوَةِ الْمَدِينَةِ، فَلْيَجَأْهُنَّ بِنَوَاهُنَّ، ثُمَّ لِيَلُدَّكَ بِهِنَّ". (د)', 'സഅ്ദുബ്നുഅബീവഖാസ്(റ): ഞാൻ രോഗം പിടിച്ച് കിടപ്പിലായി. അന്നേരം റസൂലുല്ലാഹി(സ) എന്നെ സന്ദർശിക്കാൻ വന്നു. തിരുമേനി(സ) എന്റെ നെഞ്ചുകൾക്കിടയിൽ കൈ വെച്ചു. അവിടത്തെ കൈയിന്റെ തണുപ്പ് എന്റെ ഹൃദയത്തിൽ പതിക്കുന്നത് ഞാൻ അനുഭവിച്ചു. എന്നിട്ട് പറഞ്ഞു: "നീ ഹൃദ്രോഗ ബാധിതനായിരിക്കുന്നു. സഖീഫിന്റെ സഹോദരനായ ഹാരിസുബ്നു കലദിന്റെയടുത്ത് നീ പോകുക. അദ്ദേഹം ചികിത്സിക്കുന്ന ആളാണ്. മദീനയിലെ അജ്വ ഇനത്തിൽപ്പെട്ട ഏഴ് കാരക്കകൾ എടുത്ത് അതിന്റെ കുരു സഹിതം പൊടിച്ച് ലദൂദാക്കി അദ്ദേഹം നിന്നെ കഴിപ്പിക്കട്ടെ." (ദ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നുഅബീവഖാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 636, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَصَبَّحَ سَبْعَ تَمَرَاتٍ عَجْوَةٍ لَمْ يَضُرَّهُ ذَلِكَ الْيَوْمَ سُمٌّ وَلَا سِحْرٌ". (ق,د)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും രാവിലെ ഏഴ് അജ്വ കാരക്കകൾ തിന്നാൽ ആ ദിവസം മാരണവും വിഷവും അവന്ന് ഏൽക്കുകയില്ല." (ബു,മു,ദ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 636, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ فِي عَجْوَةِ الْعَالِيَةِ شِفَاءً، وَإِنَّهَا تِرْيَاقٌ أَوَّلَ الْبُكْرَةِ". (م)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ആലിയയിലെ - മദീനയിലെ ഉയർന്ന പ്രദേശങ്ങളിലെ ഈത്തപ്പനത്തോട്ടങ്ങൾ - അജ്വ ഈത്തപ്പഴത്തിൽ ശമനമുണ്ട്. പ്രഭാതത്തിൽ കഴിച്ചാൽ വിഷത്തിനുള്ള മറുമരുന്നാണത്." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 636, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ أَخِي اسْتَطْلَقَ بَطْنُهُ؟ فَقَالَ: "اسْقِهِ عَسَلًا". فَسَقَاهُ، ثُمَّ جَاءَ فَقَالَ: يَا رَسُولَ اللهِ، قَدْ سَقَيْتُهُ عَسَلًا، فَلَمْ يَزِدْهُ إِلَّا اسْتِطْلَاقًا؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْقِهِ عَسَلًا". فَسَقَاهُ، ثُمَّ جَاءَهُ فَقَالَ: يَا رَسُولَ اللهِ، قَدْ سَقَيْتُهُ عَسَلًا، فَلَمْ يَزِدْهُ إِلَّا اسْتِطْلَاقًا؟ قَالَ: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَدَقَ اللهُ وَكَذَبَ بَطْنُ أَخِيكَ، اسْقِهِ عَسَلًا". فَسَقَاهُ عَسَلًا فَبَرَأَ. قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'അബൂസഈദ്(റ): ഒരാൾ നബി(സ)യുടെ സന്നിധിയിൽ വന്നു. എന്നിട്ട് പറഞ്ഞു: എന്റെ സഹോദരന് വയറിളക്കം ബാധിച്ചിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "അദ്ദേഹത്തെ തേൻ കുടിപ്പിക്കുക." അങ്ങനെ അദ്ദേഹത്തെ തേൻ കുടിപ്പിച്ചു. ശേഷം നബി(സ)യുടെ സന്നിധിയിൽ വന്ന് പറഞ്ഞു: റസൂലേ, ഞാൻ അദ്ദേഹത്തെ തേൻ കുടിപ്പിച്ചു. പക്ഷേ, വയറിളക്കം വർധിച്ചതേയുള്ളൂ. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അദ്ദേഹത്തിന് തേൻ കൊടുക്കുക." വീണ്ടും അദ്ദേഹം തന്റെ സഹോദരനെ തേൻ കുടിപ്പിച്ചു. തിരിച്ചുവന്നു പറഞ്ഞു: റസൂലേ, ഞാൻ സഹോദരന് തേൻ കൊടുത്തു. പക്ഷേ, അസുഖം വീണ്ടും വർധിച്ചു. അബൂസഈദ്(റ) പറയുന്നു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹു സത്യം പറഞ്ഞിരിക്കുന്നു. പക്ഷേ, താങ്കളുടെ സഹോദരന്റെ വയർ കളവാക്കി. അദ്ദേഹത്തിന് വീണ്ടും തേൻ നൽകുക." അദ്ദഹം വീണ്ടും സഹോദരന് തേൻ കൊടുത്തു. അസുഖം സുഖമായി. (ബു,മു,തു,ന)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَعِقَ الْعَسَلَ ثَلَاثَ غَدَوَاتٍ، كُلَّ شَهْرٍ، لَمْ يُصِبْهُ عَظِيمٌ مِنَ الْبَلَاءِ". [ز: قي سنده لين وفيه انقطاع] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മാസന്തോറും മൂന്ന് പ്രഭാതങ്ങളിൽ ആരെങ്കിലും തേൻ കുടിച്ചാൽ അവന് ഒരു പരിധി വരെ വിപത്തുകൾ പിടികൂടുകയില്ല." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: قي سنده لين وفيه انقطاع', null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: أُهْدِيَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَسَلٌ، فَقَسَمَ بَيْنَنَا لُعْقَةً لُعْقَةً، فَأَخَذْتُ لُعْقَتِي، ثُمَّ قُلْتُ: يَا رَسُولَ اللهِ، أَزْدَادُ أُخْرَى؟ قَالَ: "نَعَمْ". [ز: فيه راويان مختلف فيهما] (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ)യുടെ സന്നിധിയിൽ തേൻ ഹദ്യയായി കൊണ്ടുവരപ്പട്ടു. നബി(സ) ഓരോരുത്തർക്കും ഓരോ കയിൽ വീതം വിതരണം ചെയ്തു. ഞാനെന്റെ വിഹിതം വാങ്ങി. എന്നിട്ട് ഞാൻ ചോദിച്ചു: റസൂലേ, ഞാൻ ഇതിനെ വേറെയൊന്നുമായി കൂട്ടിക്കലർത്തട്ടെയോ? നബി(സ) പറഞ്ഞു: "ശരി." (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فيه راويان مختلف فيهما', null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِالشِّفَاءَيْنِ الْعَسَلِ وَالْقُرْآنِ". (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "രണ്ട് മരുന്നുകളെ നിങ്ങൾ മുറുകെപ്പിടിക്കുക, ഖുർആനും തേനും." (ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عَلَيْكُمْ بِهَذِهِ الْحَبَّةِ السَّوْدَاءِ، فَإِنَّ فِيهَا شِفَاءً مِنْ كُلِّ دَاءٍ إِلَّا السَّامَ". وَالسَّامُ: الْمَوْتُ. قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ കരിഞ്ചീരകം ഭക്ഷിച്ചു കൊള്ളൂ, ''സാം'' അല്ലാത്ത എല്ലാ രോഗങ്ങൾക്കും അതിൽ മുക്തിയുണ്ട്." ''സാം'' എന്നാൽ മരണമാണ്. (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 638, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ خَالِدِ بْنِ سَعْدٍ قَالَ: خَرَجْنَا وَمَعَنَا غَالِبُ بْنُ أَبْجَرَ، فَمَرِضَ فِي الطَّرِيقِ، فَقَدِمْنَا الْمَدِينَةَ وَهُوَ مَرِيضٌ، فَعَادَهُ ابْنُ أَبِي عَتِيقٍ، وَقَالَ لَنَا: عَلَيْكُمْ بِهَذِهِ الْحَبَّةِ السَّوْدَاءِ، فَخُذُوا مِنْهَا خَمْسًا أَوْ سَبْعًا، فَاسْحَقُوهَا ثُمَّ اقْطُرُوهَا فِي أَنْفِهِ بِقَطَرَاتِ زَيْتٍ، فِي هَذَا الْجَانِبِ وَفِي هَذَا الْجَانِبِ. فَإِنَّ عَائِشَةَ – رَضِيَ اللهُ عَنْهَا – حَدَّثَتْهُمْ: أَنَّهَا سَمِعَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ هَذِهِ الْحَبَّةَ السَّوْدَاءَ شِفَاءٌ مِنْ كُلِّ دَاءٍ، إِلَّا أَنْ يَكُونَ السَّامُ". قُلْتُ: وَمَا السَّامُ؟ قَالَ: "الْمَوْتُ". (خ,جه)', 'ഖാലിദുബ്നു സഅ്ദ്(റ): ഞങ്ങൾ ഒരു യാത്ര പുറപ്പെട്ടു. കൂട്ടത്തിൽ ഗാലിബുബ്നു അബ്ജർ(റ)വുമുണ്ട്. യാത്രാമധ്യേ അദ്ദേഹം രോഗബാധിതനായി. പിന്നീട് ഞങ്ങൾ മദീനയിലെത്തി. അപ്പോഴും അദ്ദേഹം രോഗിയായിരുന്നു. അവിടന്ന് ഇബ്നു അബീഅതീഖ്(റ) അദ്ദേഹത്തെ സന്ദർശിച്ചു. അദ്ദേഹം ഞങ്ങളോട് പറഞ്ഞു: നിങ്ങൽ കരിഞ്ചീരകം കൊണ്ടുവന്ന് അതിൽ നിന്ന് അഞ്ചോ ഏഴോ എണ്ണം എടുക്കുക. എന്നിട്ട് അത് പൊടിച്ച് ഒലീവെണ്ണയോടു കൂടി അദ്ദേഹത്തിന്റെ മൂക്കിന്റെ ഇരു ദ്വാരങ്ങളിലേക്കും ഒറ്റിക്കുക. ആഇശ(റ) അവർക്ക് ഹദീസ് പറഞ്ഞുകൊടുത്തിട്ടുണ്ട്: നബി(സ) പറയുന്നതായി മഹതി കേട്ടു: "കരിഞ്ചീരകം എല്ലാ രോഗങ്ങൾക്കും ശമനമാണ്. ''സാം'' ഒഴികെ." ഞാൻ ചോദിച്ചു: എന്താണ് ''സാം''? നബി(സ) പറഞ്ഞു: "മരണം." (ബു,ജ)', 'خَالِدِ بْنِ سَعْدٍ قَالَ', 'ഖാലിദുബ്നു സഅ്ദ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 638, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ قَتَادَةَ قَالَ: حُدِّثْتُ أَنَّ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: الشُّونِيزُ دَوَاءٌ مِنْ كُلِّ دَاءٍ إِلَّا السَّامَ. (ت)', 'ഖതാദ(റ): എന്നോട് ഹദീസ് പറയപ്പെട്ടു: അബൂഹുറൈറ(റ) പറഞ്ഞു: കരിഞ്ചീരകം മരണമല്ലാത്ത എല്ലാ രോഗത്തിൽ നിന്നും ശമനമുള്ളതാണ്. (തു)', 'قَتَادَةَ قَالَ', 'ഖതാദ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 638, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَأَلَهَا: "بِمَ تَسْتَمْشِينَ". قَالَتْ: بِالشُّبْرُمِ. قَالَ: "حَارٌّ جَارٌّ". قَالَتْ: ثُمَّ اسْتَمْشَيْتُ بِالسَّنَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ أَنَّ شَيْئًا كَانَ فِيهِ شِفَاءٌ مِنَ الْمَوْتِ لَكَانَ فِي السَّنَا". قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ. (ت,جه)', 'അസ്മാഅ് ബിൻത് ഉമൈസ്(റ): നബി(സ) മഹതിയോട് ചോദിച്ചു: "എന്തുകൊണ്ടാണ് നീ വയറിളക്കുന്നത്?" മഹതി പറഞ്ഞു: ശുബ്റമ് (മരുന്നായി ഉപയോഗിക്കുന്ന ഒരു ചെടി) കൊണ്ട് നബി(സ) പറഞ്ഞു: "അത് വളരെ ചൂടുള്ളതും വയറ്റിൽ നിന്ന് മുഴുവൻ പുറംതള്ളുന്നതുമാണ്." മഹതി പറയുന്നു: പിന്നെ ഞാൻ സുന്നാമക്കി കൊണ്ട് വയറിളക്കി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഏതെങ്കിലും വസ്തുവിൽ മരണത്തിൽ നിന്ന് ശമനമുണ്ടെങ്കിൽ അത് സുന്നാമക്കിയിലാണ്." (തു,ജ)', 'أَسْمَاءَ بِنْتِ عُمَيْسٍ', 'അസ്മാഅ് ബിൻത് ഉമൈസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 638, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَبِي أُبَيِّ بْنِ أُمِّ حَرَامٍ رَضِيَ اللهُ عَنْهُمَا، وَكَانَ قَدْ صَلَّى مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْقِبْلَتَيْنِ، قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "عَلَيْكُمْ بِالسَّنَى وَالسَّنُّوتِ فَإِنَّ فِيهِمَا شِفَاءً مِنْ كُلِّ دَاءٍ، إِلَّا السَّامَ". قِيلَ: يَا رَسُولَ اللهِ، وَمَا السَّامُ؟ قَالَ: "الْمَوْتُ". [ز: في سنده ضعيف] (جه)', 'അബൂഉബയ്യുബ്നു ഉമ്മിഹറാം(റ): അദ്ദേഹം നബി(സ)യുടെ കൂടെ രണ്ട് ഖിബ്ലയിലേക്കുമുള്ള നിസ്കാരം നിസ്കരിച്ചിട്ടുണ്ട്. അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "സുന്നാമക്കിയും ജീരകവും (അല്ലെങ്കിൽ തേൻ) നിങ്ങൾ ഉപയോഗിച്ചുകൊള്ളുക. അതിൽ എല്ലാ രോഗത്തിനും ശമനമുണ്ട്, ''സാം'' ഒഴികെ." അപ്പോൾ ചോദിച്ചു: റസൂലേ, എന്താണ് ''സാം''? നബി(സ) പറഞ്ഞു: "മരണം." (ജ)', 'أَبِي أُبَيِّ بْنِ أُمِّ حَرَامٍ', 'അബൂഉബയ്യുബ്നു ഉമ്മിഹറാം(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 638, 639, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُتْبَةَ [بْنِ مَسْعُودٍ]: أَنَّ أُمَّ قَيْسٍ بِنْتَ مِحْصَنٍ – وَكَانَتْ مِنَ الْمُهَاجِرَاتِ الْأُوَلِ اللَّاتِي بَايَعْنَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَهِيَ أُخْتُ عُكَّاشَةَ بْنِ مِحْصَنٍ أَحَدِ بَنِي أَسَدِ بْنِ خُزَيْمَةَ – قَالَ: أَخْبَرَتْنِي: أَنَّهَا أَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِابْنٍ لَهَا لَمْ يَبْلُغْ أَنْ يَأْكُلَ الطَّعَامَ، وَقَدْ أَعْلَقَتْ عَلَيْهِ مِنَ الْعُذْرَةِ – قَالَ يُونُسُ: أَعْلَقَتْ غَمَزَتْ، فَهِيَ تَخَافُ أَنْ يَكُونَ بِهِ عُذْرَةٌ – قَالَتْ: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَامَهْ تَدْغَرْنَ أَوْلَادَكُنَّ بِهَذَا الْإِعْلَاقِ؟ عَلَيْكُمْ بِهَذَا الْعُودِ الْهِنْدِيِّ – يَعْنِي بِهِ الْكُسْتَ – فَإِنَّ فِيهِ سَبْعَةَ أَشْفِيَةٍ، مِنْهَا ذَاتُ الْجَنْبِ". قَالَ عُبَيْدُ اللهِ: وَأَخْبَرَتْنِي أَنَّ ابْنَهَا ذَاكَ بَالَ فِي حَجْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَدَعَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَاءٍ فَنَضَحَهُ عَلَى بَوْلِهِ وَلَمْ يَغْسِلْهُ غَسْلًا. (م)', 'ഉബൈദില്ലാഹിബ്നി അബ്ദില്ലാഹിബ്നി ഉത്ബതുബ്നി മസ്ഊദ്(റ): ഉമ്മുഖൈസ് ബിൻത് മിഹ്സൻ(റ) - എന്നെ അറിയിച്ചു: ഭക്ഷണം കഴിക്കാൻ പ്രായമെത്താത്ത അവരുടെ കുട്ടിയുമായി അവർ നബി(സ)യുടെയടുക്കൽ പോയി. അവർ കുട്ടിയെ തൊണ്ടവേദന കാരണം ചികിത്സിച്ചിരുന്നു. - നബി(സ)യോട് ആദ്യം ഉടമ്പടി ചെയ്ത മുഹാജിർ സ്ത്രീകളിൽപ്പെട്ടവരാണവർ. - അസദുബ്നു ഖുസൈമ ഗോത്രാംഗമായ ഉക്കാശതുബ്നു മിഹ്സ്വൻ(റ)വിന്റെ സഹോദരിയുമാണ് നബി(സ) ചോദിച്ചു: "ഈ ചികിത്സ കൊണ്ട് നിങ്ങൾ എന്തിനാണ് കുട്ടിയുടെ മൂക്കിൽ നിന്ന് രക്തം ഒലിപ്പിക്കുന്നത്? ഇന്ത്യൻ ഊദ് (അഥവാ കുസ്ത്) കൊണ്ട് നിങ്ങൾ ചികിത്സിക്കുക. കാരണം അതിൽ ഏഴ് രോഗശമനമുണ്ട്. അതിലൊന്നാണ് വാരിയെല്ലിന്റെ ആവരണത്തിന് ബാധിക്കുന്ന രോഗം. ഉബൈദുല്ല(റ) പറഞ്ഞു: അവരുടെ ആ കുട്ടി നബി(സ)യുടെ മടിയിൽ മൂത്രമൊഴിച്ചുവെന്നും അപ്പോൾ നബി(സ) വെള്ളം ആവശ്യപ്പെട്ട് ആ വെള്ളം കൊണ്ട് വസ്ത്രത്തിൽ കുടഞ്ഞുവെന്നും അത് കഴുകിക്കളഞ്ഞില്ലെന്നും ആ സ്ത്രീ എന്നെ അറിയിച്ചു. (മു)', 'عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُتْبَةَ [بْنِ مَسْعُودٍ]', 'ഉബൈദില്ലാഹിബ്നി അബ്ദില്ലാഹിബ്നി ഉത്ബതുബ്നി മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'بْنِ مَسْعُودٍ', null, 639, 639, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ سَلْمَى رَضِيَ اللهُ عَنْهَا – وَكَانَتْ تَخْدُمُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – قَالَتْ: مَا كَانَ يَكُونُ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرْحَةٌ وَلَا نَكْبَةٌ إِلَّا أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَضَعَ عَلَيْهَا الْحِنَّاءَ. قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ. (د,ت,جه)', 'സൽമ(റ): മഹതി നബി(സ)ക്ക് സേവനം ചെയ്യാറുണ്ടായിരുന്നു - മഹതി പറഞ്ഞു: നബി(സ)ക്ക് മുറിവും ചുമൽ വേദനയും ഉണ്ടാകുമ്പോഴൊക്കെ അതിന്മേൽ മൈലാഞ്ചി വെക്കാൻ അവിടുന്ന് എന്നോട് കൽപിച്ചിരുന്നു. ഹദീസ് ഹസനാണ്. (ദ,തു,ജ)', 'سَلْمَى', 'സൽമ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 639, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "عَلَيْكُمْ بِالْإِثْمِدِ عِنْدَ النَّوْمِ، فَإِنَّهُ يَجْلُو الْبَصَرَ وَيُنْبِتُ الشَّعَرَ". (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഉറങ്ങുന്ന സമയത്ത് നിങ്ങൾ അഞ്ജനം ഉപയോഗിക്കുക, കാരണം അത് കണ്ണിനെ പ്രശോഭിപ്പിക്കുകയും രോമത്തെ വളർത്തുകയും ചെയ്യും." (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اكْتَحَلَ فَلْيُوتِرْ، مَنْ فَعَلَ فَقَدْ أَحْسَنَ، وَمَنْ لَا فَلَا حَرَجَ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും സുറുമയിടുകയാണെങ്കിൽ അതിനെ ഒറ്റയാക്കട്ടെ, ആരെങ്കിലും അങ്ങനെ ചെയ്താൽ അവൻ നന്മ പ്രവർത്തിച്ചു. അങ്ങനെ ചെയ്തില്ലെങ്കിൽ പ്രശ്നമൊന്നുമില്ല." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتْ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُكْحُلَةٌ، يَكْتَحِلُ مِنْهَا ثَلَاثًا فِي كُلِّ عَيْنٍ. (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)ക്ക് ഒരു സുറുമക്കുപ്പിയുണ്ടായിരുന്നു. അതിൽനിന്ന് തിരുമേനി(സ) ഓരോ കണ്ണിലും മൂന്ന് പ്രാവശ്യം സുറുമയിടാറുണ്ടായിരുന്നു. (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْبَسُوا مِنْ ثِيَابِكُمُ الْبَيَاضَ، فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ، وَكَفِّنُوا فِيهَا مَوْتَاكُمْ. وَإِنَّ خَيْرَ أَكْحَالِكُمُ الْإِثْمِدُ: يَجْلُو الْبَصَرَ، وَيُنْبِتُ الشَّعَرَ". (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ വസ്ത്രങ്ങളിൽ നിന്ന് വെള്ളയെ ധരിക്കുക. കാരണം അത് നിങ്ങളുടെ ഉത്തമ വസ്ത്രങ്ങളിൽ പെട്ടതാണ്. നിങ്ങളിൽ നിന്നുള്ള മരിച്ചവരെ നിങ്ങൾ അതിൽ (വെള്ള വസ്ത്രം) കഫൻ ചെയ്യുക. നിങ്ങളുടെ സുറുമകളിൽ ഏറ്റവും ഉത്തമമായത് അഞ്ജനമാണ്. അത് കാഴ്ചയെ പ്രശോഭിപ്പിക്കുകയും രോമത്തെ വളർത്തുകയും ചെയ്യും." (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ، سُئِلَ: بِأَيِّ شَيْءٍ دُووِيَ جَرْحُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: مَا بَقِيَ أَحَدٌ أَعْلَمُ بِهِ مِنِّي، كَانَ عَلِيٌّ يَأْتِي بِالْمَاءِ فِي تُرْسِهِ، وَفَاطِمَةُ تَغْسِلُ عَنْهُ الدَّمَ، وَأُحْرِقَ لَهُ حَصِيرٌ فَحَشَا بِهِ جُرْحُهُ. (ق,ت,جه)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): എന്തുകൊണ്ടാണ് നബി(സ)യുടെ മുറിവ് ചികിത്സിക്കപ്പെട്ടതെന്നു അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: അതിനെക്കുറിച്ച് എന്നേക്കാൾ അറിയുന്ന മറ്റൊരാളും ഇപ്പോൾ ശേഷിക്കുന്നില്ല. അലി(റ) അദ്ദേഹത്തിന്റെ പരിചയിൽ വെള്ളം കൊണ്ടുവരുമായിരുന്നു. ഫാത്വിമ(റ), നബി(സ)യുടെ ശരീരത്തിലുള്ള രക്തം കഴുകുകയും പിന്നീട് നബി(സ)ക്ക് വേണ്ടി ഒരു പായ കരിക്കുകയും അതിന്റെ വെണ്ണീര് നബി(സ)യുടെ മുറിവിന്റെ ഭാഗത്ത് നിറക്കുകയും ചെയ്തു. (ബു,മു,തു,ജ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 640, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جُرِحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ، وَكُسِرَتْ رَبَاعِيَتُهُ، وَهُشِمَتِ الْبَيْضَةُ عَلَى رَأْسِهِ، فَكَانَتْ فَاطِمَةُ رَضِيَ اللهُ عَنْهَا تَغْسِلُ الدَّمَ عَنْهُ، وَعَلِيٌّ رَضِيَ اللهُ عَنْهُ يَسْكُبُ عَلَيْهِ الْمَاءَ بِالْمِجَنِّ، فَلَمَّا رَأَتْ فَاطِمَةُ رَضِيَ اللهُ عَنْهَا أَنَّ الْمَاءَ لَا يَزِيدُ الدَّمَ إِلَّا كَثْرَةً أَخَذَتْ قِطْعَةَ حَصِيرٍ فَأَحْرَقَتْهَا، حَتَّى إِذَا صَارَ رَمَادًا أَلْزَمَتْهُ الْجُرْحَ، فَاسْتَمْسَكَ الدَّمُ. (ق,جه)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ): ഉഹ്ദ് യുദ്ധത്തിൽ നബി(സ)ക്ക് മുറിവേറ്റു. അവിടത്തെ ഒരു മുൻപല്ല് പൊട്ടി. അവിടത്തെ തലയിലുണ്ടായിരുന്ന പടത്തൊപ്പി പൊട്ടി. ഫാത്വിമ ബീവി(റ) നബി(സ)യുടെ ശരീരത്തിലുള്ള രക്തം കഴുകിക്കൊണ്ടിരിക്കുകയും അലി(റ) പരിച കൊണ്ട് മുറിവിലേക്ക് വെള്ളം ഒഴിച്ചുകൊണ്ടിരിക്കുകയും ചെയ്തിരുന്നു. രക്തം വെള്ളത്തെക്കാൾ അധികരിക്കുകയാണെന്ന് മനസ്സിലായപ്പോൾ ഫാത്വിമ ബീവി(റ) ഒരു പായയുടെ കഷ്ണം എടുത്ത് കരിക്കുകയും അത് വെണ്ണീറായപ്പോൾ മുറിവിൽ വെക്കുകയും ചെയ്തു. അപ്പോൾ രക്തം നിന്നു. (ബു,മു,ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 641, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: إِنِّي لَأَعْرِفُ يَوْمَ أُحُدٍ مَنْ جَرَحَ وَجْهَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَمَنْ كَانَ يُرْقِئُ الْكَلْمَ مِنْ وَجْهِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَيُدَاوِيهِ، وَمَنْ يَحْمِلُ الْمَاءَ فِي الْمِجَنِّ، وَبِمَا دُووِيَ بِهِ الْكَلْمُ حَتَّى رَقَأَ. قَالَ: أَمَّا مَنْ كَانَ يَحْمِلُ الْمَاءَ فِي الْمِجَنِّ فَعَلِيٌّ رَضِيَ اللهُ عَنْهُ، وَأَمَّا مَنْ كَانَ يُدَاوِي الْكَلْمَ فَفَاطِمَةُ رَضِيَ اللهُ عَنْهَا، أُحْرِقَتْ لَهُ – حِينَ لَمْ يَرْقَأْ – قِطْعَةُ حَصِيرٍ خَلَقٍ، فَوَضَعَتْ رَمَادَهُ عَلَيْهِ، فَرَقَأَ الْكَلْمُ. (جه)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ): ഉഹ്ദ് ദിനത്തിൽ നബി(സ)യുടെ മുഖത്ത് മുറിവേൽപ്പിച്ചതാരാണെന്നും, നബി(സ)യുടെ മുഖത്ത് നിന്ന് ഒലിക്കുന്ന രക്തം നിറുത്തുകയും ചികിത്സിക്കുകയും ചെയ്തതാരാണെന്നും, പരിചയിൽ വെള്ളം ചുമന്നിരുന്നതാരാണെന്നും, എന്തുകൊണ്ട് ചികിത്സിച്ചിട്ടാണ് നബി(സ)യുടെ മുഖത്തെ രക്തം ഒലിക്കൽ നിന്നതെന്നും എനിക്കറിയാം. അദ്ദേഹം പറയുന്നു: പരിചയിൽ വെള്ളം ചുമന്നിരുന്നത് അലി(റ)വും രക്തം ഒലിക്കുന്നത് ചികിത്സിച്ചത് ഫാത്വിമ ബീവി(റ)യും ആണ്. രക്തം ഒലിക്കുന്നത് നിൽക്കാതിരുന്നപ്പോൾ മഹതി ഒരു നുരുമ്പിയ പായക്കഷ്ണം എടുത്ത് കരിക്കുകയും അതിന്റെ വെണ്ണീർ മുറിവിൽ വെക്കുകയും രക്തം നിൽക്കുകയും ചെയ്തു. (ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 641, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَدَدْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَرَضِهِ، فَأَشَارَ أَنْ لَا تَلُدُّونِي، فَقُلْنَا: كَرَاهِيَةَ الْمَرِيضِ لِلدَّوَاءِ، فَلَمَّا أَفَاقَ قَالَ: "لَا يَبْقَى أَحَدٌ مِنْكُمْ إِلَّا لُدَّ غَيْرَ الْعَبَّاسِ، فَإِنَّهُ لَمْ يَشْهَدْكُمْ". (م)', 'ആഇശ(റ): ഞങ്ങൾ നബി(സ)ക്ക് രോഗം വന്നപ്പോൾ നബി(സ)യുടെ വായയുടെ ഒരു ഭാഗത്ത് ലദൂദ് (ഒരു ഔഷധം) എന്ന മരുന്ന് വെച്ചുകൊടുത്തു. അപ്പോൾ നബി(സ) അത് വേണ്ടെന്ന് സൂചിപ്പിച്ചു. അപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: മരുന്നിനോടുള്ള രോഗിയുടെ വെറുപ്പാണത്. ശരിക്ക് ബോധം വന്നപ്പോൾ നബി(സ) പറഞ്ഞു: "അബ്ബാസ് ഒഴികെ നിങ്ങളിൽ ആരും തന്നെ ഈ മരുന്ന് വായിൽ വെക്കപ്പെട്ടിട്ടല്ലാതെ ബാക്കിയാവുകയില്ല, നിശ്ചയം അദ്ദേഹം നിങ്ങളോടൊപ്പം സൻഹിതനായിരുന്നില്ല." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 641, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ خَيْرَ مَا تَدَاوَيْتُمْ بِهِ السَّعُوطُ، وَاللَّدُودُ، وَالْحِجَامَةُ، وَالْمَشِيُّ". فَلَمَّا اشْتَكَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَدَّهُ أَصْحَابُهُ، فَلَمَّا فَرَغُوا قَالَ: "لُدُّوهُمْ". قَالَ: فَلُدُّوا كُلُّهُمْ غَيْرَ الْعَبَّاسِ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നസ്യം, വായയുടെ ഒരു ഭാഗത്ത് മരുന്ന് വെക്കൽ, കൊമ്പ് വെക്കൽ, ശോദനക്കായി ഉപയോഗിക്കുന്ന മരുന്ന് എന്നിവയാണ് നിങ്ങൾ ചെയ്യാറുള്ള ചികിത്സകളിൽ ഏറ്റവും നല്ലത്." ഒരിക്കൽ നബി(സ)ക്ക് രോഗം ബാധിച്ചപ്പോൾ സ്വഹാബികൾ ലദൂദ് എന്ന മരുന്ന് വായിൽ വെച്ച് കൊടുത്തു. അവർ അത് ചെയ്തുകഴിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "അവർക്ക് മുഴുവനും നിങ്ങൾ ലദൂദ് കഴിപ്പിക്കുക." ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അങ്ങനെ അബ്ബാസ്(റ) അല്ലാത്ത അവരിൽ നിന്നുള്ള എല്ലാവരും ലദൂദ് കഴിപ്പിക്കപ്പെട്ടു. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 642, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ خَيْرَ مَا تَدَاوَيْتُمْ بِهِ اللَّدُودُ، وَالسَّعُوطُ، وَالْحِجَامَةُ، وَالْمَشِيُّ. وَخَيْرُ مَا اكْتَحَلْتُمْ بِهِ الْإِثْمِدُ، فَإِنَّهُ يَجْلُو الْبَصَرَ وَيُنْبِتُ الشَّعَرَ". وَكَانَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُكْحُلَةٌ يَكْتَحِلُ بِهَا عِنْدَ النَّوْمِ: ثَلَاثًا فِي كُلِّ عَيْنٍ. (ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ചെയ്യാറുള്ള ചികിത്സകളിൽ ഏറ്റവും ഉത്തമമായത്, നസ്യവും ലദൂദും കൊമ്പുവെക്കലും വയറിളക്കലുമാണ്. നിങ്ങൾ ഉപയോഗിക്കുന്ന സുറുമകളിൽ ഏറ്റവും ഉത്തമമായത് നീല അഞ്ജനക്കല്ലുമാണ്. അത് കാഴ്ചയെ പ്രശോഭിപ്പിക്കുകയും രോമത്തെ മുളപ്പിക്കുകയും ചെയ്യും. നബി(സ)ക്ക് ഒരു സുറുമക്കുപ്പിയുണ്ടായിരുന്നു. എല്ലാ ദിവസവും ഉറങ്ങുന്ന സമയത്ത് ഓരോ കണ്ണിലും മുമ്മൂന്ന് പ്രാവശ്യം അതിൽ നിന്ന് തിരുമേനി(സ) സുറുമയിടാറുണ്ടായിരുന്നു. (തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 642, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ: نَعَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ ذَاتِ الْجَنْبِ وَرْسًا وَقُسْطًا وَزَيْتًا، يُلَدُّ بِهِ. (ت,جه)', 'സൈദുബ്നു അർഖം(റ): വായിൽ വെക്കപ്പെടുന്ന മഞ്ഞളിനെയും, ഇന്ത്യൻ സുഗന്ധദ്രവ്യത്തെയും, സൈത് എണ്ണയെയും നബി(സ) ശ്വാസകോശാവരണ രോഗത്തിന് ചികിത്സയായി വിശേഷിപ്പിച്ചു. (തു,ജ)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 642, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ، وَأَعْطَى الْحَجَّامَ أَجْرَهُ، وَاسْتَعَطَ. (ق,د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം നബി(സ) കൊമ്പുവെക്കുകയും കൊമ്പുവെക്കുന്നയാൾക്ക് കൂലി കൊടുക്കുകയും നസ്യം (മൂക്കിലിടുന്ന ഒരു തരം മരുന്ന്) ഉപയോഗിക്കുകയും ചെയ്തിരുന്നു. (ബു,മു,ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 642, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "عَلَيْكُمْ بِهَذَا الْعُودِ الْهِنْدِيِّ، فَإِنَّ فِيهِ سَبْعَةَ أَشْفِيَةٍ: يُسْتَعَطُ بِهِ مِنَ الْعُذْرَةِ، وَيُلَدُّ بِهِ مِنْ ذَاتِ الْجَنْبِ". وَدَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِابْنٍ لِي لَمْ يَأْكُلِ الطَّعَامَ، فَبَالَ عَلَيْهِ، فَدَعَا بِمَاءٍ فَرَشَّ عَلَيْهِ. (خ)', 'ഉമ്മുഖൈസ് ബിൻത് മിഹ്സൻ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഈ ഇന്ത്യൻ ഊദ് (സുഗന്ധത്തിനായി പുകയ്ക്കുന്ന ഒരു തരം ഉലുവാൻ മരം) നിങ്ങൾ ഉപയോഗിക്കുക. നിശ്ചയം അതിൽ ഏഴ് ശമനമുണ്ട്. തൊണ്ടരോഗത്തിന് അതുകൊണ്ട് നസ്യം ചെയ്യാം. ശ്വാസകോശാവരണരോഗത്തിന് അതിനെ ലദൂദായി (വായയുടെ കോണിലൂടെ ഒഴിക്കുന്ന മരുന്ന്) ഉപയോഗിക്കാം." ഭക്ഷണം കഴിച്ചിട്ടില്ലാത്ത എന്റെ ഒരു കുട്ടിയുമായി ഞാൻ നബി(സ)യുടെ അടുത്തേക്ക് ചെന്നു. കുട്ടി നബി(സ)യുടെ മേൽ മൂത്രമൊഴിച്ചു. അപ്പോൾ തിരുമേനി(സ) കുറച്ച് വെള്ളം കൊണ്ടുവരാൻ പറഞ്ഞ് അത് മൂത്രത്തിൽ കുടഞ്ഞു. (ബു)', 'أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ', 'ഉമ്മുഖൈസ് ബിൻത് മിഹ്സൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 642, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سُئِلَ عَنْ أَجْرِ الْحَجَّامِ، فَقَالَ: احْتَجَمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، حَجَمَهُ أَبُو طَيْبَةَ، وَأَعْطَاهُ صَاعَيْنِ مِنْ طَعَامٍ، وَكَلَّمَ مَوَالِيَهُ فَخَفَّفُوا عَنْهُ، وَقَالَ: "إِنَّ أَمْثَلَ مَا تَدَاوَيْتُمْ بِهِ الْحِجَامَةُ، وَالْقُسْطُ الْبَحْرِيُّ". وَقَالَ: "لَا تُعَذِّبُوا صِبْيَانَكُمْ بِالْغَمْزِ مِنَ الْعُذْرَةِ، وَعَلَيْكُمْ بِالْقُسْطِ". (خ)', 'അനസ്(റ): അദ്ദേഹത്തോട് കൊമ്പുവെക്കുന്നവന്റെ കൂലിയെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) കൊമ്പ് വെച്ചിരുന്നു. അബൂത്വയ്ബയാണ് തിരുമേനി(സ)യെ കൊമ്പുവെച്ചത്. നബി(സ) അദ്ദേഹത്തിന് രണ്ട് സ്വാഅ് ഭക്ഷണം നൽകി. നബി(സ) അദ്ദേഹത്തിന്റെ ഉടമകളോട് സംസാരിക്കുകയും അവർ അവിടത്തേക്ക് ഇളവ് നൽകുകയും ചെയ്തു. നബി(സ) പറഞ്ഞു: "കൊമ്പുവെക്കലാണ് നിങ്ങൾ ചെയ്യുന്ന ചികിത്സകളിൽ ഏറ്റവും നല്ലത്, പിന്നെ ഖുസ്തുൽ ബഹ്രി(ഒരു ചെടി)യുമാണ്." നബി(സ) വീണ്ടും പറഞ്ഞു: "തൊണ്ടവേദനയുള്ളത് കൊണ്ട് നിങ്ങളുടെ മക്കളെ നാഡി പിടിച്ച് നിങ്ങൾ ബുദ്ധിമുട്ടാക്കരുത്. മറിച്ച് നിങ്ങൾ ഖുസ്ത് (ഒരു തരം ഔഷധച്ചെടി) ഉപയോഗിക്കുക." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 643, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْكَيِّ، فَاكْتَوَيْنَا، فَمَا أَفْلَحْنَا وَلَا أَنْجَحْنَا. (د,ت,جه)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): ചൂടുവെക്കുന്നതിനെ നബി(സ) വിലക്കി. എന്നിട്ടും ഞങ്ങൾ ചൂടുവെച്ചു. പക്ഷേ, ഞങ്ങൾ വിജയിക്കുകയോ ലക്ഷ്യത്തിലെത്തുകയോ ചെയ്തില്ല. (ദ,തു,ജ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 643, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَوَى سَعْدَ بْنَ مُعَاذٍ مِنْ رَمِيَّتِهِ. (م,د,جه)', 'ജാബിർ(റ): സഅ്ദുബ്നു മുആദ്(റ)വിന് അമ്പേറ്റ സ്ഥലത്ത് നബി(സ) ചൂടുവെച്ചു. (മു,ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 643, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ و رَفَعَهُ: "الشِّفَاءُ فِي ثَلَاثَةٍ: شَرْبَةِ عَسَلٍ، وَشَرْطَةِ مِحْجَمٍ، وَكَيَّةِ نَارٍ، وَأَنْهَى أُمَّتِي عَنِ الْكَيِّ". (ق)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞതായി അദ്ദേഹം പറയുന്നു: "രോഗശമനം മൂന്ന് ഔഷധങ്ങളിലാണുള്ളത്: തേൻ കുടിക്കുക, കൊമ്പുവെക്കുക, ചൂടുവെക്കുക. എന്റെ അനുയായികളോട് ചൂടുവെക്കരുതെന്ന് ഞാനിതാ വിലക്ക് പറയുന്നു." (ബു,മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 643, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ قَالَ: جَاءَنَا جَابِرُ بْنُ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا فِي أَهْلِنَا، وَرَجُلٌ يَشْتَكِي خُرَاجًا بِهِ أَوْ جِرَاحًا، فَقَالَ: مَا تَشْتَكِي؟ قَالَ: خُرَاجٌ بِي قَدْ شَقَّ عَلَيَّ. فَقَالَ: يَا غُلَامُ ائْتِنِي بِحَجَّامٍ، فَقَالَ لَهُ: مَا تَصْنَعُ بِالْحَجَّامِ يَا أَبَا عَبْدِ اللهِ؟ قَالَ: أُرِيدُ أَنْ أُعَلِّقَ فِيهِ مِحْجَمًا، قَالَ: وَاللهِ إِنَّ الذُّبَابَ لَيُصِيبُنِي أَوْ يُصِيبُنِي الثَّوْبُ فَيُؤْذِينِي، وَيَشُقُّ عَلَيَّ. فَلَمَّا رَأَى تَبَرُّمَهُ مِنْ ذَلِكَ قَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنْ كَانَ فِي شَيْءٍ مِنْ أَدْوِيَتِكُمْ خَيْرٌ فَفِي شَرْطَةِ مِحْجَمٍ، أَوْ شَرْبَةٍ مِنْ عَسَلٍ، أَوْ لَذْعَةٍ بِنَارٍ". قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَمَا أُحِبُّ أَنْ أَكْتَوِيَ". قَالَ: فَجَاءَ بِحَجَّامٍ فَشَرَطَهُ، فَذَهَبَ عَنْهُ مَا يَجِدُ. (م)', 'ആസിമുബ്നു ഉമറുബ്നു ഖതാദ(റ): ഒരാൾ മുഖക്കുരു കാരണമോ മുറിവ് കാരണമോ വേദനിച്ചുകൊണ്ടിരിക്കുമ്പോൾ ജാബിറുബ്നു അബ്ദില്ല(റ) ഞങ്ങളുടെ കുടുംബത്തിലേക്ക് വന്നു. ജാബിർ(റ) ചോദിച്ചു: എന്താണ് നിനക്ക് പ്രശ്നം? അയാൾ പറഞ്ഞു: എന്റെ മുഖക്കുരു കാരണം വളരെ ബുദ്ധിമുട്ടനുഭവപ്പെടുന്നുണ്ട്. അപ്പോൾ ജാബിർ(റ) പറഞ്ഞു: നീ പോയി കൊമ്പുവെക്കുന്നയാളെ കൊണ്ടുവരൂ. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: അബൂഅബ്ദില്ലാ, കൊമ്പുവെക്കുന്നയാളെക്കൊണ്ട് എന്തുചെയ്യാനാണ്? ജാബിർ(റ) പറഞ്ഞു: ആ മുറിവിൽ കൊമ്പ് വെക്കുന്ന ഉപകരണം വെക്കാനാണ് ഞാൻ ഉദ്ദേശിക്കുന്നത്. അയാൾ പറഞ്ഞു: അല്ലാഹുവാണ, ഈച്ച ഇരിക്കുന്നത് കൊണ്ടും അല്ലെങ്കിൽ വസ്ത്രം തട്ടുന്നതുകൊണ്ടു പോലും മുറിവ് വല്ലാതെ ബുദ്ധിമുട്ടാകുന്നു. അദ്ദേഹത്തിന് അതിൽ വല്ലാതെ അസഹൃത തോന്നുന്നുണ്ടെന്ന് കണ്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "നിങ്ങളുടെ മരുന്നുകളിൽ വല്ലതിലും നന്മയുണ്ടെങ്കിൽ അത് കൊമ്പുവെക്കുന്ന കത്തിയിലും തേൻ കുടിക്കുന്നതിലും അല്ലെങ്കിൽ ചൂട് വെക്കുന്നതിലുമാണ്." നബി(സ) പറഞ്ഞു: "ചൂടുവെക്കാൻ ഞാൻ ഇഷ്ടപ്പെടുന്നില്ല." ആസിം(റ) പറയുന്നു: അങ്ങനെ ഒരു കൊമ്പുവെക്കുന്നവനെ ജാബിർ(റ) കൊണ്ടുവന്നു. അയാൾ അദ്ദേഹത്തെ (രക്തമൊലിപ്പിക്കാൻ) കീറി. അദ്ദേഹത്തിന്റെ രോഗം ഭേദമാകുകയും ചെയ്തു. (മു)', 'عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ قَالَ', 'ആസിമുബ്നു ഉമറുബ്നു ഖതാദ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 643, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَذِنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأَهْلِ بَيْتٍ مِنَ الْأَنْصَارِ أَنْ يَرْقُوا مِنَ الْحُمَةِ وَالْأُذُنِ، قَالَ أَنَسٌ: كُوِيتُ مِنْ ذَاتِ الْجَنْبِ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَيٌّ، وَشَهِدَنِي أَبُو طَلْحَةَ، وَأَنَسُ بْنُ النَّضْرِ، وَزَيْدُ بْنُ ثَابِتٍ، وَأَبُو طَلْحَةَ كَوَانِي. (خ)', 'അനസുബ്നു മാലിക്(റ): ചൊള്ളയുണ്ടാവുകയോ ചെകിട് വേദനിക്കുകയോ ചെയ്യുമ്പോൾ മന്ത്രിച്ചുകൊള്ളാൻ ഒരു അൻസാരി കുടുംബത്തിന് തിരുമേനി(സ) അനുവാദം നൽകി. അനസ്(റ) പറഞ്ഞു: തിരുമേനി(സ) ജീവിച്ചിരിക്കുന്ന കാലത്തു തന്നെ വാരിയെല്ലിന്റെ ആവരണത്തിന് ബാധിക്കുന്ന രോഗത്തിന് എനിക്ക് ചൂടുവെച്ചിരുന്നു. അബൂത്വൽഹ(റ)വും അനസുബ്നുന്നള്ർ(റ)വും സൈദുബ്നു സാബിത്(റ)വും അവിടെ സന്നിഹിതരായിരുന്നു. അബൂത്വൽഹ(റ)യാണ് എനിക്ക് ചൂടുവെച്ചത്. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 644, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى أُبَيِّ بْنِ كَعْبٍ طَبِيبًا، فَقَطَعَ مِنْهُ عِرْقًا، ثُمَّ كَوَاهُ عَلَيْهِ. (م)', 'ജാബിർ(റ): ഉബയ്യുബ്നു കഅ്ബ്(റ)വിലേക്ക് നബി(സ) ഒരു വൈദ്യനെ അയച്ചു. അങ്ങനെ ആ വൈദ്യൻ അദ്ദേഹത്തിന്റെ ഞരമ്പ് മുറിക്കുകയും പിന്നെ അത് ചൂട്വെച്ച് ചികിത്സിക്കുകയും ചെയ്തു. (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 644, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رُمِيَ سَعْدُ بْنُ مُعَاذٍ رَضِيَ اللهُ عَنْهُ فِي أَكْحَلِهِ، قَالَ: فَحَسَمَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ بِمِشْقَصٍ، ثُمَّ وَرِمَتْ فَحَسَمَهُ الثَّانِيَةَ. (م)', 'ജാബിർ(റ): സഅ്ദുബ്നു മുആദ്(റ)വിന്റെ കയ്യിൽ അമ്പേറ്റു. അപ്പോൾ നബി(സ) തന്റെ സ്വന്തം കൈകൾ കൊണ്ട്, ചീർപ്പ് പോലെയുള്ള ഒരു ഇരുമ്പായുധം ഉപയോഗിച്ച് ചൂട്വെച്ചു. ശേഷം അത് വീർത്ത് വരികയും അപ്പോൾ വീണ്ടും ചൂടുവെക്കുകയും ചെയ്തു. (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 644, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَوَى أَسْعَدَ بْنَ زُرَارَةَ مِنَ الشَّوْكَةِ. (ت)', 'അനസ്(റ): ശരീരം ചുകപ്പ് നിറമായി മാറിയതിനാൽ നബി(സ) അസ്അദുബ്നു സുറാറ(റ)വിനെ ചൂട്വെച്ച് ചികിത്സിച്ചു. (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 644, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا، عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَوَاهُ. وفي رواية: عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَوَى أُبَيَّ بْنَ كَعْبٍ رَضِيَ اللهُ عَنْهُ. (ت)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)വിൽനിന്ന് ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) ഉബയ്യ്(റ)വിന് ചൂടുവെച്ചു. മറ്റൊരു നിവേദനം: ജാബിർ(റ) പറഞ്ഞു: നബി(സ) ഉബയ്യുബ്നു കഅ്ബ്(റ)വിന് ചൂടുവെച്ചു. (തു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 644, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=11 and h.hadith_no=70), 1, 'وَفِي رِوَايَةٍ: عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَوَى أُبَيَّ بْنَ كَعْبٍ رَضِيَ اللهُ عَنْهُ. (ت)', 'മറ്റൊരു നിവേദനം: ജാബിർ(റ) പറഞ്ഞു: നബി(സ) ഉബയ്യുബ്നു കഅ്ബ്(റ)വിന് ചൂടുവെച്ചു. (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ الْأَنْصَارِيِّ: سَمِعَهُ عَمِّي يَحْيَى – وَمَا أَدْرَكْتُ رَجُلًا مِنَّا بِهِ شَبِيهًا – يُحَدِّثُ النَّاسَ: أَنَّ سَعْدَ بْنَ زُرَارَةَ – وَهُوَ جَدُّ مُحَمَّدٍ مِنْ قِبَلِ أُمِّهِ – أَخَذَهُ وَجَعٌ فِي حَلْقِهِ يُقَالُ لَهُ الذُّبْحَةُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَأُبْلِغَنَّ – أَوْ: لَأُبْلِيَنَّ – فِي أَبِي أُمَامَةَ عُذْرًا". فَكَوَاهُ بِيَدِهِ، فَمَاتَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مِيتَةَ سَوْءٍ لِلْيَهُودِ، يَقُولُونَ: أفلا دفع عن صاحبه! وما أملك له ولا لِنَفْسِي شَيْئًا". (جه)', 'മുഹമ്മദുബ്നു അബ്ദിർഹ്മാനുബ്നു സഅ്ദുബ്നു സുറാറതുൽ അൻസാരി(റ): അദ്ദേഹം ജനങ്ങളോട് ഹദീസ് പറയുന്നതായി എന്റെ പിതൃവ്യൻ യഹ്യ(റ) - അദ്ദേഹത്തോട് സാദൃശ്യമുള്ള ഒരാളെയും ഞങ്ങളുടെ കൂട്ടത്തിൽ ഞാൻ എത്തിച്ചിട്ടില്ല - കേട്ടു. ഡെഫ്തീരിയ എന്ന് പേരുള്ള ഒരു വിധം കണ്ഠരോഗം സഅ്ദുബ്നു സുറാറ(റ)വിന് - അദ്ദേഹം നിവേദകനായ മുഹമ്മദിന്റെ ഉമ്മ വഴിക്കുള്ള പിതാമഹനാണ് - പിടിപെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "തീർച്ചയായും അബൂഉമാമയുടെ കാര്യത്തിൽ ഞാൻ പരിഹാരം കാണും" അങ്ങനെ നബി(സ) തന്റെ സ്വന്തം കൈകൾ കൊണ്ട് അദ്ദേഹത്തെ ചൂടുവെച്ച് ചികിത്സിക്കുകയും അദ്ദേഹം മരിക്കുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "യഹൂദികൾക്കിത് മോശമായ മരണമാണ്. അവർ പറയും: പ്രവാചകനെന്തേ തന്റെ സഹചാരിയെത്തൊട്ട് വിപത്തിനെ തടയാതിരുന്നത്? ഞാൻ എന്റെയോ അദ്ദേഹത്തിന്റെയോ നഫ്സിൽ നിന്ന് ഒന്നും ഉടമപ്പെടുത്തുന്നില്ല." (ജ)', 'مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ الْأَنْصَارِيِّ', 'മുഹമ്മദുബ്നു അബ്ദിർഹ്മാനുബ്നു സഅ്ദുബ്നു സുറാറതുൽ അൻസാരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرِضَ أُبَيُّ ابْنُ كَعْبٍ مَرَضًا، فَأَرْسَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ طَبِيبًا، فَكَوَاهُ عَلَى أَكْحَلِهِ. (م,د,جه)', 'ജാബിർ(റ): ഉബയ്യുബ്നു കഅ്ബ്(റ)വിന് രോഗംബാധിച്ചു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തിന്റെയടുത്തേക്ക് ഒരു വൈദ്യനെ പറഞ്ഞയക്കുകയും അയാൾ അദ്ദേഹത്തിന്റെ മുഴങ്കയ്യിൽ ചൂടുവെച്ച് ചികിത്സിക്കുകയും ചെയ്തു. (മു,ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَوَى سَعْدَ بْنَ مُعَاذٍ فِي أَكْحَلِهِ، مَرَّتَيْنِ. (جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): റസൂൽ(സ) സഅ്ദുബ്നുമുആദ്(റ)വിന്റെ മുഴങ്കയ്യിൽ രണ്ട് പ്രാവശ്യം ചൂടുവെച്ചു. (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى أُبَيٍّ طَبِيبًا، فَقَطَعَ مِنْهُ عِرْقًا. (د,ن)', 'ജാബിർ(റ): നബി(സ) ഉബയ്യ്(റ)വിലേക്ക് ഒരു വൈദ്യനെ അയച്ചു. അയാൾ അദ്ദേഹത്തിന്റെ ഒരു ഞരമ്പ് മുറിച്ചു. (ദ,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنْ كَانَ فِي شَيْءٍ مِمَّا تَدَاوَيْتُمْ بِهِ خَيْرٌ فَالْحِجَامَةُ". (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ചികിത്സ ചെയ്യുന്ന വല്ലതിലും നന്മയുണ്ടെങ്കിൽ കൊമ്പുവെക്കലിലാണ്." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 645, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ سَلْمَى – خَادِمِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا كَانَ أَحَدٌ يَشْتَكِي إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَجَعًا فِي رَأْسِهِ إِلَّا قَالَ: "احْتَجِمْ". وَلَا وَجَعًا فِي رِجْلَيْهِ إِلَّا قَالَ: "اخْضِبْهُمَا". (د,ت,جه)', 'റസൂൽ(സ)യുടെ സേവകയായ സൽമ(റ): നബി(സ)യോട് തലയിലെ വേദനയെക്കുറിച്ച് വേവലാധി പറയുന്നവരോടെല്ലാം അവിടന്ന്: "കൊമ്പുവെക്കുക." എന്ന് മാത്രമാണ് പറഞ്ഞത്. കാലിൽ വേദനയുള്ളവരോട് അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ മൈലാഞ്ചിയിടുക." (ദ,തു,ജ)', 'سَلْمَى – خَادِمِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ –', 'റസൂൽ(സ)യുടെ സേവകയായ സൽമ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 646, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مَرَرْتُ لَيْلَةَ أُسْرِيَ بِي بِمَلَإٍ مِنَ الْمَلَائِكَةِ إِلَّا كُلُّهُمْ يَقُولُ لِي: عَلَيْكَ – يَا مُحَمَّدُ – بِالْحِجَامَةِ". (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഇസ്റാഇന്റെ രാത്രി ഓരോ കൂട്ടം മലക്കുകളുടെ അടുത്ത്കൂടെ ഞാൻ സഞ്ചരിച്ചപ്പോഴും അവർ മുഴുവനും എന്നോട് പറഞ്ഞുകൊണ്ടിരുന്നു: മുഹമ്മദ്, താങ്കൾ കൊമ്പുവെക്കണം." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 646, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مَرَرْتُ لَيْلَةَ أُسْرِيَ بِي بِمَلَإٍ إِلَّا قَالُوا: يَا مُحَمَّدُ، مُرْ أُمَّتَكَ بِالْحِجَامَةِ". (ت,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "ഇസ്റാഇന്റെ രാത്രി ഓരോ സംഘത്തിനടുത്തുകൂടെ ഞാൻ നടന്നപ്പോഴും അവർ മുഴുവനും എന്നോട് പറഞ്ഞു: മുഹമ്മദേ, അങ്ങയുടെ സമുദായത്തോട് കൊമ്പുവെക്കാൻ കൽപിക്കുക." (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 646, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أُمَّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، زَوْجَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: اسْتَأْذَنَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْحِجَامَةِ، فَأَمَرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَبَا طَيْبَةَ أَنْ يَحْجُمَهَا، وَقَالَ: حَسِبْتُ أَنَّهُ كَانَ أَخَاهَا مِنَ الرِّضَاعَةِ، أَوْ غُلَامًا لَمْ يَحْتَلِمْ. (م,د,جه)', 'ജാബിർ(റ): നബി(സ)യുടെ ഭാര്യ ഉമ്മുസലമ(റ) നബി(സ)യോട് കൊമ്പുവെക്കാൻ അനുവാദം ചോദിച്ചു. അപ്പോൾ നബി(സ) അബൂത്വൈബ(റ)വിനോട് മഹതിയെ കൊമ്പുവെക്കാൻ പറഞ്ഞു. ജാബിർ(റ) പറയുന്നു: അദ്ദേഹം മഹതിയുടെ മുലകുടിബന്ധത്തിലുള്ള സഹോദരനോ പ്രായപൂർത്തിയാകാത്ത കുട്ടിയോ ആണെന്നാണ് ഞാൻ വിചാരിക്കുന്നത്. (മു,ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 646, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَحْتَجِمُ فِي الْأَخْدَعَيْنِ وَالْكَاهِلِ، وَكَانَ يَحْتَجِمُ لِسَبْعَ عَشْرَةَ وَتِسْعَ عَشْرَةَ وَإِحْدَى وَعِشْرِينَ. (ت)', 'അനസ്(റ): നബി(സ) തന്റെ രണ്ട് കർണ്ണഞരമ്പുകളിലും പിരടിയിലും കൊമ്പുവെക്കാറുണ്ടായിരുന്നു. മാസം പതിനേഴിനും പത്തൊമ്പതിനും ഇരുപത്തിയൊന്നിനും അവിടന്ന് കൊമ്പുവെക്കാറുണ്ടായിരുന്നു. (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 646, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عِكْرِمَةَ قَالَ: كَانَ لِابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا غِلْمَةٌ ثَلَاثَةٌ حَجَّامُونَ، فَكَانَ اثْنَانِ مِنْهُمْ يُغِلَّانِ عَلَيْهِ وَعَلَى أَهْلِهِ، وَوَاحِدٌ يَحْجُمُهُ وَيَحْجُمُ أَهْلَهُ. قَالَ: وَقَالَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: قَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نِعْمَ الْعَبْدُ الْحَجَّامُ، يُذْهِبُ الدَّمَ وَيُخِفُّ الصُّلْبَ وَيَجْلُو عَنِ الْبَصَرِ". وَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ عُرِجَ بِهِ مَا مَرَّ عَلَى مَلَإٍ مِنَ الْمَلَائِكَةِ إِلَّا قَالُوا: عَلَيْكَ بِالْحِجَامَةِ. وَقَالَ: "إِنَّ خَيْرَ مَا تَحْتَجِمُونَ فِيهِ يَوْمَ سَبْعَ عَشْرَةَ، وَيَوْمَ تِسْعَ عَشْرَةَ، وَيَوْمَ إِحْدَى وَعِشْرِينَ". وَقَالَ: "إِنَّ خَيْرَ مَا تَدَاوَيْتُمْ بِهِ السَّعُوطُ وَاللَّدُودُ وَالْحِجَامَةُ وَالْمَشْيُ". وَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَدَّهُ الْعَبَّاسُ وَأَصْحَابُهُ رَضِيَ اللهُ عَنْهُمْ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَدَّنِي". فَكُلُّهُمْ أَمْسَكُوا، فَقَالَ: "لَا يَبْقَى أَحَدٌ مِمَّنْ فِي الْبَيْتِ إِلَّا لُدَّ، غَيْرَ عَمِّهِ الْعَبَّاسِ". قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ. (ت,جه)', 'ഇക്രിമ(റ): ഇബ്നുഅബ്ബാസ്(റ)വിന് കൊമ്പുവെക്കുന്ന മൂന്ന് അടിമകളുണ്ടായിരുന്നു. അവരിൽ രണ്ട് പേർ അദ്ദേഹത്തെയും കുടുംബത്തെയും സേവിക്കുന്നതിന് കൂലിപറ്റുന്നവരായിരുന്നു. ഒരാൾ അദ്ദേഹത്തിനും കുടുംബത്തിനും കൊമ്പുവെച്ചുകൊടുക്കും. ഇക്രിമ(റ) പറയുന്നു: ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "കൊമ്പുവെക്കുന്നവൻ എത്ര നല്ലവൻ, ദുഷിച്ച രക്തം അവൻ കളയുന്നു. കാഴ്ച നന്നാക്കുന്നു. കട്ടപിടിച്ചതിനെ നേർത്തതാക്കുന്നു." അദ്ദേഹം വീണ്ടും പറഞ്ഞു: നബി(സ) മിഅ്റാജ് പോയപ്പോൾ നബി(സ) ഓരോ കൂട്ടം മലക്കുകളുടെയും അടുത്ത്കൂടെ നടന്നപ്പോൾ അവരെല്ലാം പറഞ്ഞു: കൊമ്പുവെക്കൂ. നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് കൊമ്പുവെക്കുവാൻ നല്ല ദിവസം പതിനേഴാം ദിവസവും പത്തൊമ്പതാം ദിവസവും ഇരുപത്തൊന്നാം ദിവസവുമാകുന്നു." നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ചികിത്സക്ക് പ്രയോഗിക്കുന്നതിൽ നല്ലത് നസ്യവും ലദൂദും (വായയുടെ കോണിലൂടെ കഴിക്കുന്ന മരുന്ന്) കൊമ്പ് വെപ്പിക്കലും വയറിളക്കലുമാണ്." അബ്ബാസ്(റ)വും അനുചരരും നബി(സ)യെ ലദൂദ് കഴിപ്പിച്ചു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "ആരാണ് എന്നെ ലദൂദ് കുടിപ്പിച്ചത്?" എല്ലാവരും മിണ്ടാതിരുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "പിതൃസഹോദരൻ അബ്ബാസ്(റ) ഒഴികെ ഈ വീട്ടിൽ ലദൂദ് കുടിപ്പിക്കപ്പെടാതെ ആരും ബാക്കിയാവുകയില്ല." (തു,ജ)', 'عِكْرِمَةَ قَالَ', 'ഇക്രിമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 646, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ ثَوْبَانَ، عَنْ أَبِي كَبْشَةَ الأَنْمَارِيِّ، رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَحْتَجِمُ عَلَى هَامَتِه وَبَيْنَ كَتِفَيْه، وَهُوَ يَقُولُ: "مَنْ أَهْرَاقَ مِنْ هَذِهِ الدِّمَاءِ فَلَا يَضُرُّهُ أَنْ لَا يَتَدَاوَى بِشَيْءٍ لِشَيْءٍ". (د,جه)', 'അബൂകബ്ശ(റ)വിൽനിന്ന് സൗബാൻ(റ): നബി(സ) അവിടുത്തെ തലയിലും തോളുകൾക്കിടയിലും കൊമ്പുവെക്കാറുണ്ടായിരുന്നു. നബി(സ) പറയാറുണ്ടായിരുന്നു: "ആരെങ്കിലും ഈ രക്തം കളഞ്ഞാൽ പിന്നെ ചില രോഗങ്ങൾക്ക് ചികിത്സ ചെയ്യാതിരിക്കൽ അവന് പ്രശ്നമാവുകയില്ല." (ദ,ജ)', 'ثَوْبَانَ، عَنْ أَبِي كَبْشَةَ الأَنْمَارِيِّ،', 'അബൂകബ്ശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 647, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ ثَلَاثًا فِي الأَخْدَعَيْنِ وَالْكَاهِلِ. (د,ت,جه)', 'അനസ്(റ): നബി(സ) തന്റെ പിരടിയിലും കർണ്ണഞരമ്പുകളിലും മൂന്ന് പ്രാവശ്യം കൊമ്പുവെച്ചിട്ടുണ്ട്. (ദ,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 647, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عَبْدِ اللهِ بْنِ بُحَيْنَةَ رَضِيَ اللهُ عَنْهُ قَالَ: احْتَجَمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِلَحْيِ جَمَلٍ وَهُوَ مُحْرِمٌ وَسَطَ رَأْسِهِ. (ق,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ബുജൈറ(റ): നബി(സ) ഇഹ്റാം കെട്ടിയ അവസ്ഥയിൽ ഒട്ടകത്തിന്റെ താടിയെല്ലു കൊണ്ട് തലയുടെ നടുവിൽ കൊമ്പുവെച്ചു. (ബു,മു,ന,ജ)', 'عَبْدِ اللهِ بْنِ بُحَيْنَةَ', 'അബ്ദുല്ലാഹിബ്നു ബുജൈറ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 647, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: نَزَلَ جِبْرِيلُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِحِجَامَةِ الأَخْدَعَيْنِ وَالْكَاهِلِ. [ز: في سنده ضعيف] (جه)', 'അലി(റ): പിരടിയിലും കർണ്ണഞരമ്പുകളിലും കൊമ്പുവെക്കണമെന്ന സന്ദേശവുമായി ജിബ്രീൽ(അ) നബി(സ)യുടെ സമീപത്ത് വന്നിട്ടുണ്ട്. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 647, 648, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَقَطَ عَنْ فَرَسِهِ عَلَى جِذْعٍ، فَانْفَكَّتْ قَدَمُهُ. قَالَ وَكِيعٌ: يَعْنِي أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ عَلَيْهَا مِنْ وَثْئٍ. (د,جه)', 'ജാബിർ(റ): നബി(സ) തന്റെ കുതിരപ്പുറത്ത് നിന്ന് ഒരു പനത്തടിയുടെ മേൽ വീണു. നബി(സ)യുടെ കാൽ ഇളകി. വകീഅ്(റ) പറഞ്ഞു: നബി(സ) ഉളുക്ക് മാറാൻ കൊമ്പുവെച്ചു. (ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 648, 648, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ عَلَى وَرِكِهِ مِنْ وَثْءٍ كَانَ بِهِ. (د,ن)', 'ജാബിർ(റ): നിശ്ചയം നബി(സ) ഉളുക്ക് കാരണം ഊരമേൽ കൊമ്പുവെച്ചിരുന്നു. (ദ,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 648, 648, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَرَادَ الْحِجَامَةَ فَلْيَتَحَرَّ سَبْعَةَ عَشَرَ، أَوْ تِسْعَةَ عَشَرَ، أَوْ إِحْدَى وَعِشْرِينَ. وَلَا يَتَبَيَّغْ بِأَحَدِكُمُ الدَّمُ فَيَقْتُلَهُ". [ز: في سنده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും കൊമ്പുവെക്കാനുദ്ദേശിച്ചാൽ പതിനേഴാമത്തെയോ പത്തൊമ്പതാമത്തെയോ ഇരുപത്തിയൊന്നാമത്തെയോ ദിവസങ്ങൾ സൂക്ഷിക്കട്ടെ. നിങ്ങളിൽ നിന്ന് ഒരാളെയും രക്തം കൂടുതൽ കളഞ്ഞ് അതുവഴി കൊല്ലരുത്." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 648, 648, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: يَا نَافِعُ، قَدْ تَبَيَّغَ بِيَ الدَّمُ، فَالْتَمِسْ لِي حَجَّامًا، وَاجْعَلْهُ رَفِيقًا إِنِ اسْتَطَعْتَ، وَلَا تَجْعَلْهُ شَيْخًا كَبِيرًا وَلَا صَبِيًّا صَغِيرًا، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْحِجَامَةُ عَلَى الرِّيقِ أَمْثَلُ، وَفِيهِ شِفَاءٌ وَبَرَكَةٌ، وَتَزِيدُ فِي الْعَقْلِ وَفِي الْحِفْظِ. فَاحْتَجِمُوا عَلَى بَرَكَةِ اللهِ يَوْمَ الْخَمِيسِ، وَاجْتَنِبُوا الْحِجَامَةَ يَوْمَ الأَرْبِعَاءِ وَالْجُمُعَةِ وَالسَّبْتِ وَيَوْمَ الأَحَدِ تَحَرِّيًا، وَاحْتَجِمُوا يَوْمَ الاثْنَيْنِ وَالثُّلَاثَاءِ، فَإِنَّهُ الْيَوْمُ الَّذِي عَافَى اللهُ فِيهِ أَيُّوبَ مِنَ الْبَلَاءِ، وَضَرَبَهُ بِالْبَلَاءِ يَوْمَ الأَرْبِعَاءِ، فَإِنَّهُ لَا يَبْدُو جُذَامٌ وَلَا بَرَصٌ إِلَّا يَوْمَ الأَرْبِعَاءِ، أَوْ لَيْلَةَ الأَرْبِعَاءِ". (جه)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം പറഞ്ഞു: നാഫിഅ്, എന്റെ രക്തം നശിച്ചിരിക്കുന്നു. ഒരു കൊമ്പുവെക്കുന്നയാളെ തേടിക്കൊണ്ടുവരൂ. നിനക്ക് സാധിക്കുമെങ്കിൽ ഒരു യുവാവിനെ കൊണ്ടുവരിക. വൃദ്ധനെയോ കുട്ടിയെയോ കൊണ്ടുവരരുത്. നിശ്ചയം നബി(സ) പറുയന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ഭക്ഷണം കഴിക്കുന്നതിനു മുമ്പ് കൊമ്പുവെക്കുന്നതാണ് നല്ലത്. അതിൽ ബറകത്തും ശമനവുമുണ്ട്. അത് ബുദ്ധിയും ഓർമ്മശക്തിയും വർധിപ്പിക്കുകയും ചെയ്യും. അതുകൊണ്ട് വ്യാഴാഴ്ച ദിവസം അല്ലാഹുവിന്റെ ബറക്കത്തോടു കൂടെ നിങ്ങൾ കൊമ്പുവെക്കുക. ബുധൻ, വെള്ളി, ശനി, ഞായർ എന്നീ ദിവസങ്ങൾ സൂക്ഷമത പുലർത്തുവാൻ നിങ്ങൾ കൊമ്പുവെക്കൽ ഒഴിവാക്കുക. തിങ്കളും ചൊവ്വയും നിങ്ങൾ കൊമ്പുവെക്കുക. കാരണം ആ ദിവസത്തിലാണ് അയ്യൂബ് നബി(സ)യുടെ രോഗം അല്ലാഹു സുഖമാക്കിയത്. ബുധനാഴ്ച ദിവസമാണ് അദ്ദേഹത്തിന് അസുഖം നൽകിയത്. ബുധനാഴ്ചയാണ് വെള്ളപ്പാണ്ടും കുഷ്ഠരോഗവും വെളിവാകുന്നത്, അല്ലെങ്കിൽ ബുധനാഴ്ച രാവിൽ." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 648, 648, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ نَافِعٍ قَالَ: قَالَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: يَا نَافِعُ، تَبَيَّغَ بِيَ الدَّمُ، فَأْتِنِي بِحَجَّامٍ، وَاجْعَلْهُ شَابًّا، وَلَا تَجْعَلْهُ شَيْخًا وَلَا صَبِيًّا. قَالَ: وَقَالَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْحِجَامَةُ عَلَى الرِّيقِ أَمْثَلُ، وَهِيَ تَزِيدُ فِي الْعَقْلِ، وَتَزِيدُ فِي الْحِفْظِ، وَتَزِيدُ الْحَافِظَ حِفْظًا. فَمَنْ كَانَ مُحْتَجِمًا فَيَوْمَ الْخَمِيسِ، عَلَى اسْمِ اللهِ. وَاجْتَنِبُوا الْحِجَامَةَ يَوْمَ الْجُمُعَةِ وَيَوْمَ السَّبْتِ وَيَوْمَ الأَحَدِ، وَاحْتَجِمُوا يَوْمَ الاثْنَيْنِ وَالثُّلَاثَاءِ، وَاجْتَنِبُوا الْحِجَامَةَ يَوْمَ الأَرْبِعَاءِ، فَإِنَّهُ الْيَوْمُ الَّذِي أُصِيبَ فِيهِ أَيُّوبُ بِالْبَلَاءِ، وَمَا يَبْدُو جُذَامٌ وَلَا بَرَصٌ إِلَّا فِي يَوْمِ الأَرْبِعَاءِ، أَوْ لَيْلَةِ الأَرْبِعَاءِ". [ك: في سنده مجهول] (جه)', 'നാഫിഅ്(റ): ഇബ്നുഉമർ(റ) പറഞ്ഞു: നാഫിഅ്, എന്റെ രക്തം മോശമായിരിക്കുന്നു. ഒരു കൊമ്പുവെക്കുന്നയാളെ എനിക്ക് വേണ്ടി കൊണ്ടുവരണം. ഒരു യുവാവായ ആളെ കൊണ്ടുവന്നാൽ മതി. കുട്ടിയെയോ വൃദ്ധനെയോ പാടില്ല. നാഫിഅ്(റ) പറയുന്നു: ഇബ്നുഉമർ(റ) വീണ്ടും പറഞ്ഞു: നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പ്രാതലിനു മുമ്പ് കൊമ്പുവെക്കലാണ് നല്ലത്. അത് ബുദ്ധിശക്തി വർധിപ്പിക്കും. ഓർമ്മശക്തി വർധിപ്പിക്കും. മനഃപാഠമാക്കുന്നവന് ഗ്രാഹ്യശക്തി വർധിപ്പിക്കും. ആരെങ്കിലും കൊമ്പുവെക്കുകയാണെങ്കിൽ വ്യാഴ്യാഴ്ച ദിവസം അല്ലാഹുവിന്റെ നാമം കൊണ്ട് കൊമ്പുവെക്കുക. വെള്ളിയും ശനിയും ഞായറും കൊമ്പുവെക്കൽ ഉപേക്ഷിക്കുക. തിങ്കളും ചൊവ്വയും കൊമ്പുവെച്ചുകൊള്ളുക. ബുധനാഴ്ച കൊമ്പുവെക്കൽ ഉപേക്ഷിക്കുക. കാരണം അന്നാണ് അയ്യൂബ് നബി(അ)ന് രോഗം പിടിച്ചത്. ബുധനാഴ്ചയോ ബുധനാഴ്ച രാവിലോ അല്ലാതെ കുഷ്ടവും വെള്ളപ്പാണ്ടും വെളിവാകുകയില്ല." (ജ)', 'نَافِعٍ قَالَ', 'നാഫിഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ك: في سنده مجهول', null, 649, 649, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنِ احْتَجَمَ لِسَبْعَ عَشْرَةَ وَتِسْعَ عَشْرَةَ وَإِحْدَى وَعِشْرِينَ كَانَ شِفَاءً مِنْ كُلِّ دَاءٍ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പതിനേഴ്, പത്തൊമ്പത്, ഇരുപത്തിയൊന്ന് ദിവസങ്ങളിൽ ആരെങ്കിലും കൊമ്പുവെച്ചാൽ എല്ലാ രോഗത്തിൽ നിന്നും ശമനമുണ്ടാകും." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 649, 649, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يَنْهَى أَهْلَهُ عَنِ الْحِجَامَةِ يَوْمَ الثُّلَاثَاءِ، وَيَزْعُمُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنَّ يَوْمَ الثُّلَاثَاءِ يَوْمُ الدَّمِ، وَفِيهِ سَاعَةٌ لَا يَرْقَأُ". (د)', 'അബൂബക്റ(റ): ചൊവ്വാഴ്ച ദിവസം അദ്ദേഹം കുടുംബത്തെ കൊമ്പുവെക്കുന്നതിൽ നിന്ന് വിലക്കിയിരുന്നു. നബി(സ) പറഞ്ഞതായി അദ്ദേഹം പറയും: "ചൊവ്വാഴ്ച രക്തത്തിന്റെ ദിവസമാണ്. അന്ന് ഒരു പ്രത്യേക സമയത്ത് രക്തം വറ്റുകയില്ല." (ദ)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 649, 649, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "شِفَاءُ عِرْقِ النَّسَا أَلْيَةُ شَاةٍ أَعْرَابِيَّةٍ تُذَابُ، ثُمَّ تُجَزَّأُ ثَلَاثَةَ أَجْزَاءٍ، ثُمَّ يُشْرَبُ عَلَى الرِّيقِ فِي كُلِّ يَوْمٍ جُزْءٌ". (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഊരവേദനയുടെ ചികിത്സ, ഒരു നാടൻ ആടിന്റെ ഊര തിളപ്പിച്ചതാണ്, അതിനെ മൂന്ന് ഭാഗമാക്കി ഓരോ ദിവസവും വെറും വയറ്റിൽ ഓരോ ഭാഗം വീതം കുടിക്കണം." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 649, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهَا كَانَتْ إِذَا مَاتَ الْمَيِّتُ مِنْ أَهْلِهَا، فَاجْتَمَعَ لِذَلِكَ النِّسَاءُ ثُمَّ تَفَرَّقْنَ إِلَّا أَهْلَهَا وَخَاصَّتَهَا، أَمَرَتْ بِبُرْمَةٍ مِنْ تَلْبِينَةٍ فَطُبِخَتْ، ثُمَّ صُنِعَ ثَرِيدٌ فَصُبَّتِ التَّلْبِينَةُ عَلَيْهَا، ثُمَّ قَالَتْ: كُلْنَ مِنْهَا، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "التَّلْبِينَةُ مُجِمَّةٌ لِفُؤَادِ الْمَرِيضِ، تُذْهِبُ بَعْضَ الْحُزْنِ". (م)', 'ആഇശ(റ): മഹതിയുടെ കുടുംബത്തിലെ ആരെങ്കിലും പരേതനാവുകയും സ്ത്രീകളെല്ലാം ഒരുമിച്ചുകൂടി സ്വന്തക്കാരും ബന്ധുക്കളുമൊഴികെ എല്ലാവരും പിരിഞ്ഞുപോവുകയും ചെയ്താൽ കല്ലിൽ നിർമ്മിക്കപ്പെട്ട ഒരു പാത്രം കൊണ്ടുവരാൻ മഹതി കൽപിക്കുകയും അതിൽ തൽബീനത്ത് (തേനും പാലും സങ്കരമാക്കിയ ചാർ) പാകം ചെയ്യുകയും ചെയ്യും. പിന്നീട് ചാർ പുരട്ടിയ പത്തിരിയുണ്ടാക്കി അതിന്മേൽ തൽബീനത് ഒഴിക്കും. എന്നിട്ട് മഹതി പറയും: നിങ്ങളത് ഭക്ഷിക്കുക. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "തൽബീനത്ത് രോഗിയുടെ മനസ്സിനാശ്വാസമാണ്. അത് ദുഃഖത്തെ ദൂരീകരിക്കുകയും ചെയ്യും." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَخَذَ أَهْلَهُ الْوَعْكُ أَمَرَ بِالْحَسَاءِ. قَالَتْ: وَكَانَ يَقُولُ: "إِنَّهُ لَيَرْتُو فُؤَادَ الْحَزِينِ، وَيَسْرُو عَنْ فُؤَادِ السَّقِيمِ، كَمَا تَسْرُو إِحْدَاكُنَّ الْوَسَخَ عَنْ وَجْهِهَا بِالْمَاءِ". (ت,جه)', 'ആഇശ(റ): നബി(സ) തന്റെ കുടുംബത്തിൽ ആർക്കെങ്കിലും ക്ഷീണം ബാധിച്ചാൽ ഹസാഅ് (മാവും വെള്ളവും വെണ്ണയും ചേർത്തുണ്ടാക്കുന്ന പലഹാരം) കുടിക്കാൻ കൽപിക്കുമായിരുന്നു. എന്നിട്ടു പറയും: "അത് ദുഃഖിതന്റെ ഹൃദയത്തിന് ധൈര്യം പകരുകയും നിങ്ങൾ വെള്ളം കൊണ്ട് മുഖത്തെ അഴുക്ക് നീക്കുന്നതു പോലെ രോഗിയുടെ മനസ്സിന്റെ ദുഃഖമകറ്റുകയും ചെയ്യും." (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِالْبَغِيضِ النَّافِعِ، التَّلْبِينَةِ" يَعْنِي الْحَسَاءَ. قَالَتْ: وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اشْتَكَى أَحَدٌ مِنْ أَهْلِهِ، لَمْ تَزَلِ الْبُرْمَةُ عَلَى النَّارِ، حَتَّى يَنْتَهِيَ أَحَدُ طَرَفَيْهِ. يَعْنِي يَبْرَأُ أَوْ يَمُوتُ. (جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ശരീരത്തിന് വെറുപ്പുള്ളതും എന്നാൽ ഉപകാരപ്രതവുമായ പായസം നിങ്ങൾ കഴിച്ചുകൊള്ളുക. അതായത് ഹസാഅ് (മാവും വെള്ളവും വെണ്ണയും ചേർത്തണ്ടാക്കിയ പലഹാരം)". മഹതി പറയുന്നു: നബി(സ)യുടെ കുടുംബത്തിലാർക്കെങ്കിലും രോഗം ബാധിച്ചാൽ സുഖപ്പെടുകയോ മരണപ്പെടുകയോ ചെയ്യുന്നതു വരെ അടുപ്പത്ത് പാത്രം വെച്ച് കത്തിച്ചുകൊണ്ടിരിക്കുമായിരുന്നു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَادَ رَجُلًا، فَقَالَ لَهُ: "مَا تَشْتَهِي". فَقَالَ: أَشْتَهِي خُبْزَ بُرٍّ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ عِنْدَهُ خُبْزُ بُرٍّ فَلْيَبْعَثْ إِلَى أَخِيهِ". ثُمَّ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اشْتَهَى مَرِيضُ أَحَدِكُمْ شَيْئًا فَلْيُطْعِمْهُ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരിക്കൽ ഒരു രോഗിയെ സന്ദർശിച്ചു. അദ്ദേഹത്തോട് ചോദിച്ചു: "വല്ലതും ആഗ്രഹിക്കുന്നുണ്ടോ?" അയാൾ പറഞ്ഞു: ഗോതമ്പ് റൊട്ടിയാണ് ഞാൻ ആഗ്രഹിക്കുന്നത്? അപ്പോൾ നബി(സ) പറഞ്ഞു: "ആരുടെയെങ്കിലും പക്കൽ ഗോതമ്പുറൊട്ടിയുണ്ടെങ്കിൽ ഈ സഹോദരനിലേക്ക് കൊടുത്തയക്കുക". പിന്നീട് നബി(സ) പറഞ്ഞു: "രോഗിക്ക് വല്ലതിനോടും ആഗ്രഹമുണ്ടെങ്കിൽ അത് അവനെ ഭക്ഷിപ്പിക്കണം." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 651, 651, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى مَرِيضٍ يَعُودُهُ، قَالَ: "أَتَشْتَهِي شَيْئًا". قَالَ: أَشْتَهِي كَعْكًا، قَالَ: "نَعَمْ". فَطَلَبُوا لَهُ. [ز: في سنده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഒരു രോഗിയുടെ സമീപത്ത് സന്ദർശകനായി ചെന്നു. അയാളോട് ചോദിച്ചു: "താങ്കൾക്ക് വല്ലതും ആവശ്യമുണ്ടോ?" അയാൾ പറഞ്ഞു: എനിക്ക് കേക്ക് വേണം. നബി(സ) പറഞ്ഞു: "അതെ." പിന്നീട് അനുയായികൾ അദ്ദേഹത്തിനു വേണ്ടി കേക്ക് അന്വേഷിച്ചുപോയി. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 651, 651, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُكْرِهُوا مَرْضَاكُمْ عَلَى الطَّعَامِ، فَإِنَّ اللهَ يُطْعِمُهُمْ وَيَسْقِيهِمْ". قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ. (ت,جه)', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ രോഗികളെ നിങ്ങൾ ഭക്ഷണപദാർത്ഥങ്ങളുടെ മേൽ നിർബന്ധിപ്പിക്കരുത്. നിശ്ചമായും അല്ലാഹുവാണ് അവരെ ഭക്ഷിപ്പിക്കുന്നതും കുടിപ്പിക്കുന്നതും." (തു,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 651, 651, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَرَادَتْ أُمِّي أَنْ تُسَمِّنَنِي لِدُخُولِي عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ أَقْبَلْ عَلَيْهَا بِشَيْءٍ مِمَّا تُرِيدُ، حَتَّى أَطْعَمَتْنِي الْقِثَّاءَ بِالرُّطَبِ، فَسَمِنْتُ عَلَيْهِ كَأَحْسَنِ السِّمَنِ. (د,جه)', 'ആഇശ(റ): നബി(സ)യുടെ മേൽ പ്രവേശിക്കുന്നതിനുവേണ്ടി എന്നെ തടിച്ചവളാക്കാൻ എന്റെ ഉമ്മ ആഗ്രഹിച്ചു. പക്ഷെ അവർ ഉദ്ദേശിച്ച ഒന്നുകൊണ്ടുംതന്നെ ഞാനങ്ങനെയായില്ല. അങ്ങനെയവരെന്നെ കക്കരി ഈത്തപ്പഴത്തോടൊപ്പം തീറ്റിക്കുകയും, ഞാൻ നല്ലവണ്ണം തടിച്ച് കൊഴുക്കുകയും ചെയ്തു. (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 651, 651, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ رَضِيَ اللهُ عَنْهُ: أَنَّ طَبِيبًا سَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ضِفْدَعٍ يَجْعَلُهَا فِي دَوَاءٍ، فَنَهَاهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ قَتْلِهَا. (د,ن)', 'അബ്ദുർറഹ്മാനുബ്നു ഉസ്മാൻ(റ): ഒരു വൈദ്യൻ നബി(സ)യോട് മരുന്നിൽ ചേർക്കപ്പെടുന്ന തവളയെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ നബി(സ) അതിനെ വധിക്കൽ നിരോധിച്ചു. (ദ,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ', 'അബ്ദുർറഹ്മാനുബ്നു ഉസ്മാൻ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 651, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَرَدَّى مِنْ جَبَلٍ فَقَتَلَ نَفْسَهُ فَهُوَ فِي نَارِ جَهَنَّمَ يَتَرَدَّى فِيهِ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا، وَمَنْ تَحَسَّى سُمًّا فَقَتَلَ نَفْسَهُ فَسُمُّهُ فِي يَدِهِ يَتَحَسَّاهُ فِي نَارِ جَهَنَّمَ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا، وَمَنْ قَتَلَ نَفْسَهُ بِحَدِيدَةٍ فَحَدِيدَتُهُ فِي يَدِهِ يَجَأُ بِهَا فِي بَطْنِهِ فِي نَارِ جَهَنَّمَ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "ഒരാൾ മലയുടെ മുകളിൽ നിന്ന് ചാടി ആത്മഹത്യ ചെയ്തു. എങ്കിൽ അവന്റെ വാസസ്ഥലം നരകമായിരിക്കും. ശാശ്വതമായി അതിൽ വീണുകൊണ്ടേയിരിക്കും. വല്ലവനും വിഷം കഴിച്ച് ആത്മഹത്യ ചെയ്താൽ ശാശ്വതമായി നരകത്തിൽ വെച്ച് കയ്യിലുള്ള വിഷം കഴിച്ചുകൊണ്ടേയിരിക്കും. ഒരായുധം പ്രയോഗിച്ച് ഒരാൾ ആത്മഹത്യ ചെയ്താൽ കാലാകാലവും നരകത്തിൽ വെച്ച് കത്തി കയ്യിൽ പിടിച്ച് അവൻ തന്റെ വയറ് കുത്തിക്കീറിക്കൊണ്ടേയിരിക്കും." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الدَّوَاءِ الْخَبِيثِ. يَعْنِي السُّمَّ. (د,ت,جه)', 'അബൂഹുറൈറ(റ): മോശമായ മരുന്നുകളെ നബി(സ) വിലക്കി. വിഷമാണ് അവിടന്ന് ഉദ്ദേശിച്ചത്. (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَاسًا مِنْ عُرَيْنَةَ قَدِمُوا الْمَدِينَةَ فَاجْتَوَوْهَا، فَبَعَثَهُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي إِبِلِ الصَّدَقَةِ وَقَالَ: "اشْرَبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا". (ق,د,ت,ن,جه)', 'അനസ്(റ): ഉറൈന ഗോത്രത്തിൽപെട്ട ചില ആളുകൾ മദീനയിലേക്ക് വരികയും മദീനയിലെ അന്തരീക്ഷം ഇഷ്ടപ്പെടാത്ത അവർക്ക് ചില രോഗങ്ങൾ വരികയും ചെയ്തു. അപ്പോൾ സ്വദഖയുടെ ഒട്ടകങ്ങളുടെ അടുത്തേക്ക് നബി(സ) അവരെ അയക്കുകയും അവരോട് പറയുകയും ചെയ്തു: "നിങ്ങൾ അവയുടെ പാലും മൂത്രവും കുടിക്കുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَاسًا مِنْ عُرَيْنَةَ قَدِمُوا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَاجْتَوَوُا الْمَدِينَةَ، فَقَالَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ خَرَجْتُمْ إِلَى ذَوْدٍ لَنَا، فَشَرِبْتُمْ مِنْ أَلْبَانِهَا وَأَبْوَالِهَا". فَفَعَلُوا. (جه)', 'അനസ്(റ): ഉറൈന ഗോത്രത്തിൽപെട്ട ചിലയാളുകൾ നബി(സ)യുടെയടുത്ത് വന്നു. പക്ഷേ, മദീനയിലെ അന്തരീക്ഷം അവരെ അസന്തുഷ്ടരാക്കി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഞങ്ങളുടെ ഏതെങ്കിലും ഓരൊട്ടകത്തെ സമീപിച്ച് അതിന്റെ പാലും മൂത്രവും കുടിച്ചെങ്കിൽ." അപ്പോൾ അവരങ്ങനെ ചെയ്തു. (ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ طَارِقِ بْنِ سُوَيْدٍ الْحَضْرَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، إِنَّ بِأَرْضِنَا أَعْنَابًا نَعْتَصِرُهَا، فَنَشْرَبُ مِنْهَا؟ قَالَ: "لَا". فَرَاجَعْتُهُ، قُلْتُ: إِنَّا نَسْتَشْفِي بِهِ لِلْمَرِيضِ. قَالَ: "إِنَّ ذَلِكَ لَيْسَ بِشِفَاءٍ، وَلَكِنَّهُ دَاءٌ". (د,جه)', 'ത്വാരിഖുബ്നു സുവൈദിൽ ഹള്റമി(റ): ഞാൻ ചോദിച്ചു: നബിയേ, ഞങ്ങളുടെ നാട്ടിൽ മുന്തിരിയുണ്ട്. അതിൽനിന്ന് ഞങ്ങൾ വീഞ്ഞുണ്ടാക്കുന്നു. ഞങ്ങൾ അത് കുടിക്കട്ടെയോ? നബി(സ) പറഞ്ഞു: "അരുത്." ഞാൻ വീണ്ടും വീണ്ടും ചോദിച്ചു. പിന്നെ ഞാൻ പറഞ്ഞു: ഞങ്ങൾ അതുകൊണ്ട് രോഗിയെ ചികിത്സിക്കാറുണ്ട്. നബി(സ) പറഞ്ഞു: "മദ്യം മരുന്നല്ല, മറിച്ച് രോഗമാണ്." (ദ,ജ)', 'طَارِقِ بْنِ سُوَيْدٍ الْحَضْرَمِيِّ', 'ത്വാരിഖുബ്നു സുവൈദിൽ ഹള്റമി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 653, 653, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ وَائِلِ بْنِ حُجْرٍ الْحَضْرَمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ شَهِدَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَسَأَلَهُ سُوَيْدُ بْنُ طَارِقٍ - أَوْ طَارِقُ بْنُ سُوَيْدٍ - عَنِ الْخَمْرِ فَنَهَاهُ عَنْهُ، فَقَالَ: إِنَّا نَتَدَاوَى بِهَا؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهَا لَيْسَتْ بِدَوَاءٍ، وَلَكِنَّهَا دَاءٌ". (م,د,ت,جه)', 'വാഇലുബ്നു ഹുജ്റിൽ ഹള്റമി(റ): അദ്ദേഹം നബി(സ)യുടെ അടുക്കൽ സന്നിഹിതനായിരുന്നപ്പോൾ സുവൈദുബ്നു ത്വാരിഖ്(റ) - അല്ലെങ്കിൽ ത്വാരിഖുബ്നു സുവൈദ്(റ) - നബി(സ)യോട് കള്ളിനെക്കുറിച്ച് ചോദിക്കുകയും നബി(സ) അതിനെ അദ്ദേഹത്തിന് വിലക്കുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ അത് മരുന്നായി ഉപയോഗിക്കാറുണ്ടായിരുന്നല്ലോ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "തീർച്ചയായും അത് മരുന്നല്ല, മറിച്ച് രോഗമാണ്." (മു,ദ,തു,ജ)', 'وَائِلِ بْنِ حُجْرٍ الْحَضْرَمِيِّ', 'വാഇലുബ്നു ഹുജ്റിൽ ഹള്റമി(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 653, 653, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: ذُكِرَتِ الْحُمَّى عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَبَّهَا رَجُلٌ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَسُبَّهَا، فَإِنَّهَا تَنْفِي الذُّنُوبَ كَمَا تَنْفِي النَّارُ خَبَثَ الْحَدِيدِ". [ز: في سنده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ)യോട് പനിയെക്കുറിച്ച് പറയപ്പെട്ടു. അപ്പോൾ ഒരാൾ പനിയെ ആക്ഷേപിച്ചു. അന്നേരം നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പനിയെ ആക്ഷേപിക്കരുത്. ഇരുമ്പിന്റെ കേടുകൾ തീ കളയുന്നതു പോലെ ദോഷങ്ങളെ അത് പോക്കിക്കളയും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 653, 653, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ عَادَ مَرِيضًا - وَمَعَهُ أَبُو هُرَيْرَةَ - مِنْ وَعْكٍ كَانَ بِهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَبْشِرْ، فَإِنَّ اللهَ يَقُولُ: هِيَ نَارِي أُسَلِّطُهَا عَلَى عَبْدِيَ الْمُؤْمِنِ فِي الدُّنْيَا لِتَكُونَ حَظَّهُ مِنَ النَّارِ فِي الآخِرَةِ". (جه)', 'അബൂഹുറൈറ(റ): പനി ബാധിച്ച ഒരാളെ നബി(സ) സന്ദർശിച്ചു. കൂടെ അബൂഹുറൈറ(റ)വുമുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ സന്തോഷിക്കുക, നിശ്ചയം അല്ലാഹു പറയുന്നു: അത് എന്റെ മുഅ്മിനായ അടിമക്ക് ആഖിറത്തിലെ നരകത്തത്തീയിൽ നിന്നുള്ള വിഹിതത്തിനു പകരമായി ഞാൻ ദുൻയാവിൽ വെച്ച് നൽകുന്നതാണ്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 653, 653, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى أُمِّ السَّائِبِ، أَوْ أُمِّ الْمُسَيَّبِ، فَقَالَ: "مَا لَكِ يَا أُمَّ السَّائِبِ - أَوْ يَا أُمَّ الْمُسَيَّبِ - تُزَفْزِفِينَ". قَالَتِ: الْحُمَّى، لَا بَارَكَ اللهُ فِيهَا، فَقَالَ: "لَا تَسُبِّي الْحُمَّى، فَإِنَّهَا تُذْهِبُ خَطَايَا بَنِي آدَمَ كَمَا يُذْهِبُ الْكِيرُ خَبَثَ الْحَدِيدِ". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഉമ്മുസാഇബ്(റ)യുടെ അല്ലെങ്കിൽ ഉമ്മുൽ മുസയ്യബ്(റ)യുടെ അടുത്തേക്ക് നബി(സ) ചെന്നു. എന്നിട്ട് ചേദിച്ചു: "ഉമ്മുസാഇബ്, - അല്ലെങ്കിൽ: ഉമ്മുൽമുസയ്യിബ്, - എന്തു കൊണ്ടാണ് വിറക്കുന്നത്?" മഹതി പറഞ്ഞു: പനിയാണ്. അതിൽ അല്ലാഹു ബറകത്ത് ചെയ്യില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "പനിയെ ആക്ഷേപിക്കരുത്. കാരണം, ഇരുമ്പിന്റെ മ്ലേഛത തീ പോക്കുന്നത് പോലെ ആദം സന്തതികളുടെ ദോഷങ്ങൾ പനി നീക്കിക്കളയുന്നതാണ്." (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 654, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنِ الْحَسَنِ الْبَصْرِيِّ - رَحِمَهُ اللهُ تَعَالَى - قَالَ: كَانُوا يَرْتَجُونَ الْحُمَّى لَيْلَةً، كَفَّارَةً لِمَا نَقَصَ مِنَ الذُّنُوبِ. (ت)', 'ഹസനുൽ ബസ്വരി(റ): അദ്ദേഹം പറഞ്ഞു: ചെയ്ത തെറ്റുകൾക്ക് പ്രായശ്ചിത്തമായി രാത്രി സമയങ്ങളിൽ പനിയുണ്ടാവാൻ അവർ ആഗ്രഹിക്കാറുണ്ടായിരുന്നു. (തു)', 'الْحَسَنِ الْبَصْرِيِّ - رَحِمَهُ اللهُ تَعَالَى - قَالَ', 'ഹസനുൽ ബസ്വരി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 654, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَصَابَ أَحَدَكُمُ الْحُمَّى فَإِنَّ الْحُمَّى قِطْعَةٌ مِنَ النَّارِ، فَلْيُطْفِئْهَا عَنْهُ بِالْمَاءِ، فَلْيَسْتَنْقِعْ نَهْرًا جَارِيًا، لِيَسْتَقْبِلْ جِرْيَتَهُ فَيَقُولَ: بِسْمِ اللهِ، اللَّهُمَّ اشْفِ عَبْدَكَ، وَصَدِّقْ رَسُولَكَ. بَعْدَ صَلَاةِ الصُّبْحِ قَبْلَ طُلُوعِ الشَّمْسِ، فَلْيَغْتَمِسْ فِيهِ ثَلَاثَ غَمَسَاتٍ ثَلَاثَةَ أَيَّامٍ، فَإِنْ لَمْ يَبْرَأْ فِي ثَلَاثٍ فَخَمْسٍ، وَإِنْ لَمْ يَبْرَأْ فِي خَمْسٍ فَسَبْعٍ، فَإِنْ لَمْ يَبْرَأْ فِي سَبْعٍ فَتِسْعٍ، فَإِنَّهَا لَا تَكَادُ تُجَاوِزُ تِسْعًا بِإِذْنِ اللهِ". (ت)', 'സൗബാൻ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാർക്കെങ്കിലും പനി ബാധിച്ചാൽ, വെള്ളം കൊണ്ട് അവൻ അതിനെ ലഘൂകരിക്കുക. തീർച്ചയായും പനി നരകത്തിന്റെ ഒരു അംശമാണ്. അതിനാൽ ഒഴുകുന്ന ഒരു നദി കണ്ടെത്തി, അതിന്റെ ഒഴുക്കിനഭിമുഖമായി അവൻ നിൽക്കുക. എന്നിട്ട് പറയുക: അല്ലാഹുവിന്റെ നാമം കൊണ്ട് നിന്റെ അടിമക്ക് നീ ശമനം നൽകുക, നിന്റെ ദൂതനെ നീ സത്യമാക്കുക. സുബ്ഹിയുടെയും സൂര്യോദയത്തിന്റേയുമിടയിലാണ് ഇങ്ങനെ ചെയ്യേണ്ടത്. എന്നിട്ട് മൂന്ന് പ്രാവശ്യം വെള്ളത്തിൽ മുങ്ങുക. മൂന്ന് ദിവസം ഇപ്രകാരം ചെയ്യുക. മൂന്ന് ദിവസം കൊണ്ട് രോഗം ഭേദമായില്ലെങ്കിൽ അഞ്ച് ദിവസം മുങ്ങുക. അഞ്ച് ദിവസം കൊണ്ട് സുഖമായില്ലെങ്കിൽ ഏഴ് ദിവസം മുങ്ങുക. ഏഴ് ദിവസം കൊണ്ട് സുഖമായില്ലെങ്കിൽ ഒമ്പത് ദിവസം മുങ്ങുക. അല്ലാഹുവിന്റെ അനുവാദത്താൽ ഒമ്പത് ദിവസത്തേക്കാൾ അത് കൂടുകയില്ല." (തു)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 654, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهَا كَانَتْ إِذَا أُتِيتْ بِالْمَرْأَةِ قَدْ حُمَّتْ تَدْعُو لَهَا، أَخَذَتِ الْمَاءَ فَصَبَّتْهُ بَيْنَهَا وَبَيْنَ جَيْبِهَا. قَالَتْ: وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُنَا أَنْ نَبْرُدَهَا بِالْمَاءِ. (خ)', 'അസ്മാഅ് ബിൻത് അബീബക്ർ(റ): പനിപിടിച്ച സ്ത്രീയെ മഹതിയുടെ അടുക്കൽ കൊണ്ടുവന്നാൽ ആദ്യം അവൾക്കുവേണ്ടി പ്രാർത്ഥിക്കും. എന്നിട്ട് തണുത്ത വെള്ളമെടുത്ത് അവളുടെ നെഞ്ചത്ത് ഒഴിക്കും. മഹതി പറയുന്നു: പനിയെ വെള്ളം കൊണ്ട് തണുപ്പിക്കാൻ തിരുമേനി(സ) ഞങ്ങളോട് കൽപിക്കാറുണ്ടായിരുന്നു. (ബു)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻത് അബീബക്ർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 654, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "إِنَّ شِدَّةَ الْحُمَّى مِنْ فَيْحِ جَهَنَّمَ، فَابْرُدُوهَا بِالْمَاءِ". (م,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "കഠിനമായ പനി നരകത്തിന്റെ ചൂടിൽ പെട്ടതാണ്. അതുകൊണ്ട് വെള്ളം കൊണ്ട് അതിനെ തണുപ്പിക്കുക." (മു,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 655, 655, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْحُمَّى مِنْ فَيْحِ جَهَنَّمَ، فَابْرُدُوهَا بِالْمَاءِ". فَدَخَلَ عَلَى ابْنِ لِعَمَّارٍ فَقَالَ: "اكْشِفِ الْبَاسَ رَبَّ النَّاسِ، إِلَهَ النَّاسِ". (ق,ت,جه)', 'റാഫിഉബ്നു ഖദീജ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "പനി നരകത്തിന്റെ ചൂടിൽ പെട്ടതാണ്. അതിനാൽ വെള്ളം കൊണ്ടതിനെ തണുപ്പിക്കുക." തിരുമേനി(സ) അമ്മാർ(റ)വിന്റെ മകന്റെ സമീപം പ്രവേശിച്ചു. എന്നിട്ട് പറഞ്ഞു: "ജനങ്ങളുടെ രക്ഷിതാവേ, ജനങ്ങളുടെ ആരാധ്യനേ, നീ രോഗം അകറ്റുക." (ബു,മു,തു,ജ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 655, 655, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهَا كَانَتْ تُؤْتَى بِالْمَرْأَةِ الْمَوْعُوكَةِ، فَتَدْعُو بِالْمَاءِ فَتَصُبُّهُ فِي جَيْبِهَا، وَتَقُولُ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ابْرُدُوهَا بِالْمَاءِ". وَقَالَ: "إِنَّهَا مِنْ فَيْحِ جَهَنَّمَ". (ق,ت,جه)', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ): പനിപിടിച്ച സ്ത്രീയെ അവരുടെ അടുത്ത് കൊണ്ടുവരാറുണ്ടായിരുന്നു. അപ്പോൾ അവർ വെള്ളം കൊണ്ടുവരാൻ ആവശ്യപ്പെടുകയും വെള്ളം ആ സ്ത്രീയുടെ കക്ഷത്തിൽ ഒഴിക്കുകയും എന്നിട്ട് ഇപ്രകാരം പറയുകയും ചെയ്യാറുണ്ടായിരുന്നു. നബി(സ) പറഞ്ഞു: "പനിയെ നിങ്ങൾ വെള്ളം കൊണ്ട് തണുപ്പിക്കുക." നബി(സ) പറഞ്ഞു: "നിശ്ചയം പനി നരകജ്വാലയിൽ പെട്ടതാണ്." (ബു,മു,തു,ജ)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 655, 655, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْحُمَّى كِيرٌ مِنْ كِيرِ جَهَنَّمَ، فَنَحُّوهَا عَنْكُمْ بِالْمَاءِ الْبَارِدِ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പനി നരകത്തിന്റെ തീനാളത്തിൽപ്പെട്ട ഒരു തീനാളമാണ്, തണുത്ത വെള്ളമുപയോഗിച്ച് നിങ്ങളതിനെ അകറ്റുക." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 655, 655, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْحُمَّى فَوْرٌ مِنَ النَّارِ، فَأَبْرِدُوهَا بِالْمَاءِ". (ق,ت,جه)', 'റാഫിഉബ്നു ഖദീജ്(റ): "പനി നരകത്തിന്റെ കാഠിന്യത്തിൽ നിന്നൽപമാണ്. അതിനാൽ വെള്ളം കൊണ്ടതിനെ തണുപ്പിക്കുക." (ബു,മു,തു,ജ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 655, 655, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهُمْ مِنَ الْحُمَّى وَمِنَ الأَوْجَاعِ كُلِّهَا أَنْ يَقُولُوا: "بِسْمِ اللهِ الْكَبِيرِ، أَعُوذُ بِاللهِ الْعَظِيمِ مِنْ شَرِّ عِرْقٍ نَعَّارٍ، وَمِنْ شَرِّ حَرِّ النَّارِ". وفي رواية: "يَعَّارٍ". (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): പനിയിൽ നിന്നും മുഴുവൻ വേദനകളിൽ നിന്നും രക്ഷ നേടാൻ നബി(സ) ഇത് ചൊല്ലുവാൻ പറയുമായിരുന്നു: "വലിയവനായ അല്ലാഹുവിന്റെ നാമം കൊണ്ട്, കത്തിയൊലിക്കുന്ന രക്തമുള്ള ഞരമ്പിന്റെ ശർറിൽ നിന്നും നരകത്തിന്റെ ചൂടിന്റെ ശർറിൽ നിന്നും ഉന്നതനായ അല്ലാഹുവിനോട് ഞാൻ കാവൽ തേടുന്നു." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 655, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=11 and h.hadith_no=119), 1, 'وَفِي رِوَايَةٍ: "يَعَّارٍ". (ت,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى جِبْرَائِيلُ عَلَيْهِ السَّلَامُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُوعَكُ، فَقَالَ: "بِسْمِ اللهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ حَسَدِ حَاسِدٍ، وَمِنْ كُلِّ عَيْنٍ، اللهُ يَشْفِيكَ". (جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): നബി(സ)ക്ക് പനിക്കുന്ന സമയത്ത് ജബ്റാഈൽ(അ) നബി(സ)യുടെ അടുത്തേക്ക് വന്നു. എന്നിട്ട് പറഞ്ഞു: "താങ്കളെ ബുദ്ധിമുട്ടാക്കുന്ന എല്ലാ കാര്യങ്ങളിൽ നിന്നും അസൂയക്കാരന്റെ അസൂയയിൽ നിന്നും എല്ലാ കണ്ണേറുകളിൽ നിന്നും അല്ലാഹുവിന്റെ നാമം കൊണ്ട് ഞാൻ താങ്കളെ ചികിത്സിക്കുന്നു. അല്ലാഹു താങ്കളെ സുഖപ്പെടുത്തും." (ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، إِذَا أَتَى الْمَرِيضَ فَدَعَا لَهُ، قَالَ: "أَذْهِبِ الْبَاسَ، رَبَّ النَّاسْ، وَاشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا". (جه)', 'ആഇശ(റ): നബി(സ) ഒരു രോഗിയുടെ അടുത്ത് ചെന്നാൽ അവന് വേണ്ടി പ്രാർത്ഥിക്കും. നബി(സ) പറയും: "ജനങ്ങളുടെ രക്ഷിതാവേ, ബുദ്ധിമുട്ടുകൾ നീക്കിക്കൊടുക്കുക. നീ ശമിപ്പിക്കുക. നീയാണ് ശമനം നൽകുന്നവൻ. നിന്റെ ശമനമല്ലാതെ ഒരു ശമനവുമില്ല. ഒരു രോഗത്തെയും ഒഴിവാക്കാത്ത ശമനമാണത്." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ مِمَّا يَقُولُ لِلْمَرِيضِ بِبُزَاقِهِ بِإِصْبَعِهِ: "بِسْمِ اللهِ، تُرْبَةُ أَرْضِنَا، بِرِيقَةِ بَعْضِنَا، لِيُشْفَى سَقِيمُنَا، بِإِذْنِ رَبِّنَا". (ق,د,جه)', 'ആഇശ(റ): നബി(സ) തന്റെ ഉമിനീർ വിരലുകളിലാക്കി രോഗിയോട് പറയുന്നവയിൽ പെട്ടതാണിത്: "അല്ലാഹുവിന്റെ നാമം കൊണ്ട്, ഞങ്ങളുടെ ഭൂമിയുടെ മണ്ണാണിത്, ഞങ്ങളിൽ നിന്നൊരാളുടെ ഉമിനീർ കൊണ്ട്, ഞങ്ങളുടെ രക്ഷിതാവിന്റെ അനുവാദത്തോടെ രോഗിയുടെ രോഗം സുഖപ്പെടാൻ." (ബു,മു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ الثَّقَفِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَبِي وَجَعٌ قَدْ كَادَ يُبْطِلُنِي، فَقَالَ لِيَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اجْعَلْ يَدَكَ الْيُمْنَى عَلَيْهِ وَقُلْ: بِسْمِ اللهِ، أَعُوذُ بِعِزَّةِ اللهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ. سَبْعَ مَرَّاتٍ". فَقُلْتُ ذَلِكَ فَشَفَانِيَ اللهُ. (م,د,ت,جه)', 'ഉസ്മാനുബ്നു അബിൽ ആസിസ്സഖഫി(റ): ക്ഷീണിപ്പിക്കുന്ന വേദനയോടു കൂടി നബി(സ)യുടെ സന്നിധിയിലേക്ക് ഞാൻ ചെന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിന്റെ വലതുകൈ വേദനയുള്ള സ്ഥലത്ത് വെച്ചിട്ട് ഏഴ് പ്രാവശ്യം പറയുക: അല്ലാഹുവിന്റെ നാമം കൊണ്ട്, ഞാനനുഭവിക്കുന്നതിൽ നിന്നും എനിക്ക് വരാനിരിക്കുന്നതായി ഞാൻ പേടിക്കുന്നതിൽ നിന്നും അല്ലാഹുവിന്റെ മഹത്വം കൊണ്ടും ശക്തി കൊണ്ടും ഞാൻ കാവൽ തേടുന്നു." ഞാനത് ചൊല്ലി. അല്ലാഹു എന്നെ സുഖപ്പെടുത്തി. (മു,ദ,തു,ജ)', 'عُثْمَانَ بْنِ أَبِي الْعَاصِ الثَّقَفِيِّ', 'ഉസ്മാനുബ്നു അബിൽ ആസിസ്സഖഫി(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ جِبْرَائِيلَ أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مُحَمَّدُ، اشْتَكَيْتَ؟ قَالَ: "نَعَمْ". قَالَ: "بِسْمِ اللهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنٍ أَوْ حَاسِدٍ اللهُ يَشْفِيكَ، بِسْمِ اللهِ أَرْقِيكَ". (م,ت,جه)', 'അബൂസഇൗദ്(റ): ജിബ്രീൽ(അ) നബി(സ)യുടെ സന്നിധിയിൽ വന്നുപറഞ്ഞു: മുഹമ്മദേ, താങ്കൾക്ക് രോഗം ബാധിച്ചിരിക്കുന്നോ? നബി(സ) പറഞ്ഞു: "അതെ." ജിബ്രീൽ(അ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ നാമം കൊണ്ട് ഞാൻ അങ്ങയെ മന്ത്രിക്കുന്നു. താങ്കളെ ബുദ്ധിമുട്ടാക്കുന്ന എല്ലാ കാര്യങ്ങളിൽ നിന്നും എല്ലാ മനുഷ്യരിൽ നിന്നും, അല്ലെങ്കിൽ കണ്ണേറിൽ നിന്നും, അല്ലെങ്കിൽ അസൂയക്കാരനിൽ നിന്നും അല്ലാഹു അങ്ങേക്ക് ശമനം നൽകും. അല്ലാഹുവിന്റെ നാമം കൊണ്ട് ഞാൻ താങ്കളെ മന്ത്രിക്കുന്നു." (മു,തു,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഇൗദ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 656, 657, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي، فَقَالَ لِي: "أَلَا أَرْقِيكَ بِرُقْيَةٍ جَاءَنِي بِهَا جِبْرَائِيلُ". قُلْتُ: بِأَبِي وَأُمِّي، بَلَى يَا رَسُولَ اللهِ. قَالَ: "بِسْمِ اللهِ أَرْقِيكَ، وَاللهُ يَشْفِيكَ، مِنْ كُلِّ دَاءٍ فِيكَ. مِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ، وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ". ثَلَاثَ مَرَّاتٍ. [ز: في سنده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) എന്നെ സന്ദർശിക്കാൻ വന്നു. എന്നോട് പറഞ്ഞു: "ജിബ്രീൽ(അ) എനിക്ക് കൊണ്ടുവന്ന മന്ത്രം കൊണ്ട് ഞാൻ നിന്നെ മന്ത്രിക്കട്ടെയോ?" ഞാൻ പറഞ്ഞു: അതെ റസൂലേ, എന്റെ മാതാവും പിതാവും അവിടുത്തേക്ക് ദൺഢമാണ്. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ നാമം കൊണ്ട് നിന്നെ ഞാൻ മന്ത്രിക്കുന്നു. നിന്റെ എല്ലാ രോഗങ്ങളിൽ നിന്നും, കെട്ടിൽ ഊതുന്നവരുടെ ശർറിൽ നിന്നും അസൂയക്കാരൻ അസൂയ വെച്ചാലുണ്ടാകുന്ന ശർറിൽ നിന്നും അല്ലാഹു നിന്നെ സുഖപ്പെടുത്തും." നബി(സ) മൂന്ന് പ്രാവശ്യം ഇങ്ങനെ പറഞ്ഞു. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 657, 657, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَوِّذُ الْحَسَنَ وَالْحُسَيْنَ، يَقُولُ: "أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ". قَالَ: "وَكَانَ أَبُونَا إِبْرَاهِيمُ يُعَوِّذُ بِهَا إِسْمَعِيلَ وَإِسْحَقَ". أَوْ قَالَ: "إِسْمَعِيلَ وَيَعْقُوبَ". (خ,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഹസൻ(റ)വിനെയും ഹുസൈൻ(റ)നെയും മന്ത്രിക്കാറുണ്ടായിരുന്നു. തിരുമേനി(സ) പറയും: "അല്ലാഹുവിന്റെ പൂർണ്ണമായ വാക്യങ്ങൾ കൊണ്ട് ഞാൻ കാവൽ തേടുന്നു. സകല പിശാചിൽ നിന്നും വിഷജന്തുക്കളിൽ നിന്നും പൈശാചിക കണ്ണുകളിൽ നിന്നും." നബി(സ) പറഞ്ഞു: "നമ്മുടെ പിതാമഹൻ ഇബ്റാഹീം(അ) ഇസ്മാഈൽ(അ)നെയും ഇസ്ഹാഖ്(അ)നെയും ഇത് കൊണ്ട് മന്ത്രിക്കാറുണ്ടായിരുന്നു. അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞു: "ഇസ്മാഈൽ(അ)നെയും യഅ്ഖൂബ്(അ)നെയും." (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 657, 657, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ خَوْلَةَ بِنْتِ حَكِيمٍ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ أَنَّ أَحَدَكُمْ إِذَا نَزَلَ مَنْزِلًا قَالَ: أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّةِ مِنْ شَرِّ مَا خَلَقَ، لَمْ يَضُرَّهُ فِي ذَلِكَ الْمَنْزِلِ شَيْءٌ حَتَّى يَرْتَحِلَ مِنْهُ". (م,ت,جه)', 'ഖൗലത്ത് ബിൻത് ഹകീം(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും ഒരു വീട്ടിൽ ചെല്ലുകയും ''അല്ലാഹുവിന്റെ പൂർണ്ണമായ വാക്യം കൊണ്ട്, അവൻ സൃഷ്ടിച്ച എല്ലാത്തിന്റെയും നാശത്തിൽ നിന്ന് ഞാൻ കാവൽ തേടുന്നു.'' എന്ന് പറയുകയും ചെയ്താൽ അവൻ അവിടെനിന്ന് മടങ്ങിപ്പോകും വരെ ആ വീട്ടിൽ വെച്ച് ഒന്നും തന്നെ അവനെ ബുദ്ധിമുട്ടിക്കുകയില്ല." (മു,തു,ജ)', 'خَوْلَةَ بِنْتِ حَكِيمٍ', 'ഖൗലത്ത് ബിൻത് ഹകീം(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 657, 657, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا اسْتَعْمَلَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى الطَّائِفِ جَعَلَ يَعْرِضُ لِي شَيْءٌ فِي صَلَاتِي، حَتَّى مَا أَدْرِي مَا أُصَلِّي. فَلَمَّا رَأَيْتُ ذَلِكَ رَحَلْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: "ابْنُ أَبِي الْعَاصِ". قُلْتُ: نَعَمْ، يَا رَسُولَ اللهِ. قَالَ: "مَا جَاءَ بِكَ". قُلْتُ: يَا رَسُولَ اللهِ، عَرَضَ لِي شَيْءٌ فِي صَلَوَاتِي، حَتَّى مَا أَدْرِي مَا أُصَلِّي. قَالَ: "ذَاكَ الشَّيْطَانُ، ادْنُهْ". فَدَنَوْتُ مِنْهُ، فَجَلَسْتُ عَلَى صُدُورِ قَدَمَيَّ. قَالَ: فَضَرَبَ صَدْرِي بِيَدِهِ، وَتَفَلَ فِي فَمِي، وَقَالَ: "اخْرُجْ، عَدُوَّ اللهِ". فَفَعَلَ ذَلِكَ ثَلَاثَ مَرَّاتٍ، ثُمَّ قَالَ: "الْحَقْ بِعَمَلِكَ". قَالَ: فَقَالَ عُثْمَانُ: فَلَعَمْرِي، مَا أَحْسِبُهُ خَالَطَنِي بَعْدُ. (جه)', 'ഉസ്മാനുബ്നു അബിൽ ആസ്(റ): റസൂൽ(സ) എന്നെ ത്വാഇഫിന്റെ ഗവർണ്ണറായി നിയമിച്ചപ്പോൾ, എന്റെ നിസ്കാരത്തിൽ എനിക്കെന്തോ ഒരു വസ്തു വെളിവാകാൻ തുടങ്ങുകയും, ഞാൻ നിസ്കരിക്കുന്നതെങ്ങനെയാണെന്ന് പോലും ഞാൻ അറിയാത്ത ഒരവസ്ഥയുണ്ടാവുകയും ചെയ്തു. എനിക്കിങ്ങനെയൊരവസ്ഥ വന്നപ്പോൾ ഞാൻ നബി(സ)യുടെ സന്നിധിയിലേക്ക് യാത്ര ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഇബ്നുഅബിൽ അബ്ബാസല്ലെയോ?" ഞാൻ പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ റസൂലേ. തിരുമേനി(സ) ചോദിച്ചു: "എന്താണിങ്ങ് വരാൻ കാരണം." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് എന്റെ നിസ്കാരങ്ങളിൽ എന്തോ ഒരു വസ്തു വെളിവാകുകയും, നിസ്കരിക്കുന്നതെങ്ങനെയാണെന്ന്പോലും ഞാൻ അറിയാതിരിക്കുകയും ചെയ്യുന്നു. നബി(സ) പറഞ്ഞു: "അത് പിശാചാണ്, നീയിങ്ങ് അടുത്ത് വരൂ." അപ്പോൾ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെല്ലുകയും എന്റെ രണ്ട് ഉള്ളൻകാലുകളിൽ ഞാൻ ഇരിക്കുകയും ചെയ്തു. ഇബ്നു അബിൽ ആസ്(റ) പറയുന്നു: അപ്പോൾ നബി(സ) അവിടത്തെ തൃക്കരങ്ങൾ കൊണ്ട് എന്റെ നെഞ്ചിൽ അടിക്കുകയും എന്റെ വായിൽ (നേർത്ത) ഉമിനീർ തുപ്പുകയും "അല്ലാഹുവിന്റെ ശത്രുവേ, നീ പുറത്ത് പോവുക" എന്ന് പറയുകയും ചെയ്തു. നബി(സ) ഇപ്രകാരം മൂന്ന് പ്രാവശ്യം ചെയ്തതിന് ശേഷം എന്നോട് പറഞ്ഞു: "ഇനി നീ നിന്റെ ജോലിയിലേർപ്പെടുക." നിവേദകൻ പറയുന്നു: പിന്നെ ഉസ്മാൻ(റ) പറഞ്ഞു: എന്റെ ആയുസ്സ് തന്നെയാണ് സത്യം, അതുപോലെ ഒരു അവസ്ഥ എനിക്ക് പിന്നെ ഉണ്ടായിട്ടേയില്ല. (ജ)', 'عُثْمَانَ بْنِ أَبِي الْعَاصِ', 'ഉസ്മാനുബ്നു അബിൽ ആസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 657, 658, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَبِي لَيْلَى الأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ أَعْرَابِيٌّ، فَقَالَ: إِنَّ لِي أَخًا وَجِعًا. قَالَ: "مَا وَجَعُ أَخِيكَ". قَالَ: بِهِ لَمَمٌ. قَالَ: "اذْهَبْ فَأْتِنِي بِهِ". قَالَ: فَذَهَبَ فَجَاءَ بِهِ، فَأَجْلَسَهُ بَيْنَ يَدَيْهِ. فَسَمِعْتُهُ عَوَّذَهُ بِفَاتِحَةِ الْكِتَابِ، وَأَرْبَعِ آيَاتٍ مِنْ أَوَّلِ الْبَقَرَةِ، وَآيَتَيْنِ مِنْ وَسَطِهَا: {وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ} [١٦٣] وَآيَةِ الْكُرْسِيِّ [٢٥٥] وَثَلَاثِ آيَاتٍ مِنْ خَاتِمَتِهَا، وَآيَةٍ مِنْ آلِ عِمْرَانَ - أَحْسَبُهُ قَالَ: {شَهِدَ اللهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ} [١٨] - وَآيَةٍ مِنَ الأَعْرَافِ [٥٤]: {إِنَّ رَبَّكُمُ اللهُ الَّذِي خَلَقَ} الآيَةِ، وَآيَةٍ مِنَ الْمُؤْمِنِينَ [١١٧]: {وَمَنْ يَدْعُ مَعَ اللهِ إِلَهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ} وَآيَةٍ مِنَ الْجِنِّ [٣]: {وَأَنَّهُ تَعَالَى جَدُّ رَبِّنَا مَا اتَّخَذَ صَاحِبَةً وَلَا وَلَدًا} وَعَشْرِ آيَاتٍ مِنْ أَوَّلِ الصَّافَّاتِ، وَثَلَاثِ آيَاتٍ مِنْ آخِرِ الْحَشْرِ، وَ{قُلْ هُوَ اللهُ أَحَدٌ} وَالْمُعَوِّذَتَيْنِ. فَقَامَ الأَعْرَابِيُّ قَدْ بَرَأَ، لَيْسَ بِهِ بَأْسٌ. [ز: في سنده ضعيف، وصححه الحاكم من نفس الطريق] (جه)', 'അബൂലൈലൽ അൻസാരി(റ): ഞാൻ നബി(സ)യുടെ അടുക്കൽ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരു അഅ്റാബി വന്ന് നബി(സ)യോട് പറഞ്ഞു: എനിക്ക് രോഗിയായ ഒരു സഹോദരനുണ്ട്. നബി(സ) ചോദിച്ചു: "എന്താണ് നിന്റെ സഹോദരന്റെ രോഗം?" അഅ്റാബി പറഞ്ഞു: അവന് ചെറിയ നിലയിൽ ഭ്രാന്തുണ്ട്. നബി(സ) പറഞ്ഞു: "നീ പോയി അവനെയും കൂട്ടിക്കൊണ്ടുവരിക." നിവേദകൻ പറയുന്നു: അപ്പോൾ ആ അഅ്റാബി പോയി സഹോദരനുമായി വന്നു. അപ്പോൾ നബി(സ) അയാളെ തന്റെ മുന്നിൽ ഇരുത്തി. എന്നിട്ട് സൂറതുൽ ഫാതിഹ, അൽബഖറയുടെ തുടക്കത്തിലെ നാല് സൂക്തങ്ങൾ, അതേ സൂറത്തിന്റെ മധ്യത്തിൽ നിന്നുള്ള രണ്ട് ആയത്തുകൾ: ''വഇലാഹുകും ഇലാഹുൻ വാഹിദുൻ'' (നിങ്ങളുടെ ആരാധ്യൻ ഏകനായ ആരാധ്യനാണ്) (163) ആയത്തുൽ കുർസിയ്യ് (255) എന്നിവയാണവ. അതേ സൂറത്തിന്റെ അവസാനത്തിലുള്ള മൂന്ന് ആയത്തുകൾ, ആലുഇംറാനിൽ നിന്നുള്ള ഒരു സൂക്തം - ''ശഹിദല്ലാഹു അന്നഹു ലാഇലാഹ ഇല്ലാഹുവ'' (താനല്ലാതെ ആരാധ്യനില്ല എന്നതിന് അല്ലാഹു സാക്ഷ്യം വഹിച്ചിരിക്കുന്നു) (18) എന്നതാണ് ഓതിയതെന്ന് ഞാൻ വിചാരിക്കുന്നു. - അഅ്റാഫിൽ നിന്നുള്ള ഒരു സൂക്തം (53): ''ഇന്ന റബ്ബകുമുല്ലാഹുല്ലദീ ഖലഖ'' (സൃഷ്ടിപ്പ് നടത്തിയ അല്ലാഹുവാണ് നിങ്ങളുടെ രക്ഷിതാവ്) എന്ന സൂക്തം, സൂറതുൽ മുഅ്മിനീനിൽ നിന്നുള്ള ഒരു സൂക്തം (117): ''വമൻ യദ്ഊ മഅല്ലാഹി ഇലാഹൻ ആഖറ ലാ ബിർഹാന ലഹു ബിഹി'' (യാതൊരു തെളിവുമില്ല എന്നിരിക്കെ വല്ലവനും അല്ലാഹുവോടൊപ്പം മറ്റു വല്ല ദൈവത്തേയും വിളിച്ചാൽ) എന്ന സൂക്തം, സൂറത്തുൽ ജിന്നിൽ നിന്ന് ഒരു ആയത്ത് (3): ''വഅന്നഹു തആലാ ജദ്ധു റബ്ബിനാ മത്തഖദ സ്വാഹിബതൻ വലാ വലദാ'' (നമ്മുടെ രക്ഷിതാവിന്റെ മഹത്വം ഉന്നതമാകുന്നു, അവൻ കൂട്ടുകാരിയെയോ സന്താനത്തെയോ സ്വീകരിച്ചിട്ടില്ല) എന്ന സൂക്തം, സൂറത്തുസ്സാഫാത്തിലെ ആദ്യത്തിൽ നിന്നുള്ള പത്ത് ആയത്തുകൾ, സൂറതുൽ ഹശ്റിലെ അവസാനത്തിലെ മൂന്ന് സൂക്തങ്ങൾ, സൂറത്തുൽ ഇഖ്ലാസ്, മുഅവ്വിദത്തെനി എന്നിവ കൊണ്ട് അയാളുടെ സംരക്ഷണത്തിനായി നബി(സ) പ്രാർത്ഥിക്കുന്നത് ഞാൻ കേട്ടു. അപ്പോൾ ആ അഅ്റാബി യാതൊരു കുഴപ്പവുമില്ലാത്ത രോഗമുക്തനായി എഴുന്നേറ്റു. (ജ)', 'أَبِي لَيْلَى الأَنْصَارِيِّ', 'അബൂലൈലൽ അൻസാരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف، وصححه الحاكم من نفس الطريق', null, 658, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ قَيْسِ بْنِ شَمَّاسٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ دَخَلَ عَلَى ثَابِتِ بْنِ قَيْسٍ قَالَ أَحْمَدُ وَهُوَ مَرِيضٌ، فَقَالَ: "اكْشِفِ الْبَأْسَ رَبَّ النَّاسِ، عَنْ ثَابِتِ بْنِ قَيْسِ بْنِ شَمَّاسٍ". ثُمَّ أَخَذَ تُرَابًا مِنْ بَطْحَانَ فَجَعَلَهُ فِي قَدَحٍ، ثُمَّ نَفَثَ عَلَيْهِ بِمَاءٍ، وَصَبَّهُ عَلَيْهِ. (د,جه)', 'ഖൈസുബ്നു ശമ്മാസ്(റ) നബി(സ)യിൽ നിന്നും നിവേദനം ചെയ്യുന്നു: നബി(സ) രോഗിയായ സാബിത്തുബ്നു ഖൈസ്(റ)വിന്റെയടുക്കൽ ചെല്ലുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ജനങ്ങളുടെ രക്ഷിതാവേ, സാബിതുബ്നു ഖൈസുബ്നു ശമ്മാസിന്റെ മുഴുവൻ പ്രശ്നങ്ങളെയും നീ തീർത്തുകൊടുക്കണേ." പിന്നെ അവിടുന്ന് ബത്ഹാൻ എന്ന താഴ്വരയിൽ നിന്ന് അൽപം മണ്ണെടുക്കുകയും അതിനെ ഒരു പാത്രത്തിലാക്കുകയും ചെയ്തു. പിന്നെ അതിലേക്ക് വെള്ളം കൊണ്ട് ഊതുകയും അത് അദ്ദേഹത്തിനുമേൽ ഒഴിക്കുകയും ചെയ്തു. (ദ,ജ)', 'قَيْسِ بْنِ شَمَّاسٍ', 'ഖൈസുബ്നു ശമ്മാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 659, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ، قَالَ لِثَابِتٍ الْبُنَانِيِّ: أَلَا أَرْقِيكَ بِرُقْيَةِ رَسُولِ اللهِ قَالَ: بَلَى، قَالَ: فَقَالَ: "اللَّهُمَّ رَبَّ النَّاسِ، مُذْهِبَ الْبَأْسِ، اشْفِ أَنْتَ الشَّافِي، لَا شَافِي إِلَّا أَنْتَ، اشْفِهِ شِفَاءً لَا يُغَادِرُ سَقَمًا". (خ,ت)', 'അനസ്(റ): അദ്ദേഹം സാബിതുൽ ബുതാനി(റ)വിനോട് ചോദിച്ചു: റസൂൽ(സ)യുടെ മന്ത്രം കൊണ്ട് ഞാൻ നിങ്ങളെ മന്ത്രിക്കട്ടെയോ? അദ്ദേഹം പറഞ്ഞു: ശരി. നിവേദകൻ പറയുന്നു: അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: "ജനങ്ങളുടെ രക്ഷിതാവായ ബുദ്ധിമുട്ടുകളെ അകറ്റുന്നവനായ അല്ലാഹുവേ, നീ രോഗം സുഖപ്പെടുത്തേണമേ. നീയാണ് രോഗം സുഖപ്പെടുത്തുന്നവൻ. നീയല്ലാതെ ശിഫ നൽകുന്ന മറ്റൊരുത്തനുമില്ല. ഒരു രോഗത്തെപ്പോലും വിട്ടുകളയാത്ത രോഗശമനം നീ അദ്ദേഹത്തിന് നൽകേണമേ." (ബു,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 659, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنِ اشْتَكَى مِنْكُمْ شَيْئًا، أَوِ اشْتَكَاهُ أَخٌ لَهُ، فَلْيَقُلْ: رَبَّنَا اللهُ الَّذِي فِي السَّمَاءِ، تَقَدَّسَ اسْمُكَ، أَمْرُكَ فِي السَّمَاءِ وَالأَرْضِ، كَمَا رَحْمَتُكَ فِي السَّمَاءِ فَاجْعَلْ رَحْمَتَكَ فِي الأَرْضِ، اغْفِرْ لَنَا حُوبَنَا وَخَطَايَانَا، أَنْتَ رَبُّ الطَّيِّبِينَ، أَنْزِلْ رَحْمَةً مِنْ رَحْمَتِكَ وَشِفَاءً مِنْ شِفَائِكَ عَلَى هَذَا الْوَجَعِ، فَيَبْرَأَ". (د)', 'അബുദ്ദർദാഅ്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങളിൽ നിന്നാർക്കെങ്കിലും രോഗം ബാധിച്ചാൽ അല്ലെങ്കിൽ അവനോട് തന്റെ സഹോദരൻ രോഗമുണ്ടെന്ന് പരാതി പറഞ്ഞാൽ അവൻ ഇപ്രകാരം പറഞ്ഞുകൊള്ളട്ടെ: ആകാശത്തിലുള്ള ഞങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവേ, നിന്റെ നാമം എത്ര പരിശുദ്ധമായിരിക്കുന്നു. ആകാശത്തിലുള്ളതും ഭൂമിയിലുള്ളതും നിന്റെ കാര്യമാണ്. ആകാശലോകത്ത് നിന്റെ കാരുണ്യം ഉള്ളത് പോലെ ഭൂമിയിലേക്കും അത് വർഷിപ്പിക്കേണമേ, ഞങ്ങളുടെ ചെറുതും വലുതുമായ എല്ലാ ദോശങ്ങളെയും നീ പൊറുത്തുതരേണമേ, നീ നല്ലവരുടെ രക്ഷിതാവാണ്, നിന്റെ അനുഗ്രഹത്തിൽ നിന്നുള്ള ഒരു അനുഗ്രഹത്തെയും നിന്റെ ശിഫയിൽ നിന്നുള്ള ഒരു ശിഫയെയും ഈ രോഗത്തിന്റെമേൽ അത് സുഖപ്പെടും വിധം നീ ഇറക്കേണമേ." (ദ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 659, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهُمْ مِنَ الْفَزَعِ كَلِمَاتٍ: "أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّةِ، مِنْ غَضَبِهِ وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ". وَكَانَ عَبْدُ اللهِ بْنُ عُمَرَ يُعَلِّمُهُنَّ مَنْ عَقَلَ مِنْ بَنِيهِ، وَمَنْ لَمْ يَعْقِلْ كَتَبَهُ فَأَعْلَقَهُ عَلَيْهِ. (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പേടിയിൽനിന്ന് രക്ഷനേടാൻ അവർക്ക് ചില വാക്യങ്ങൾ പഠിപ്പിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവിന്റെ പൂർണ്ണമായ വാക്യങ്ങൾ കൊണ്ട് ഞാൻ കാവൽ തേടുന്നു, അവന്റെ ദേഷ്യത്തിൽനിന്നും അവന്റെ അടിമകളുടെ തിന്മയിൽനിന്നും പിശാചുക്കളുടെ ദുർബോധനത്തിൽനിന്നും അവർ എന്റെ അടുത്ത് സന്നിഹിതരാവലിൽനിന്നും." അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) ഈ വാക്യങ്ങളെ തന്റെ സന്താനങ്ങളിൽ പകൃതയെത്തിയവർക്ക് പഠിപ്പിച്ചുകൊടുക്കുകയും പകൃതയെത്താത്തവരുടെ ശരീരത്തിൽ അത് എഴുതി ബന്ധിപ്പിക്കുകയും ചെയ്യുമായിരുന്നു. (തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 659, 660, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ يَزِيدَ بْنِ أَبِي عُبَيْدٍ قَالَ: رَأَيْتُ أَثَرَ ضَرْبَةٍ فِي سَاقِ سَلَمَةَ رَضِيَ اللهُ عَنْهُ، فَقُلْتُ: مَا هَذِهِ؟ قَالَ: أَصَابَتْنِي يَوْمَ خَيْبَرَ، فَقَالَ النَّاسُ: أُصِيبَ سَلَمَةُ، فَأُتِيَ بِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنَفَثَ فِيَّ ثَلَاثَ نَفَثَاتٍ، فَمَا اشْتَكَيْتُهَا حَتَّى السَّاعَةِ. (خ)', 'യസീദുബ്നു അബീഉബൈദ്(റ): സലമ(റ)വിന്റെ തണ്ടൻ കാലിൽ ഒരു വെട്ടിന്റെ അടയാളം ഞാൻ കണ്ടു. അപ്പോൾ ഞാൻ ചോദിച്ചു: എന്താണിത്? അദ്ദേഹം പറഞ്ഞു: അതെനിക്ക് ഖൈബർ യുദ്ധത്തിൽ പറ്റിയതാണ്. അപ്പോൾ ജനങ്ങൾ വിളിച്ചുപറഞ്ഞു: സലമക്ക് വെട്ടേറ്റിരിക്കുന്നു. അങ്ങനെ ഞാൻ തിരുസന്നിധിയിൽ കൊണ്ടുവരപ്പെട്ടു. അപ്പോൾ അവിടുന്ന് എന്നിൽ മൂന്ന് പ്രാവശ്യം നേർത്ത തുപ്പുനീരോടു കൂടി ഊതി. അതിനുശേഷം ഇന്നുവരെ എനിക്കതിൽ ഒരു വേദനയും അനുഭവപ്പെട്ടിട്ടില്ല. (ബു)', 'يَزِيدَ بْنِ أَبِي عُبَيْدٍ قَالَ', 'യസീദുബ്നു അബീഉബൈദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 660, 660, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِلَدِيغٍ لَدَغَتْهُ عَقْرَبٌ، قَالَ: فَقَالَ: "لَوْ قَالَ: أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّةِ مِنْ شَرِّ مَا خَلَقَ لَمْ يُلْدَغْ. أَوْ: لَمْ يَضُرَّهُ". (د)', 'അബൂഹുറൈറ(റ): തേൾ കടിച്ച ഒരാളെ നബി(സ)യുടെ സന്നിധിയിൽ കൊണ്ടുവന്നു. നിവേദകൻ പറയുന്നു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ പൂർണ്ണമായ വാക്യങ്ങൾ കൊണ്ട് അവൻ സൃഷ്ടിച്ച എല്ലാറ്റിന്റെയും നാശത്തിൽ നിന്ന് ഞാൻ കാവൽ തേടുന്നു എന്ന് അവൻ പറഞ്ഞിരുന്നുവെങ്കിൽ അവന് കടി ഏൽക്കുമായിരുന്നില്ല. അല്ലെങ്കിൽ അതവനെ ബുദ്ധിമുട്ടിക്കുമായിരുന്നില്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 660, 660, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اشْتَكَى يَقْرَأُ فِي نَفْسِهِ بِالْمُعَوِّذَاتِ وَيَنْفُثُ، فَلَمَّا اشْتَدَّ وَجَعُهُ كُنْتُ أَقْرَأُ عَلَيْهِ وَأَمْسَحُ عَلَيْهِ بِيَدِهِ رَجَاءَ بَرَكَتِهَا. (ق,د,جه)', 'ആഇശ(റ): നബി(സ)ക്ക് വല്ല ബുദ്ധിമുട്ടും വന്നാൽ അവിടന്ന് സ്വന്തമായി മുഅവ്വിദതൈനി (സൂറതുൽ ഫലഖ്, സൂറതുന്നാസ്) ഓതുകയും ഊതുകയും ചെയ്യുമായിരുന്നു. നബി(സ)ക്ക് വേദന ശക്തമായപ്പോൾ ഞാൻ നബി(സ)യുടെ മേൽ ഓതുകയും, അവിടത്തെ കൈകളുടെ ബറകതിനെ പ്രതീക്ഷിച്ച്, അവിടത്തെ മേൽ അവിടത്തെ കൈകൾ കൊണ്ട് തന്നെ ഞാൻ തടവുകയും ചെയ്യുമായിരുന്നു. (ബു,മു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 660, 660, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَرِيَّةٍ، فَنَزَلْنَا بِقَوْمٍ، فَسَأَلْنَاهُمُ الْقِرَى فَلَمْ يَقْرُونَا، فَلُدِغَ سَيِّدُهُمْ، فَأَتَوْنَا فَقَالُوا: هَلْ فِيكُمْ مَنْ يَرْقِي مِنَ الْعَقْرَبِ؟ قُلْتُ: نَعَمْ، أَنَا، وَلَكِنْ لَا أَرْقِيهِ حَتَّى تُعْطُونَا غَنَمًا. قَالَ: فَأَنَا أُعْطِيكُمْ ثَلَاثِينَ شَاةً. فَقَبِلْنَا، فَقَرَأْتُ عَلَيْهِ الْحَمْدُ لِلَّهِ سَبْعَ مَرَّاتٍ فَبَرَأَ، وَقَبَضْنَا الْغَنَمَ، وَقَالَ: فَعَرَضَ فِي أَنْفُسِنَا مِنْهَا شَيْءٌ، فَقُلْنَا: لَا تَعْجَلُوا حَتَّى تَأْتُوا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَلَمَّا قَدِمْنَا عَلَيْهِ ذَكَرْتُ لَهُ الَّذِي صَنَعْتُ، قَالَ: "وَمَا عَلِمْتَ أَنَّهَا رُقْيَةٌ؟ اقْبِضُوا الْغَنَمَ، وَاضْرِبُوا لِي مَعَكُمْ بِسَهْمٍ". (ق,د,ت,جه)', 'അബൂസഇൗദിൽ ഖുദ്രി(റ): തിരുദൂതർ(സ) ഞങ്ങളെ ഒരു സംഘത്തിൽ അയച്ചു. ഞങ്ങൾ ഒരു കൂട്ടം ജനങ്ങളുടെ സമീപമെത്തി. അവരോട് ഞങ്ങളെ സൽക്കരിക്കാനാവശ്യപ്പെട്ടു. എന്നാൽ അവർ വിസമ്മതിച്ചു. അൽപനേരം കഴിഞ്ഞപ്പോൾ അവരുടെ നേതാവിനെ തേൾ കടിച്ചു. അവർ ഞങ്ങളുടെ അടുത്ത് വന്നുകൊണ്ട് ചോദിച്ചു: തേൾ കുത്തിയതിന് മന്ത്രിക്കുന്ന വല്ലവരും നിങ്ങളുടെ കൂട്ടത്തിലുണ്ടോ? ഞാൻ പറഞ്ഞു: അതെ, ഞാനുണ്ട്. പക്ഷേ, ഞങ്ങൾക്ക് ആടുകളെ തന്നാൽ മാത്രമേ ഞാൻ മന്ത്രിക്കുകയുള്ളൂ. അപ്പോൾ അയാൾ പറഞ്ഞു: ഞാൻ നിങ്ങൾക്ക് മുപ്പത് ആടുകളെ തരാം. ഞങ്ങൾ സമ്മതിച്ചു. അങ്ങനെ ഞാൻ ''അൽഹംദു'' സൂറത്ത് (ഫാതിഹ) ഏഴ് പ്രാവശ്യം ഓതി. അയാൾക്ക് സുഖമായി. ഞങ്ങൾ ആടുകളെ സ്വീകരിച്ചു. അബൂസഇൗദിൽ ഖുദ്രി(റ) പറയുന്നു: അന്നേരം ഞങ്ങൾക്ക് മനസ്സിൽ അസ്വസ്ഥതയുണ്ടായി. ഞങ്ങൾ പറഞ്ഞു: നിങ്ങൾ ധൃതികൂട്ടരുത്. നമുക്ക് നബി(സ)യുടെ അടുത്ത് ചെല്ലാം. നബി(സ)യുടെ സമീപത്തെത്തിയപ്പോൾ ഞാൻ നടന്നതെല്ലാം പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ആ സൂറത്ത് മന്ത്രമാണെന്ന് നീ അറിഞ്ഞതെങ്ങനെ? നിങ്ങൾ ആടുകളെ സ്വീകരിക്കുക. നിങ്ങളോടൊപ്പം ഒരു വിഹിതം എനിക്കും നൽകൂ." (ബു,മു,ദ,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രി(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 660, 661, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَاسًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرُّوا بِحَيٍّ مِنَ الْعَرَبِ فَلَمْ يَقْرُوهُمْ وَلَمْ يُضَيِّفُوهُمْ، فَاشْتَكَى سَيِّدُهُمْ، فَأَتَوْنَا فَقَالُوا: هَلْ عِنْدَكُمْ دَوَاءٌ؟ قُلْنَا: نَعَمْ، وَلَكِنْ لَمْ تَقْرُونَا وَلَمْ تُضَيِّفُونَا، فَلَا نَفْعَلُ حَتَّى تَجْعَلُوا لَنَا جُعْلًا. فَجَعَلُوا عَلَى ذَلِكَ قَطِيعًا مِنَ الْغَنَمِ، قَالَ: فَجَعَلَ رَجُلٌ مِنَّا يَقْرَأُ عَلَيْهِ بِفَاتِحَةِ الْكِتَابِ، فَبَرَأَ، فَلَمَّا أَتَيْنَا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَكَرْنَا ذَلِكَ لَهُ، قَالَ: "وَمَا يُدْرِيكَ أَنَّهَا رُقْيَةٌ". وَلَمْ يَذْكُرْ نَهْيًا مِنْهُ، وَقَالَ: "كُلُوا وَاضْرِبُوا لِي مَعَكُمْ بِسَهْمٍ". (ت)', 'അബൂസഇൗദ്(റ): നബി(സ)യുടെ സ്വഹാബികളിൽ ചിലർ ഒരു അറബ് സമൂഹത്തിന്റെ സമീപത്തുകൂടെ സഞ്ചരിച്ചു. പക്ഷേ, അവർ സ്വഹാബികളെ സൽക്കരിക്കുകയോ സ്വീകരിക്കുകയോ ചെയ്തില്ല. അങ്ങനെ അവരുടെ നേതാവിന് രോഗം ബാധിച്ചു. അവർ ഞങ്ങളുടെ സമീപത്തുവന്ന് ചോദിച്ചു: നിങ്ങളുടെയടുത്ത് മരുന്നുണ്ടോ? ഞങ്ങൾ പറഞ്ഞു: ഉണ്ട്. പക്ഷേ, നിങ്ങൾ ഞങ്ങളെ സൽക്കരിക്കുകയോ സ്വീകരിക്കുകയോ ചെയ്തിട്ടില്ല. അതിനാൽ ഞങ്ങൾക്ക് പ്രതിഫലം തരുന്നില്ലെങ്കിൽ ഞങ്ങൾ മരുന്ന് തരില്ല. അപ്പോൾ അവർ കുറച്ച് ആടുകളെ തന്നു. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞങ്ങളിൽ നിന്നൊരാൾ ഫാതിഹ ഓതാൻ തുടങ്ങി. അയാൾക്ക് സുഖമായി. പിന്നീട് ഞങ്ങൾ നബി(സ)യുടെ സമീപത്തെത്തിയപ്പോൾ നടന്നതെല്ലാം പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അത് മന്ത്രമാണെന്ന് നിനക്കറിയാമോ?" എതിർത്തൊന്നും നബി(സ) പറഞ്ഞില്ല. ശേഷം പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷിക്കുക, എനിക്കും ഒരു വിഹിതം നൽകുക." (തു)', 'أَبِي سَعِيدٍ', 'അബൂസഇൗദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 661, 661, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ خَارِجَةَ بْنِ الصَّلْتِ التَّمِيمِيِّ، عَنْ عَمِّهِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَسْلَمَ، ثُمَّ أَقْبَلَ رَاجِعًا مِنْ عِنْدِهِ، فَمَرَّ عَلَى قَوْمٍ عِنْدَهُمْ رَجُلٌ مَجْنُونٌ مُوثَقٌ بِالْحَدِيدِ، فَقَالَ أَهْلُهُ: إِنَّا حُدِّثْنَا أَنَّ صَاحِبَكُمْ هَذَا قَدْ جَاءَ بِخَيْرٍ، فَهَلْ عِنْدَكَ شَيْءٌ تُدَاوِيهِ؟ فَرَقَيْتُهُ بِفَاتِحَةِ الْكِتَابِ، فَبَرَأَ، فَأَعْطَوْنِي مِائَةَ شَاةٍ، فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ، فَقَالَ: "هَلْ إِلَّا هَذَا". وفي رواية: "هَلْ قُلْتَ غَيْرَ هَذَا؟" قُلْتُ: لَا، قَالَ: "خُذْهَا، فَلَعَمْرِي لَمَنْ أَكَلَ بِرُقْيَةِ بَاطِلٍ لَقَدْ أَكَلْتَ بِرُقْيَةِ حَقٍّ". وفي رواية: فَرَقَاهُ بِفَاتِحَةِ الْكِتَابِ ثَلَاثَةَ أَيَّامٍ غُدْوَةً وَعَشِيَّةً، كُلَّمَا خَتَمَهَا جَمَعَ بُزَاقَهُ ثُمَّ تَفَلَ، فَكَأَنَّمَا أُنْشِطَ مِنْ عِقَالٍ، فَأَعْطَوْهُ شَيْئًا، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ ذَكَرَ مَعْنَى الْحَدِيثِ. (د)', 'ഖാരിജതുബ്നു സ്വൽതുത്തമീമി(റ) തന്റെ പിതൃവ്യനിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: അദ്ദേഹം നബി(സ)യുടെ സന്നിധിയിൽ വരികയും മുസ്ലിമാവുകയും ശേഷം നബി(സ)യുടെ അടുത്തുനിന്ന് യാത്ര തിരിക്കുകയും ചെയ്തു. അങ്ങനെ അദ്ദേഹം ഇരുമ്പുമായി ബന്ധിപ്പിക്കപ്പെട്ട ഭ്രാന്തനായ ഒരു മനുഷ്യൻ ഉൾപെടുന്ന ഒരു കൂട്ടരുടെ അടുത്തുകൂടെ നടന്നുപോയി. അപ്പോൾ അവർ ചോദിച്ചു: നിങ്ങളുടെ ആൾ - നബി(സ) - ഒരു നല്ല കാര്യവുമായി വന്നിരിക്കുന്നുവെന്ന വാർത്ത ഞങ്ങൾ അറിയിക്കപ്പെട്ടിരിക്കുന്നു. അതുകൊണ്ട് ഈ രോഗിയെ ചികിത്സിക്കാൻ പറ്റിയ എന്തെങ്കിലും താങ്കളുടെ പക്കലുണ്ടോ? അപ്പോൾ ഞാനാ മനുഷ്യനെ സൂറത്തുൽ ഫാതിഹ കൊണ്ട് മന്ത്രിച്ചു. അങ്ങനെ അയാൾ സുഖം പ്രാപിക്കുകയും ചെയ്തു. അങ്ങനെ അവരെനിക്ക് നൂറ് ആടുകളെ തന്നു. അങ്ങനെ ഞാൻ നബി(സ)യുടെ സന്നിധിയിൽ ചെന്ന് അവിടുത്തോട് വിവരങ്ങളെല്ലാം പറഞ്ഞു. അപ്പോൾ അവിടുന്നെന്നോട് ചോദിച്ചു: "ഇതല്ലാതെ മറ്റെന്തെങ്കിലും ഉണ്ടോ?" മറ്റൊരു റിപ്പോർട്ടിൽ: "ഇതല്ലാതെ മറ്റെന്തെങ്കിലും നീ പറഞ്ഞോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. അവിടുന്ന് പറഞ്ഞു: "അതിനെ നീ എടുത്തുകൊള്ളുക. എന്റെ ആയുസ്സ് തന്നെയാണ് സത്യം, തീർച്ചയായും ആരെങ്കിലും പൊള്ളയായ മന്ത്രം കൊണ്ട് ഭക്ഷിക്കുന്നുവെങ്കിൽ, തീർച്ചയായും നീ ഭക്ഷിച്ചിരിക്കുന്നത് സത്യമായ മന്ത്രം കൊണ്ടാണ്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=11 and h.hadith_no=139), 1, 'وَفِي رِوَايَةٍ: "هَلْ قُلْتَ غَيْرَ هَذَا؟" قُلْتُ: لَا، قَالَ: "خُذْهَا، فَلَعَمْرِي لَمَنْ أَكَلَ بِرُقْيَةِ بَاطِلٍ لَقَدْ أَكَلْتَ بِرُقْيَةِ حَقٍّ".', 'മറ്റൊരു നിവേദനിൽ: "ഇതല്ലാതെ മറ്റെന്തെങ്കിലും നീ പറഞ്ഞോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. അവിടുന്ന് പറഞ്ഞു: "അതിനെ നീ എടുത്തുകൊള്ളുക. എന്റെ ആയുസ്സ് തന്നെയാണ് സത്യം, തീർച്ചയായും ആരെങ്കിലും പൊള്ളയായ മന്ത്രം കൊണ്ട് ഭക്ഷിക്കുന്നുവെങ്കിൽ, തീർച്ചയായും നീ ഭക്ഷിച്ചിരിക്കുന്നത് സത്യമായ മന്ത്രം കൊണ്ടാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=11 and h.hadith_no=139), 2, 'وَفِي رِوَايَةٍ: فَرَقَاهُ بِفَاتِحَةِ الْكِتَابِ ثَلَاثَةَ أَيَّامٍ غُدْوَةً وَعَشِيَّةً، كُلَّمَا خَتَمَهَا جَمَعَ بُزَاقَهُ ثُمَّ تَفَلَ، فَكَأَنَّمَا أُنْشِطَ مِنْ عِقَالٍ، فَأَعْطَوْهُ شَيْئًا، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ ذَكَرَ مَعْنَى الْحَدِيثِ. (د)', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം മൂന്ന് ദിവസം രാവിലെയും വൈകുന്നേരവും ആ മനുഷ്യനെ സൂറതുൽ ഫാതിഹ കൊണ്ട് മന്ത്രിച്ചു. സൂറത് അവസാനിക്കുമ്പോഴെല്ലാം അദ്ദേഹം തന്റെ ഉമിനീർ ഒരുമിച്ചുകൂട്ടി തുപ്പുമായിരുന്നു. അങ്ങനെ ആ മനുഷ്യന്റെ ഭ്രാന്ത് ഏറെക്കുറെ സുഖമായി. അപ്പോൾ അവർ അദ്ദേഹത്തിന് എന്തോ സമ്മാനിക്കുകയും അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വരികയും ചെയ്തു. ശേഷം ഈ ഹദീസിന്റെ ആശയം പറഞ്ഞു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ حَابِسٍ التَّمِيمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا شَيْءَ فِي الْهَامِ، وَالْعَيْنُ حَقٌّ". (ق,د,ت,جه)', 'ഹാബിസുത്തമീമി(റ): നബി(സ) പറുയന്നതായി അദ്ദേഹം കേട്ടു: "പക്ഷിലക്ഷണത്തിൽ ഒന്നുമില്ല. കണ്ണേറ് വാസ്തവമാണ്." (ബു,മു,ദ,തു,ജ)', 'حَابِسٍ التَّمِيمِيِّ', 'ഹാബിസുത്തമീമി(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 662, 662, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ كَانَ شَيْءٌ سَابَقَ الْقَدَرَ لَسَبَقَتْهُ الْعَيْنُ، وَإِذَا اسْتُغْسِلْتُمْ فَاغْسِلُوا". قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (م,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "വിധിയെ മുൻകടക്കുന്ന വല്ലതുമുണ്ടാകുമായിരുന്നുവെങ്കിൽ കണ്ണേറ് മറികടക്കുമായിരുന്നു. നിങ്ങൾ കുളിക്കാൻ നിർദ്ദേശിക്കപ്പെട്ടാൽ കുളിക്കുക." (മു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 662, 662, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "لِكُلِّ دَاءٍ دَوَاءٌ، فَإِذَا أُصِيبَ دَوَاءُ الدَّاءِ بَرَأَ بِإِذْنِ اللهِ عَزَّ وَجَلَّ". (م,د)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "എല്ലാ രോഗങ്ങൾക്കും മരുന്നുണ്ട്. രോഗത്തിന്റെ മരുന്ന് നൽകപ്പെട്ടാൽ അല്ലാഹുവിന്റെ അനുവാദത്തോടെ അത് സുഖപ്പെടുന്നു." (മു,ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 662, 662, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ يُؤْمَرُ الْعَائِنُ فَيَتَوَضَّأُ، ثُمَّ يَغْتَسِلُ مِنْهُ الْمَعِينُ. (د)', 'ആഇശ(റ): കണ്ണേറ് ഏൽപിച്ചവൻ വുളു ചെയ്യാൻ കൽപിക്കപ്പെടുമായിരുന്നു. ശേഷം അതിൽനിന്ന് കണ്ണേറ് ഏറ്റവൻ കുളിക്കുമായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 662, 662, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ عَامِرُ بْنُ رَبِيعَةَ بِسَهْلِ بْنِ حُنَيْفٍ وَهُوَ يَغْتَسِلُ، فَقَالَ: لَمْ أَرَ كَالْيَوْمِ، وَلَا جِلْدَ مُخَبَّأَةٍ. فَمَا لَبِثَ أَنْ لُبِطَ بِهِ، فَأُتِيَ بِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقِيلَ لَهُ: أَدْرِكْ سَهْلًا صَرِيعًا. قَالَ: "مَنْ تَتَّهِمُونَ بِهِ". قَالُوا: عَامِرَ بْنَ رَبِيعَةَ. قَالَ: "عَلَامَ يَقْتُلُ أَحَدُكُمْ أَخَاهُ؟ إِذَا رَأَى أَحَدُكُمْ مِنْ أَخِيهِ مَا يُعْجِبُهُ فَلْيَدْعُ لَهُ بِالْبَرَكَةِ". ثُمَّ دَعَا بِمَاءٍ، فَأَمَرَ عَامِرًا أَنْ يَتَوَضَّأَ، فَيَغْسِلَ وَجْهَهُ وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ، وَرُكْبَتَيْهِ وَدَاخِلَةَ إِزَارِهِ، وَأَمَرَهُ أَنْ يُصَبَّ عَلَيْهِ. وفي رواية: وَأَمَرَهُ أَنْ يَكْفَأَ الإِنَاءَ مِنْ خَلْفِهِ. (جه)', 'അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ): ആമിറുബ്നു റബീഅ(റ) സഹ്ലുബ്നു ഹുനൈഫ്(റ)വിന്റെ അടുത്തുകൂടെ നടന്നുപോയപ്പോൾ അദ്ദേഹം കുളിക്കുകയായിരുന്നു. അപ്പോൾ ആമിർ(റ) പറഞ്ഞു: ഇന്ന് കണ്ടതുപോലെ (ഭംഗിയുള്ള) വിധവയുടെ തൊലി ഞാൻ കണ്ടിട്ടില്ല. അപ്പോൾ തന്നെ സഹ്ൽ(റ) അവിടെ വീണു. നബി(സ)യുടെ അടുക്കലേക്ക് അദ്ദേഹം കൊണ്ടുവരപ്പെട്ടു. നബി(സ)യോട് പറയപ്പെട്ടു: സഹ്ൽ(റ) ബോധക്ഷയനായിരിക്കുന്നു. നബി(സ) ചോദിച്ചു: "ഇക്കാര്യത്തിൽ നിങ്ങൾ ആരെയാണ് സംശയിക്കുന്നത്?" അവർ പറഞ്ഞു: ആമിറുബ്നു റബീഅ്(റ)വിനെ. നബി(സ) ചോദിച്ചു: "എന്തിന്റെ പേരിലാണ് നിങ്ങളിലൊരുത്തൻ തന്റെ സഹോദരനെ വധിക്കുന്നത്? നിങ്ങളിലാരെങ്കിലും തന്റെ സഹോദരനിൽ അത്ഭുതമുളവാക്കുന്ന വല്ലതും കണ്ടാൽ അവന് ബറകത്തിന് വേണ്ടി പ്രാർത്ഥിക്കുക." പിന്നെ നബി(സ) വെള്ളം കൊണ്ടുവരാൻ പറഞ്ഞു. ആമിർ(റ)വിനോട് അതിൽ നിന്ന് വുളു ചെയ്യാൻ കൽപിച്ചു. മുഖവും കൈകൾ മുട്ട് വരെയും കാൽമുട്ടുകളും വസ്ത്രത്തിന്റെ ഉൾഭാഗവും കഴുകാനും കൽപിച്ചു. എന്നിട്ട് സഹ്ൽ(റ)വിന്റെ മേൽ ആ വെള്ളം ഒഴിക്കാൻ പറഞ്ഞു. മറ്റൊരു റിപ്പോർട്ടിൽ: അദ്ദേഹത്തിന്റെ പിന്നിൽ നിന്ന് പാത്രം ചൊരിക്കാൻ കൽപിച്ചു. (ജ)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ', 'അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 662, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=11 and h.hadith_no=144), 1, 'وَفِي رِوَايَةٍ: وَأَمَرَهُ أَنْ يَكْفَأَ الإِنَاءَ مِنْ خَلْفِهِ. (جه)', 'മറ്റൊരു നിവേദനിൽ: അദ്ദേഹത്തിന്റെ പിന്നിൽ നിന്ന് പാത്രം ചൊരിക്കാൻ കൽപിച്ചു. (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "اسْتَعِيذُوا بِاللهِ، فَإِنَّ الْعَيْنَ حَقٌّ". [ز: قي سنده ضعيف] (جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിനോട് കാവൽ തേടുക. നിശ്ചയം കണ്ണേറ് വാസ്തവമാണ്." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: قي سنده ضعيف', null, 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَوْ أَمَرَ أَنْ يُسْتَرْقَى مِنَ الْعَيْنِ. (خ)', 'ആഇശ(റ): കണ്ണേറിനു ണ്ടേി മന്ത്രിക്കാൻ നബി(സ) എന്നോട് കൽപിച്ചു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى فِي بَيْتِهَا جَارِيَةً فِي وَجْهِهَا سَفْعَةٌ فَقَالَ: "اسْتَرْقُوا لَهَا، فَإِنَّ بِهَا النَّظْرَةَ". (خ)', 'ഉമ്മുസലമ(റ): മഹതിയുടെ വീട്ടിൽ മുഖത്ത് പാടുള്ള ഒരു പെൺകുട്ടിയെ നബി(സ) കണ്ടപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അവളെ നിങ്ങൾ മന്ത്രിക്കുക. അവൾക്ക് കണ്ണേറ് തട്ടിയിരിക്കുന്നു." (ബു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: يَا رَسُولَ اللهِ، إِنَّ بَنِي جَعْفَرٍ تُصِيبُهُمُ الْعَيْنُ، فَأَسْتَرْقِي لَهُمْ؟ قَالَ: "نَعَمْ، فَلَوْ كَانَ شَيْءٌ سَابَقَ الْقَدَرَ سَبَقَتْهُ الْعَيْنُ". (ت,جه)', 'അസ്മാഅ് ബിൻത് ഉമൈസ്(റ): മഹതി ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ബനൂജഅ്ഫറിന് കണ്ണേറ് ബാധിച്ചിരിക്കുന്നു. അതുകൊണ്ട് ഞാൻ അവർക്കു വേണ്ടി മന്ത്രിക്കട്ടെയോ? നബി(സ) പറഞ്ഞു: "അതെ, വിധിയെ ഏതെങ്കിലും വസ്തു മറികടക്കുകയാണെങ്കിൽ കണ്ണേറ് മറികടക്കുമായിരുന്നു." (തു,ജ)', 'أَسْمَاءَ بِنْتِ عُمَيْسٍ', 'അസ്മാഅ് ബിൻത് ഉമൈസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ مِنْ عَيْنِ الْجَانِّ، ثُمَّ أَعْيُنِ الإِنْسِ. فَلَمَّا نَزَلَتِ الْمُعَوِّذَتَانِ أَخَذَهُمَا، وَتَرَكَ مَا سِوَى ذَلِكَ. (ت,ن,جه)', 'അബൂസഇൗദ്(റ): നബി(സ) ജിന്നുകളുടെയും പിന്നെ മനുഷ്യരുടെയും കണ്ണേറിനു വേണ്ടി മന്ത്രിച്ചിരുന്നു. പിന്നീട് മുഅവ്വിദതാനി (സൂറതുൽ ഫലഖ്, സൂറതുന്നാസ്) ഇറക്കപ്പെട്ടപ്പോൾ അത് മാത്രം സ്വീകരിച്ച് ബാക്കി മന്ത്രങ്ങൾ നബി(സ) ഒഴിവാക്കി. (തു,ന,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഇൗദ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 664, 664, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَهَا أَنْ تَسْتَرْقِيَ مِنَ الْعَيْنِ. (خ,جه)', 'ആഇശ(റ): കണ്ണേറിൽ നിന്ന് രക്ഷക്കായി മന്ത്രം ജപിക്കാൻ മഹതിയോട് നബി(സ) കൽപിച്ചു. (ബു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 664, 664, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ زَيْنَبَ - امْرَأَةِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا - قَالَتْ: كَانَتْ عَجُوزٌ تَدْخُلُ عَلَيْنَا تَرْقِي مِنَ الْحُمْرَةِ، وَكَانَ لَنَا سَرِيرٌ طَوِيلُ الْقَوَائِمِ، وَكَانَ عَبْدُ اللهِ إِذَا دَخَلَ تَنَحْنَحَ وَصَوَّتَ، فَدَخَلَ يَوْمًا، فَلَمَّا سَمِعَتْ صَوْتَهُ احْتَجَبَتْ مِنْهُ، فَجَاءَ فَجَلَسَ إِلَى جَانِبِي، فَمَسَّنِي، فَوَجَدَ مَسَّ خَيْطٍ، فَقَالَ: مَا هَذَا؟ فَقُلْتُ: رُقًى لِي فِيهِ مِنَ الْحُمْرَةِ. فَجَذَبَهُ وَقَطَعَهُ، فَرَمَى بِهِ وَقَالَ: لَقَدْ أَصْبَحَ آلُ عَبْدِ اللهِ أَغْنِيَاءَ عَنِ الشِّرْكِ، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الرُّقَى وَالتَّمَائِمَ وَالتِّوَلَةَ شِرْكٌ". قُلْتُ: فَإِنِّي خَرَجْتُ يَوْمًا فَأَبْصَرَنِي فُلَانٌ، فَدَمَعَتْ عَيْنِي الَّتِي تَلِيهِ، فَإِذَا رَقَيْتُهَا سَكَنَتْ دَمْعَتُهَا، وَإِذَا تَرَكْتُهَا دَمَعَتْ. قَالَ: ذَاكَ الشَّيْطَانُ، إِذَا أَطَعْتِهِ تَرَكَكِ، وَإِذَا عَصَيْتِهِ طَعَنَ بِإِصْبَعِهِ فِي عَيْنِكِ. وَلَكِنْ لَوْ فَعَلْتِ كَمَا فَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ خَيْرًا لَكِ، وَأَجْدَرَ أَنْ تَشْفَيْنَ: تَنْضَحِينَ فِي عَيْنِكِ الْمَاءَ وَتَقُولِينَ: "أَذْهِبِ الْبَاسْ رَبَّ النَّاسْ، اشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا". (د,جه)', 'സൈനബ്(റ) - ഇബ്നുമസ്ഊദ്(റ)വിന്റെ ഭാര്യ: ഞങ്ങളുടെ അടുത്ത് വരാറുണ്ടായിരുന്ന ഒരു വൃദ്ധയുണ്ടായിരുന്നു. അവർ ചൊള്ളയുണ്ടായാൽ മന്ത്രിക്കുമായിരുന്നു. ഞങ്ങളുടെ വീട്ടിൽ നീണ്ട കാലുകളുള്ള ഒരു കട്ടിലയുണ്ടായിരുന്നു. അബ്ദുല്ല(റ) വീട്ടിൽ പ്രവേശിക്കുമ്പോൾ തൊണ്ടയനക്കുകയും ശബ്ദമുണ്ടാക്കുകയും ചെയ്യുമായിരുന്നു. ഒരു ദിവസം അദ്ദേഹം വീട്ടിൽ വന്നു. അദ്ദേഹത്തിന്റെ ശബ്ദം കേട്ടപ്പോൾ ആ സ്ത്രീ മാറിനിന്നു. അങ്ങനെ അദ്ദേഹം എന്റെയടുക്കൽ വന്ന് ഇരുന്നു. എന്നെ തൊട്ടു. അപ്പോൾ ഒരു നൂലിന്റെ സ്പർശം അദ്ദേഹം അറിഞ്ഞു. അദ്ദേഹം ചോദിച്ചു: എന്താണിത്? അപ്പോൾ ഞാൻ പറഞ്ഞു: ചൊള്ള കാരണം എന്റെ കൈയിൽ കെട്ടിയ ഉറുക്കാണ്. അദ്ദേഹം അത് വലിച്ച് മുറിച്ചിട്ടു. എന്നിട്ട് വലിച്ചെറിഞ്ഞുകൊണ്ട് പറഞ്ഞു: അബ്ദുല്ലായുടെ കുടുംബം ശിർക്കിൽ നിന്നും മുക്തരായിരിക്കുന്നു. നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്. "ഉറുക്കും ഏലസ്സും മാരണവും ശിർക്കാണ്." അപ്പോൾ ഞാൻ പറഞ്ഞു: ഒരു ദിവസം ഞാൻ പുറത്ത് പോയപ്പോൾ ഏതോ ഒരാൾ എന്നെ നോക്കി. അപ്പോൾ അയാളുടെ അടുത്തേക്ക് നിൽക്കുന്ന എന്റെ കണ്ണിൽ നിന്ന് വെള്ളമൊലിച്ചു. ഞാൻ ഒരു ഏലസ്സ് കൊണ്ട് മന്ത്രിച്ചപ്പോൾ അത് നിന്നു. ഏലസ്സ് ഒഴിവാക്കിയപ്പോൾ കണ്ണുനീർ വീണ്ടും ഒഴുകി. അപ്പോൾ അബ്ദുല്ല(റ) പറഞ്ഞു: അത് പിശാചിന്റെ പണിയാണ്. നീ പിശാചിനെ അനുസരിക്കുമ്പോൾ അവൻ നിന്നെ വെറുതെവിടുന്നു. അവനെതിരാവുമ്പോൾ അവൻ നിന്റെ കണ്ണിൽ വിരൽ കൊണ്ട് കുത്തുന്നു. എങ്കിലും അല്ലാഹുവിന്റെ റസൂൽ(സ) ചെയ്തതുപോലെ നീ ചെയ്യുകയാണെങ്കിൽ നന്നാകുമായിരുന്നു. നിന്റെ രോഗം ഭേദമാവുകയും ചെയ്യും. നിന്റെ കണ്ണിൽ വെള്ളം തെളിക്കുക, ശേഷം പറയുക: "ജനങ്ങളുടെ രക്ഷിതാവേ, ബുദ്ധിമുട്ടിനെ നീ നീക്കുക, ശമിപ്പിക്കുക, നീയാണ് ശമനം നൽകുന്നവൻ. നിന്റേതല്ലാതെ ശമനമില്ല. സർവ്വ രോഗത്തെയും ഒഴിവാക്കുന്ന ശമനം നൽകുക." (ദ,ജ)', 'زَيْنَبَ - امْرَأَةِ ابْنِ مَسْعُودٍ', 'സൈനബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 664, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ عِمْرَانَ بْنِ الْحُصَيْنِ رَضِيَ اللهُ عَنْهُمَا، أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا فِي يَدِهِ حَلْقَةً مِنْ صُفْرٍ، فَقَالَ: "مَا هَذِهِ الْحَلْقَةُ". قَالَ: هَذِهِ مِنَ الْوَاهِنَةِ. قَالَ: "انْزِعْهَا، فَإِنَّهَا لَا تَزِيدُكَ إِلَّا وَهْنًا". (جه)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): കയ്യിൽ പിത്തള കൊണ്ടുണ്ടാക്കിയ വളയിട്ട ഒരാളെ നബി(സ) കണ്ടു. നബി(സ) ചോദിച്ചു: "ഇതെന്ത് വളയാണ്?" അയാൾ പറഞ്ഞു: ഇത് കയ്യിനും തൊലിക്കും വേദന ബാധിച്ചതു കൊണ്ടാണ്. നബി(സ) പറഞ്ഞു: "നീ ഇത് ഊരിക്കളയുക, ഇത് നിന്റെ ബലക്ഷയം വർധിപ്പിക്കുകയേ ചെയ്യൂ." (ജ)', 'عِمْرَانَ بْنِ الْحُصَيْنِ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا رُقْيَةَ إِلَّا مِنْ عَيْنٍ أَوْ حُمَةٍ". (د,ت)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): നബി(സ) പറഞ്ഞു: "കണ്ണേറിനും വിഷത്തിനും മാത്രമേ ഉറുക്കിന്റെ ഉപയോഗമുള്ളൂ." (ദ,തു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ عِيسَى بْنِ أَبِي لَيْلَى قَالَ: دَخَلْتُ عَلَى عَبْدِ اللهِ بْنِ عُكَيْمٍ أَبِي مَعْبَدٍ الْجُهَنِيِّ أَعُودُهُ وَبِهِ حُمْرَةٌ، فَقُلْنَا: أَلَا تُعَلِّقُ شَيْئًا؟ قَالَ: الْمَوْتُ أَقْرَبُ مِنْ ذَلِكَ، قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَعَلَّقَ شَيْئًا وُكِلَ إِلَيْهِ". (ت)', 'ഈസുബ്നു അബീലൈല(റ): കരപ്പൻ ബാധിച്ച അബ്ദുല്ലാഹിബ്നു ഉകൈം അബീ മഅ്ബദുൽ ജുഹനി(റ)വിനെ ഞാൻ സന്ദർശിച്ചു. ഞങ്ങൾ അദ്ദേഹത്തോട് ചോദിച്ചു: താങ്കൾ ഉറുക്ക് പോലുള്ള ഒന്നും കെട്ടുന്നില്ലെയോ? അദ്ദേഹം പറഞ്ഞു: മരണം അതിനേക്കാൾ അടുത്താണ്, നബി(സ) പറഞ്ഞിട്ടുണ്ട്: "ആരെങ്കിലും (ഉറുക്ക് പോലുള്ള) വല്ലതും കെട്ടിയാൽ അവൻ അതിലേക്ക് ഏൽപിക്കപ്പെടും." (തു)', 'عِيسَى بْنِ أَبِي لَيْلَى قَالَ', 'ഈസുബ്നു അബീലൈല(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا أُبَالِي مَا أَتَيْتُ إِنْ أَنَا شَرِبْتُ تِرْيَاقًا، أَوْ تَعَلَّقْتُ تَمِيمَةً، أَوْ قُلْتُ الشِّعْرَ مِنْ قِبَلِ نَفْسِي". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഞാൻ വിഷഔഷധം കുടിക്കുകയോ ഏലസ്സ് കെട്ടുകയോ എന്റെ സ്വന്തമായ കവിതകൾ പാടുകയോ ചെയ്യുന്നുവെങ്കിൽ ഞാൻ പ്രവർത്തിക്കുന്ന ഒരു കാര്യത്തെയും ഞാനൊരു പ്രശ്നമായി കാണുന്നില്ല." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ أُمِّ جُنْدُبٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَمَى جَمْرَةَ الْعَقَبَةِ مِنْ بَطْنِ الْوَادِي، يَوْمَ النَّحْرِ، ثُمَّ انْصَرَفَ. وَتَبِعَتْهُ امْرَأَةٌ مِنْ خَثْعَمٍ، وَمَعَهَا صَبِيٌّ لَهَا بِهِ بَلَاءٌ، لَا يَتَكَلَّمُ. فَقَالَتْ: يَا رَسُولَ اللهِ، إِنَّ هَذَا ابْنِي وَبَقِيَّةُ أَهْلِي، وَإِنَّ بِهِ بَلَاءً، لَا يَتَكَلَّمُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ائْتُونِي بِشَيْءٍ مِنْ مَاءٍ". فَأُتِيَ بِمَاءٍ، فَغَسَلَ يَدَيْهِ وَمَضْمَضَ فَاهُ ثُمَّ أَعْطَاهَا، فَقَالَ: "اسْقِيهِ مِنْهُ، وَصُبِّي عَلَيْهِ مِنْهُ، وَاسْتَشْفِي اللهَ لَهُ". قَالَتْ: فَلَقِيتُ الْمَرْأَةَ فَقُلْتُ: لَوْ وَهَبْتِ لِي مِنْهُ، فَقَالَتْ: إِنَّمَا هُوَ لِهَذَا الْمُبْتَلَى. قَالَتْ: فَلَقِيتُ الْمَرْأَةَ مِنَ الْحَوْلِ فَسَأَلْتُهَا عَنِ الْغُلَامِ فَقَالَتْ: بَرَأَ وَعَقَلَ عَقْلًا لَيْسَ كَعُقُولِ النَّاسِ. (د,جه)', 'ഉമ്മുജുൻദുബ്(റ): നബി(സ) മലഞ്ചെരുവിൽ നിന്ന് ജംറത്തുൽ അഖബക്ക് ബലിപെരുന്നാൾ ദിവസത്തിൽ എറിയുന്നത് ഞാൻ കണ്ടു. പിന്നെ നബി(സ) അതുകഴിഞ്ഞു പിന്തിരിഞ്ഞു. ഖസ്അം ഗോത്രത്തിൽ പെട്ട ഒരു സ്ത്രീ നബി(സ)യെ പിന്തുടരുന്നുണ്ടായിരുന്നു. അവളുടെ കൂടെ സംസാരിക്കാത്ത രോഗിയായ ഒരു കുഞ്ഞുമുണ്ടായിരുന്നു. അവർ നബി(സ)യോട് പറഞ്ഞു: റസൂലേ, ഇത് എന്റെ മകനാണ്. എനിക്ക് ഇവൻ മാത്രമേയുള്ളൂ. ഇവന് രോഗം പിടിച്ചിട്ടുണ്ട്. സംസാരിക്കാൻ അശക്തനാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അൽപം വെള്ളം കൊണ്ടുവരൂ." വെള്ളം കൊണ്ടുവന്നു. നബി(സ) തന്റെ കൈകൾ കഴുകി. വായ കൊപ്ലിച്ചു. എന്നിട്ട് അത് അവൾക്ക് നൽകി. എന്നിട്ട് പറഞ്ഞു: "ഈ കുട്ടിയെ കുടിപ്പിക്കുകയും അവന്റെ മേൽ ഒഴിക്കുകയും അവന് വേണ്ടി അല്ലാഹുവിനോട് രോഗശമനത്തിന് പ്രാർത്ഥിക്കുകയും ചെയ്യുക." ഉമ്മുജുൻദുബ്(റ) പറയുന്നു: ഞാനാ സ്ത്രീയെ കണ്ടുമുട്ടി. അവളോട് ചോദിച്ചു: അതിൽ നിന്ന് അൽപം എനിക്ക് തരുമോ? അവൾ പറഞ്ഞു: ഇത് രോഗിക്ക് മാത്രമുള്ളതാകുന്നു. ഉമ്മുജുൻദുബ്(റ) വീണ്ടും പറയുന്നു: പിന്നീട് ആ സ്ത്രീയെ അടുത്തവർഷം കണ്ടുമുട്ടിയപ്പോൾ ഞാൻ കുട്ടിയെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ അവൾ പറഞ്ഞു: അവൻ പൂർണ്ണസുഖമായിരിക്കുന്നു, അസാധാരണമായ ബുദ്ധിശക്തിയുള്ളവനായി മാറിയിരിക്കുന്നു. (ദ,ജ)', 'أُمِّ جُنْدُبٍ', 'ഉമ്മുജുൻദുബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 665, 666, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ النُّشْرَةِ، فَقَالَ: "هُوَ مِنْ عَمَلِ الشَّيْطَانِ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഉറുക്ക് കെട്ടുന്നതിനെക്കുറിച്ച് റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അത് പിശാചിന്റെ പ്രവർത്തനങ്ങളിൽ പെട്ടതാണ്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 666, 666, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عُرِضَتْ عَلَيَّ الْأُمَمُ فَجَعَلَ النَّبِيُّ وَالنَّبِيَّانِ يَمُرُّونَ مَعَهُمُ الرَّهْطُ، وَالنَّبِيُّ لَيْسَ مَعَهُ أَحَدٌ حَتَّى رُفِعَ لِي سَوَادٌ عَظِيمٌ، قُلْتُ مَا هَذَا؟ أُمَّتِي هَذِهِ؟ قِيلَ: بَلْ هَذَا مُوسَى وَقَوْمُهُ، قِيلَ: انْظُرْ إِلَى الْأُفُقِ، فَإِذَا سَوَادٌ يَمْلَأُ الْأُفُقَ، ثُمَّ قِيلَ لِي: انْظُرْ هَا هُنَا وَهَا هُنَا فِي آفَاقِ السَّمَاءِ فَإِذَا سَوَادٌ قَدْ مَلَأَ الْأُفُقَ، قِيلَ: هَذِهِ أُمَّتُكَ، وَيَدْخُلُ الْجَنَّةَ مِنْ هَؤُلَاءِ سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ". ثُمَّ دَخَلَ وَلَمْ يُبَيِّنْ لَهُمْ، فَأَفَاضَ الْقَوْمُ، وَقَالُوا: نَحْنُ الَّذِينَ آمَنَّا بِاللهِ وَاتَّبَعْنَا رَسُولَهُ فَنَحْنُ هُمْ أَوْ أَوْلَادُنَا الَّذِينَ وُلِدُوا فِي الْإِسْلَامِ، فَإِنَّا وُلِدْنَا فِي الْجَاهِلِيَّةِ، فَبَلَغَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَخَرَجَ فَقَالَ: "هُمُ الَّذِينَ لَا يَسْتَرْقُونَ، وَلَا يَتَطَيَّرُونَ، وَلَا يَكْتَوُونَ، وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ". فَقَالَ عُكَّاشَةُ بْنُ مِحْصَنٍ: أَمِنْهُمْ أَنَا يَا رَسُولَ اللهِ؟ قَالَ: "نَعَمْ". فَقَامَ آخَرُ فَقَالَ: أَمِنْهُمْ أَنَا؟ قَالَ: "سَبَقَكَ بِهَا عُكَّاشَةُ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): തിരുമേനി(സ) അരുളി: "പൂർവ്വ ജനസമുദായങ്ങളെല്ലാം എന്റെ മുമ്പിൽ പ്രദർശിപ്പിക്കപ്പെട്ടു. ഓരോ നബിയും ഈരണ്ട് നബിമാരും ഓരോ സംഘം അനുചരൻമാരോട് കൂടി നടന്നുകൊണ്ടിരുന്നു. ചില പ്രവാചകൻമാരോടൊപ്പം ആരുമുണ്ടായിരുന്നില്ല. അവസാനം ഒരു വലിയ സംഘം ആളുകൾ എന്റെ മുമ്പിൽ പ്രത്യക്ഷപ്പെട്ടു. ഞാൻ ചോദിച്ചു: ഈ സമുദായമേതാണ്? ഇതെന്റെ സമുദായമാണോ? എന്നോട് പറഞ്ഞു: ഇത് മൂസാ(അ)മും അദ്ദേഹത്തിന്റെ ജനതയുമാണ്. എന്നോട് പറഞ്ഞു: ചക്രവാളത്തിലേക്ക് നോക്കൂ. അപ്പോഴതാ ചക്രവാളം നിറയെ ഒരു ജനസമൂഹം നിൽക്കുന്നു. പിന്നീട് എന്നോട് പറഞ്ഞു: ചക്രവാളത്തിൽ അങ്ങോട്ടുമിങ്ങോട്ടും നോക്കൂ. അപ്പോഴും ആ ചക്രവാളം നിറയെ ജനം നിന്നിരുന്നു. എന്നിട്ട് പറഞ്ഞു: ഇതാണ് താങ്കളുടെ സമുദായം. ഇവരിൽ എഴുപതിനായിരം പേർ വിചാരണ കൂടാതെ സ്വർഗ്ഗത്തിൽ കടക്കും." ഇത്രയുമരുളിയിട്ട് വിശദീകരിക്കാതെ തിരുമേനി(സ) വീട്ടിനുള്ളിലേക്ക് പോയി. ഒന്നും വിശദീകരിച്ചില്ല. ജനങ്ങൾ അതിനെക്കുറിച്ചുള്ള ചർച്ചയിൽ മുഴുകി. അവർ പറഞ്ഞു: ഞങ്ങളാണ് അല്ലാഹുവിൽ വിശ്വസിക്കുകയും അവന്റെ ദൂതനെ പിന്തുടരുകയും ചെയ്തവർ. നാമാണോ അക്കൂട്ടർ അതോ ഇസ്ലാമിൽ ജനിച്ച നമ്മുടെ സന്തതികളാണോ? നാം അജ്ഞാനകാലത്ത് ജനിച്ചവരാണല്ലോ. ഈ സംഭാഷണം തിരുമേനി(സ) അറിഞ്ഞു. അവിടന്ന് പുറത്തുവന്ന് പറഞ്ഞു: "മന്ത്രിച്ച് ഊതാത്തവരും പക്ഷിലക്ഷണം നോക്കാത്തവരും ചൂട് വെക്കാത്തവരും തങ്ങളുടെ രക്ഷിതാവിങ്കൽ എല്ലാം അർപ്പിക്കുന്നവരുമാണ് അക്കൂട്ടർ." അപ്പോൾ ഉക്കാശ(റ) ചോദിച്ചു: റസൂലേ, ഞാൻ ആ കൂട്ടത്തിൽപ്പെടുമോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." ഉടനെ മറ്റൊരാൾ ചോദിച്ചു: അവരിൽ ഞാനുണ്ടോ? തിരുമേനി(സ) അരുളി: "ഉക്കാശ നിന്റെ മുമ്പിൽ കടന്നു." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 666, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رَخَّصَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الرُّقْيَةَ مِنْ كُلِّ ذِي حُمَةٍ. (خ)', 'ആഇശ(റ): വിഷമുള്ള ഏത് ജന്തു കടിച്ചാലും മന്ത്രിക്കുവാൻ തിരുമേനി(സ) അനുവദിച്ചിട്ടുണ്ട്. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 667, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا رُقْيَةَ إِلَّا مِنْ عَيْنٍ أَوْ حُمَةٍ". (م,جه)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "കണ്ണേറിനും വിഷത്തിനുമല്ലാതെ മന്ത്രിച്ചൂതലില്ല." (മു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 667, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ خَالِدَةَ بِنْتِ أَنَسٍ رَضِيَ اللهُ عَنْهَا - أُمِّ بَنِي حَزْمٍ السَّاعِدِيَّةِ: جَاءَتْ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَعَرَضَتْ عَلَيْهِ الرُّقَى، فَأَمَرَهَا بِهَا. (جه)', 'ബനൂഹസ്മിനിസ്സാഇദിയ്യയുടെ ഉമ്മയായ ഖാലിദതു ബിൻതിഅനസ്(റ): മഹതി പ്രവാചക സന്നിധിയിൽ വന്ന് താൻ മന്ത്രിക്കുന്ന മന്തം തിരിമേനി(സ)ക്ക് പറഞ്ഞ്കൊടുത്തു. അപ്പോൾ അവിടന്ന് മഹതിയോട് അത് ചെയ്യാൻ കൽപിച്ചു. (ജ)', 'خَالِدَةَ بِنْتِ أَنَسٍ', 'ബനൂഹസ്മിനിസ്സാഇദിയ്യയുടെ ഉമ്മയായ ഖാലിദതു ബിൻതിഅനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 667, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَهْلُ بَيْتٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُمْ آلُ عَمْرِو بْنِ حَزْمٍ، يَرْقُونَ مِنَ الْحُمَةِ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ نَهَى عَنِ الرُّقَى، فَأَتَوْهُ فَقَالُوا: يَا رَسُولَ اللهِ، إِنَّكَ قَدْ نَهَيْتَ عَنِ الرُّقَى، وَإِنَّا نَرْقِي مِنَ الْحُمَةِ؟ فَقَالَ لَهُمْ: "اعْرِضُوا عَلَيَّ". فَعَرَضُوهَا عَلَيْهِ، فَقَالَ: "لَا بَأْسَ بِهَذِهِ، هَذِهِ مَوَاثِيقُ". (م,جه)', 'ജാബിർ(റ): ''ആലു അംറുബ്നു ഹസ്മ്'' എന്ന് പറയപ്പെടുന്ന അൻസാറുകളിൽപെട്ട ഒരു കുടുംബം വിഷബാധക്ക് മന്ത്രിക്കാറുണ്ടായിരുന്നു. നബി(സ)യാണെങ്കിൽ മന്ത്രിക്കലിനെ നിരോധിച്ചിട്ടുമുണ്ടായിരുന്നു. അപ്പോൾ അവർ നബി(സ)യുടെ സന്നിധിയിൽ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടന്ന് മന്ത്രിക്കലിനെ നിരോധിച്ചിരിക്കുന്നു. ഞങ്ങളാണെങ്കിൽ വിഷബാധക്ക് മന്ത്രിക്കാറുമുണ്ട്. അപ്പോൾ റസൂൽ(സ) അവരോട് പറഞ്ഞു: "നിങ്ങളുടെ മന്ത്രം എനിക്ക് വ്യക്തമാക്കിത്തരിക." അവർ അത് നബി(സ)ക്ക് പറഞ്ഞുകൊടുത്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇതുകൊണ്ട് പ്രശ്നമില്ല, ഇവ (രോഗശമനം കൊണ്ട് അല്ലാഹുവുമായി നടത്തപ്പെട്ട) കരാറുകളിൽപെട്ടതാണ്. (മു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 667, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ فِي الرُّقْيَةِ مِنَ الْحُمَةِ وَالْعَيْنِ وَالنَّمْلَةِ. (م,ت,جه)', 'അനസ്(റ): വിഷത്തിനും കണ്ണേറിനും ശരീരഭാഗങ്ങളിൽ നിന്ന് ചലം ഒലിക്കുന്നതിനും (ചികിത്സയായി) മന്ത്രിക്കുന്നതിൽ നബി(സ) ഇളവ് നൽകി. (മു,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 667, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رَخَّصَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الرُّقْيَةِ مِنَ الْحَيَّةِ وَالْعَقْرَبِ. (م,جه)', 'ആഇശ(റ): പാമ്പ്, തേൾ (എന്നിവയുടെ വിഷത്തിന്) മന്ത്രിച്ചൂതാൻ നബി(സ) ഇളവ് നൽകി. (മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 667, 668, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَدَغَتْ عَقْرَبٌ رَجُلًا، فَلَمْ يَنَمْ لَيْلَتَهُ، فَقِيلَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّ فُلَانًا لَدَغَتْهُ عَقْرَبٌ فَلَمْ يَنَمْ لَيْلَتَهُ؟ فَقَالَ: "أَمَا إِنَّهُ لَوْ قَالَ حِينَ أَمْسَى: أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ، مَا ضَرَّهُ لَدْغُ عَقْرَبٍ حَتَّى يُصْبِحَ". (جه)', 'അബൂഹുറൈറ(റ): ഒരാളെ ഒരു തേൾ കടിക്കുകയും അങ്ങനെ അയാൾ രാത്രി മുഴുവൻ ഉറക്കമൊഴിക്കുകയും ചെയ്തു. അപ്പോൾ നബി(സ)യോട് പറയപ്പെട്ടു: ഇന്നയാളെ തേൾ കടിക്കുകയും, അതിനാൽ അയാൾ രാത്രി മുഴുവൻ ഉറക്കമൊഴിയുകയും ചെയ്തിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ പൂർണ്ണമായ വാക്യങ്ങൾ കൊണ്ട് അവൻ സൃഷ്ടിച്ച സകല നാശങ്ങളിൽ നിന്നും ഞാൻ കാവൽ ചോദിക്കുന്നു എന്ന് അവൻ പ്രദോശസമയത്ത് പറഞ്ഞിരുന്നുവെങ്കിൽ പ്രഭാതം വരെ ഒരു തേളിന്റെ കടിയും അവനെ ബുദ്ധിമുട്ടാക്കുമായിരുന്നില്ല." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 668, 668, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عَمْرِو بْنِ حَزْمٍ رَضِيَ اللهُ عَنْهُ قَالَ: عَرَضْتُ النَّهْشَةَ مِنَ الْحَيَّةِ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ بِهَا. [ز: في إسناده انقطاع] (جه)', 'അംറുബ്നുഹസ്മ്(റ): പാമ്പ് കടിയേറ്റതിനുള്ള ഉറുക്ക് ഞാൻ നബി(സ)ക്ക് കാണിച്ച് കൊടുത്തു. അപ്പോൾ അവിടന്ന് അത് ചെയ്യാൻ കൽപിച്ചു. (ജ)', 'عَمْرِو بْنِ حَزْمٍ', 'അംറുബ്നുഹസ്മ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده انقطاع', null, 668, 668, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَرْقِي فِي الْجَاهِلِيَّةِ، فَقُلْنَا: يَا رَسُولَ اللهِ، كَيْفَ تَرَى فِي ذَلِكَ؟ فَقَالَ: "اعْرِضُوا عَلَيَّ رُقَاكُمْ، لَا بَأْسَ بِالرُّقَى مَا لَمْ تَكُنْ شِرْكًا". (م,د)', 'ഔഫുബ്നു മാലിക്(റ): ഞങ്ങൾ ജാഹിലിയ്യാ കാലത്ത് മന്ത്രിക്കാറുണ്ടായിരുന്നു. അപ്പോൾ ഞങ്ങൾ ചോദിച്ചു: തിരുദൂതരേ, അതിനെക്കുറിച്ച് അവിടുന്ന് എന്തു പറുയുന്നു? അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ മന്ത്രിക്കുന്ന മന്ത്രങ്ങൾ എനിക്ക് വെളിവാക്കിത്തരിക. മന്ത്രം ശിർക്കാവാത്ത കാലമത്രയും അതിൽ പ്രശ്നമില്ല." (മു,ദ)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 668, 668, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنِ الشِّفَاءِ بِنْتِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا عِنْدَ حَفْصَةَ، فَقَالَ لِي: "أَلَا تُعَلِّمِينَ هَذِهِ رُقْيَةَ النَّمْلَةِ كَمَا عَلَّمْتِيهَا الْكِتَابَةَ". (د)', 'ശിഫാഉബിൻത് അബ്ദില്ല(റ): ഞാൻ ഹഫ്സ(റ)യുടെ കൂടെയായിരുന്നപ്പോൾ എന്റെയടുത്തേക്ക് നബി(സ) കടന്നുവന്നു. അപ്പോൾ അവിടുന്ന് എന്നോട് പറഞ്ഞു: "നീ അവൾക്ക് എഴുത്ത് പഠിപ്പിച്ചത് പോലെ, ചൊറിക്കുള്ള മന്ത്രവും പഠിപ്പിക്കുന്നില്ലേ?" (ദ)', 'الشِّفَاءِ بِنْتِ عَبْدِ اللهِ', 'ശിഫാഉബിൻത് അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 668, 668, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنِ الرَّبَابِ قَالَتْ: سَمِعْتُ سَهْلَ بْنَ حُنَيْفٍ رَضِيَ اللهُ عَنْهُ يَقُولُ: مَرَرْنَا بِسَيْلٍ، فَدَخَلْتُ فَاغْتَسَلْتُ فِيهِ، فَخَرَجْتُ مَحْمُومًا، فَنُمِيَ ذَلِكَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "مُرُوا أَبَا ثَابِتٍ يَتَعَوَّذُ". قَالَتْ: فَقُلْتُ: يَا سَيِّدِي وَالرُّقَى صَالِحَةٌ؟ فَقَالَ: "لَا رُقْيَةَ إِلَّا فِي نَفْسٍ أَوْ حُمَةٍ أَوْ لَدْغَةٍ". (د,جه)', 'റബാബ്(റ): സഹ്ലുബ്നു ഹുനൈഫ്(റ) പറയുന്നതായി ഞാൻ കേട്ടു: കുത്തിയൊലിക്കുന്ന വെള്ളത്തിന്റെയരികിലൂടെ ഞങ്ങൾ നടന്നു. അപ്പോൾ ഞാനതിൽ പ്രവേശിക്കുകയും അതിൽ കുളിക്കുകയും പനിബാധിച്ചവനായി പുറത്ത് വരികയും ചെയ്തു. അപ്പോൾ ആ വാർത്ത നബി(സ)യോട് പറയപ്പെട്ടു. അവിടുന്ന് പറഞ്ഞു: "അബൂസാബിതിനോട് കാവൽ ചോദിക്കാൻ കൽപിക്കൂ." റബാബ്(റ) പറയുന്നു: അപ്പോൾ ഞാൻ ചോദിച്ചു: എന്റെ നേതാവേ, മന്ത്രം നല്ലതാണോ? അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "കണ്ണേറ്, വിഷബാധ, തേളിന്റെ കടി എന്നിവക്കല്ലാതെ മന്ത്രിക്കലില്ല." (ദ,ജ)', 'الرَّبَابِ قَالَتْ', 'റബാബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 668, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا رُقْيَةَ إِلَّا مِنْ عَيْنٍ أَوْ حُمَةٍ أَوْ دَمٍ يَرْقَأُ". (م,د,ت,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "കണ്ണേറ്, വിഷബാധ, മുറിയുന്ന രക്തം എന്നിവക്കല്ലാതെ മന്ത്രിക്കലില്ല." (മു,ദ,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 669, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَهْطًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ انْطَلَقُوا فِي سَفْرَةٍ سَافَرُوهَا، فَنَزَلُوا بِحَيٍّ مِنْ أَحْيَاءِ الْعَرَبِ، فَقَالَ بَعْضُهُمْ: إِنَّ سَيِّدَنَا لُدِغَ، فَهَلْ عِنْدَ أَحَدٍ مِنْكُمْ شَيْءٌ يَنْفَعُ صَاحِبَنَا؟ فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: نَعَمْ، وَاللهِ إِنِّي لَأَرْقِي، وَلَكِنِ اسْتَضَفْنَاكُمْ فَأَبَيْتُمْ أَنْ تُضَيِّفُونَا، مَا أَنَا بِرَاقٍ حَتَّى تَجْعَلُوا لِي جُعْلًا. فَجَعَلُوا لَهُ قَطِيعًا مِنَ الشَّاءِ، فَأَتَاهُ فَقَرَأَ عَلَيْهِ أُمَّ الْكِتَابِ، وَيَتْفُلُ حَتَّى بَرَأَ، كَأَنَّمَا أُنْشِطَ مِنْ عِقَالٍ، قَالَ: فَأَوْفَاهُمْ جُعْلَهُمُ الَّذِي صَالَحُوهُمْ عَلَيْهِ، فَقَالُوا: اقْتَسِمُوا، فَقَالَ الَّذِي رَقَى: لَا تَفْعَلُوا حَتَّى نَأْتِيَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنَسْتَأْمِرَهُ، فَغَدَوْا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرُوا لَهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مِنْ أَيْنَ عَلِمْتُمْ أَنَّهَا رُقْيَةٌ؟ أَحْسَنْتُمْ، اقْتَسِمُوا وَاضْرِبُوا لِي مَعَكُمْ بِسَهْمٍ". (ق,د,ت,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ)യുടെ അനുചരന്മാരിൽ നിന്നുള്ള ഒരു സംഘം ഒരു യാത്രപുറപ്പെട്ടു. അങ്ങനെ അവർ ഒരു അരബി ഗോത്രത്തിൽ ചെന്ന് ഇറങ്ങി. അപ്പോൾ ഗോത്രക്കാരിൽ ചിലർ പറഞ്ഞു: ഞങ്ങളുടെ നേതാവിന് വിഷമേറ്റിരിക്കുന്നു. അദ്ദേഹത്തിന് ഉപകാരപ്പെടുന്ന എന്തെങ്കിലും നിങ്ങളിൽ ആരുടെ പക്കലെങ്കിലും ഉണ്ടോ? അപ്പോൾ സ്വഹാബികളിൽ ഒരാൾ പറഞ്ഞു: അതെ. അല്ലാഹുവാണ് സത്യം, ഞാൻ മന്ത്രിക്കും. പക്ഷേ, നിങ്ങളോട് ഞങ്ങളെ അതിഥികളായി സ്വീകരിക്കാൻ പറഞ്ഞു. പക്ഷേ, നിങ്ങളതിന് വിസമ്മതിക്കുകയും ഞങ്ങളെ അതിഥികളായി സ്വീകരിക്കാതിരിക്കുകയും ചെയ്തു. അതിനാൽ നിങ്ങൾ എനിക്കായി എന്തെങ്കിലും നൽകാനായി മാറ്റിവെക്കാതെ ഞാൻ മന്ത്രിക്കുകയില്ല. അപ്പോൾ അവർ അദ്ദേഹത്തിനായി കുറച്ച് ആടുകളെ മാറ്റിവെച്ചു. അപ്പോൾ അദ്ദേഹം നേതാവിന്റെയടുക്കൽ പോവുകയും അദ്ദേഹത്തിന്റെ മേൽ സൂറതുൽ ഫാതിഹ ഓതുകയും തുപ്പുകയും ചെയ്തു. അങ്ങനെ അയാൾ ബന്ധനത്തിൽ നിന്ന് മോചിതനായത് പോലെ സുഖം പ്രാപിച്ചു. നിവേദകൻ പറയുന്നു: പരസ്പരം ധാരണയിലെത്തി മാറ്റിവെച്ച ആടുകളെ അവർ സ്വഹാബാക്കൾക്ക് നൽകി. അപ്പോൾ സ്വഹാബികൾ പറഞ്ഞു: നിങ്ങൾ അത് വീതിക്കുക. അപ്പോൾ മന്ത്രിച്ച ആൾ പറഞ്ഞു: നാം നബി(സ)യുടെ അടുത്ത് ചെന്ന് അവിടത്തോട് നമ്മുടെ ഈ കാര്യത്തിൽ കൂടിയാലോചിക്കുന്നത്വരെ നിങ്ങളത് ചെയ്യരുത്. അങ്ങനെ അവർ പിറ്റേന്ന് രാവിലെ നബി(സ)യുടെ അടുക്കൽ ചെല്ലുകയും നബി(സ)യോട് വിവരങ്ങൾ പറയുകുയം ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് (ഫാതിഹ) ഒരു മന്ത്രമാണെന്നത് നിങ്ങൾ എങ്ങനെയാണറിഞ്ഞത്? എന്തായാലും നിങ്ങൾ ചെയ്തത് വളരെ നന്നായി. നിങ്ങളത് വീതിക്കുകയും നിങ്ങളോട് കൂടെ എനിക്കായി ഒരു ഓഹരി നൽകുകയും ചെയ്യുക." (ബു,മു,ദ,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 669, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ خَارِجَةَ بْنِ الصَّلْتِ التَّمِيمِيِّ، عَنْ عَمِّهِ رَضِيَ اللهُ عَنْهُ قَالَ: أَقْبَلْنَا مِنْ عِنْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْنَا عَلَى حَيٍّ مِنَ الْعَرَبِ، فَقَالُوا: إِنَّا أُنْبِئْنَا أَنَّكُمْ قَدْ جِئْتُمْ مِنْ عِنْدِ هَذَا الرَّجُلِ بِخَيْرٍ، فَهَلْ عِنْدَكُمْ مِنْ دَوَاءٍ أَوْ رُقْيَةٍ، فَإِنَّ عِنْدَنَا مَعْتُوهًا فِي الْقُيُودِ؟ قَالَ: فَقُلْنَا: نَعَمْ، قَالَ: فَجَاءُوا بِمَعْتُوهٍ فِي الْقُيُودِ، قَالَ: فَقَرَأْتُ عَلَيْهِ فَاتِحَةَ الْكِتَابِ ثَلَاثَةَ أَيَّامٍ غُدْوَةً وَعَشِيَّةً، كُلَّمَا خَتَمْتُهَا أَجْمَعُ بُزَاقِي ثُمَّ أَتْفُلُ، فَكَأَنَّمَا نَشِطَ مِنْ عِقَالٍ، قَالَ: فَأَعْطَوْنِي جُعْلًا، فَقُلْتُ: لَا، حَتَّى أَسْأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: "كُلْ، فَلَعَمْرِي مَنْ أَكَلَ بِرُقْيَةِ بَاطِلٍ لَقَدْ أَكَلْتَ بِرُقْيَةِ حَقٍّ". (د,ت)', 'ഖാരിജതുബ്നു സ്വൽതുത്തമീമി(റ): ഞങ്ങൾ നബി(സ)യുടെ അടുത്ത് നിന്ന് പുറപ്പെട്ട് ഒരു അറബി ഗോത്രക്കാരുടെ അടുത്ത് എത്തി. അപ്പോൾ അവർ പറഞ്ഞു: നിങ്ങൾ ഈ മനുഷ്യന്റെ (നബി(സ)യുടെ) അടുക്കൽ നിന്നും ഒരു നന്മയുമായാണ് വരുന്നതെന്ന് ഞങ്ങൾ അറിയിക്കപ്പെട്ടിരിക്കുന്നു. അതുകൊണ്ട് നിങ്ങളുടെ അടുക്കൽ വല്ല മരുന്നോ അല്ലെങ്കിൽ വല്ല മന്ത്രങ്ങളോ ഉണ്ടോ. കാരണം, ഞങ്ങളുടെ പക്കൽ ബന്ധനത്തിൽ കിടക്കുന്ന ഒരു ഭ്രാന്തനുണ്ട്? നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: അതെ. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞാൻ അദ്ദേഹത്തിന്റെ മേൽ മൂന്ന് ദിവസം പ്രഭാതത്തിലും പ്രദോശത്തിലും സൂറതുൽ ഫാതിഹ ഓതുകയും ഓരോ പ്രാവശ്യവും ഓതിക്കഴിയുമ്പോൾ ഞാനെന്റെ ഉമിനീരിനെ ഒരുമിച്ചുകൂട്ടുകയും പിന്നെയതിനെ തുപ്പുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം ഭ്രാന്ത് മാറി ഉന്മേശവാനായത് പോലെയുണ്ട്. നിവേദകൻ പറയുന്നു: അപ്പോൾ അവരെനിക്ക് ഒരു സമ്മാനം തന്നു. അപ്പോൾ ഞാൻ പറഞ്ഞു: പ്രവാചകർ(സ)യോട് ചോദിക്കും വരെ എനിക്കത് വേണ്ട. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ ഭക്ഷിക്കുക, എന്റെ ആയുസ്സ്തന്നെയാണ് സത്യം, ആരെങ്കിലും പൊള്ളയായ മന്ത്രം കൊണ്ട് ഭക്ഷിക്കുന്നുണ്ടെങ്കിൽ നീ ഭക്ഷിക്കുന്നത് യഥാർത്ഥ മന്ത്രം കൊണ്ടാണ്." (ദ,തു)', 'خَارِجَةَ بْنِ الصَّلْتِ التَّمِيمِيِّ، عَنْ عَمِّهِ', 'ഖാരിജതുബ്നു സ്വൽതുത്തമീമി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 669, 670, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَحَرَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَهُودِيٌّ مِنْ يَهُودِ بَنِي زُرَيْقٍ، يُقَالُ لَهُ لَبِيدُ بْنُ الْأَعْصَمِ، حَتَّى كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُخَيَّلُ إِلَيْهِ أَنَّهُ يَفْعَلُ الشَّيْءَ وَلَا يَفْعَلُهُ. قَالَتْ: حَتَّى إِذَا كَانَ ذَاتَ يَوْمٍ - أَوْ كَانَ ذَاتَ لَيْلَةٍ - دَعَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ دَعَا، ثُمَّ دَعَا، ثُمَّ قَالَ: "يَا عَائِشَةُ، أَشَعَرْتِ أَنَّ اللهَ قَدْ أَفْتَانِي فِيمَا اسْتَفْتَيْتُهُ فِيهِ؟ جَاءَنِي رَجُلَانِ، فَجَلَسَ أَحَدُهُمَا عِنْدَ رَأْسِي وَالْآخَرُ عِنْدَ رِجْلِي، فَقَالَ الَّذِي عِنْدَ رَأْسِي لِلَّذِي عِنْدَ رِجْلِي، أَوِ الَّذِي عِنْدَ رِجْلِي لِلَّذِي عِنْدَ رَأْسِي: مَا وَجَعُ الرَّجُلِ؟ قَالَ: مَطْبُوبٌ. قَالَ: مَنْ طَبَّهُ؟ قَالَ: لَبِيدُ بْنُ الْأَعْصَمِ. قَالَ: فِي أَيِّ شَيْءٍ؟ قَالَ: فِي مُشْطٍ وَمُشَاطَةٍ، وَجُفِّ طَلْعَةِ ذَكَرٍ. قَالَ: وَأَيْنَ هُوَ؟ قَالَ: فِي بِئْرِ ذِي أَرْوَانَ". قَالَتْ: فَأَتَاهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي أُنَاسٍ مِنْ أَصْحَابِهِ، ثُمَّ جَاءَ فَقَالَ: "وَاللهِ يَا عَائِشَةُ، لَكَأَنَّ مَاءَهَا نُقَاعَةُ الْحِنَّاءِ، وَلَكَأَنَّ نَخْلَهَا رُءُوسُ الشَّيَاطِينِ". قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ، أَفَلَا أَحْرَقْتَهُ؟ قَالَ: "لَا، أَمَّا أَنَا فَقَدْ عَافَانِي اللهُ، وَكَرِهْتُ أَنْ أُثِيرَ عَلَى النَّاسِ مِنْهُ شَرًّا". فَأَمَرَ بِهَا فَدُفِنَتْ. (ق,جه)', 'ആഇശ(റ): ബനൂസുറൈഖിൽ പെട്ട ഒരു ജൂതൻ നബി(സ)ക്കെതിരെ മാരണം ചെയ്തു. ലബീദുബ്നുൽ അഅ്സം എന്നായിരുന്നു അയാളുടെ പേര്. കാര്യങ്ങൾ ചെയ്യാതെ തന്നെ എല്ലാം ചെയ്യുന്നുണ്ടെന്ന ഒരു തോന്നൽ നബി(സ)ക്ക് ഉണ്ടാകുന്ന അവസ്ഥയുണ്ടായി. ആഇശ(റ) പറയുന്നു: ഒരു പകൽ സമയത്ത് - അല്ലെങ്കിൽ രാത്രിയിൽ - നബി(സ) പ്രാർത്ഥിച്ചു. പിന്നെയും പലപ്രാവശ്യം ദുആ ചെയ്തു. പിന്നീട് പറഞ്ഞു: "ആഇശാ, നീയറിഞ്ഞില്ലേ, എന്റെ തേട്ടത്തിന് അല്ലാഹു മറുപടി നൽകിയിരിക്കുന്നു. രണ്ട് ആളുൾ വന്നുകൊണ്ട് എന്റെ കാലിന്റെയും തലയുടെയും സമീപങ്ങളിലായി ഇരുന്നു. തലയുടെ ഭാഗത്തിരുന്ന ആൾ കാൽഭാഗത്തിരുന്നയാളോട് - അല്ലെങ്കിൽ കാൽഭാഗത്തിരുന്ന ആൾ തലഭാഗത്തിരിക്കുന്നവനോട് - ചോദിച്ചു: ഈ മനുഷ്യന്റെ അസുഖമെന്താണ്? മറ്റെയാൾ പറഞ്ഞു: മാരണം ചെയ്യപ്പെട്ടതാണ്. ഒന്നാമൻ ചോദിച്ചു: ആരാണ് മാരണം ചെയ്തത്? രണ്ടാമൻ പറഞ്ഞു: ലബീദുബ്നുൽ അഅ്സം. ഒന്നാമൻ ചോദിച്ചു: എന്ത് വസ്തുവിലാണ് ചെയ്തത്? രണ്ടാമൻ പറഞ്ഞു: ചീർപ്പിലും ചീകുമ്പോൾ കൊഴിഞ്ഞുവീണ മുടിയിലും ഈത്തപ്പന പൂമ്പൊടിയിലും. ഒന്നാമൻ ചോദിച്ചു: എവിടെയാണതുള്ളത്? രണ്ടാമൻ പറഞ്ഞു: ദൂഅർവാൻ കിണറ്റിൽ." ആഇശ(റ) പറയുന്നു: അപ്പോൾ നബി(സ) കുറച്ച് സ്വഹാബാക്കളുടെ കൂടെ കിണറിനടുത്തു പോയി തിരിച്ചുപോന്നു പറഞ്ഞു: "ആഇശാ, അല്ലാഹുവാണ് സത്യം, ആ കിണറ്റിലെ വെള്ളം മൈലാഞ്ചി ചേർത്തതു പോലെയുണ്ട്. അവിടെയുള്ള ഈത്തപ്പനകൾ പിശാചുക്കളുടെ ശിരസ്സ് പോലെയുണ്ട്." ആഇശ(റ) പറയുന്നു: ഞാൻ ചോദിച്ചു: "നബിയേ, നിങ്ങൾ അതിനെ കരിച്ചുകളഞ്ഞില്ലേ? നബി(സ) പറഞ്ഞു: "ഇല്ല, അല്ലാഹു എനിക്ക് സുഖപ്പെടുത്തിത്തന്നിരിക്കുന്നു. ഇനി അത് കാരണം ജനങ്ങളെ ബുദ്ധിമുട്ടാക്കാൻ ഞാനിഷ്ടപ്പെടുന്നില്ല." പിന്നീട് നബി(സ) അത് കുഴിച്ചിടാൻ കൽപിക്കുകയും അത് മൂടപ്പെടുകയും ചെയ്തു. (ബു,മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 670, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ قَدِمَ رَجُلَانِ مِنَ الْمَشْرِقِ فَخَطَبَا، فَعَجِبَ النَّاسُ لِبَيَانِهِمَا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ الْبَيَانِ لَسِحْرًا، أَوْ: إِنَّ بَعْضَ الْبَيَانِ لَسِحْرٌ". (خ,د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): കിഴക്ക് ഭാഗത്തുനിന്ന് രണ്ടാളുകൾ വന്നു. അവർ പ്രസംഗിച്ചു. അപ്പോൾ ജനങ്ങൾ അവരുടെ പ്രഭാഷണം കേട്ട് അദ്ഭുതം കൂറി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "തീർച്ചയായും പ്രഭാഷണത്തിൽ മാരണശക്തിയുണ്ട് - അല്ലെങ്കിൽ ചില പ്രസംഗങ്ങൾ മാരണമാണ്." (ബു,ദ)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 671, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى فِي امْرَأَتَيْنِ مِنْ هُذَيْلٍ اقْتَتَلَتَا، فَرَمَتْ إِحْدَاهُمَا الْأُخْرَى بِحَجَرٍ، فَأَصَابَ بَطْنَهَا وَهِيَ حَامِلٌ، فَقَتَلَتْ وَلَدَهَا الَّذِي فِي بَطْنِهَا، فَاخْتَصَمُوا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَضَى أَنَّ دِيَةَ مَا فِي بَطْنِهَا غُرَّةُ عَبْدٍ أَوْ أَمَةٍ، فَقَالَ وَلِيُّ الْمَرْأَةِ الَّتِي غَرِمَتْ: كَيْفَ أَغْرَمُ يَا رَسُولَ اللهِ مَنْ لَا شَرِبَ وَلَا أَكَلَ وَلَا نَطَقَ وَلَا اسْتَهَلَّ فَمِثْلُ ذَلِكَ بَطَلٌ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا هَذَا مِنْ إِخْوَانِ الْكُهَّانِ". (خ)', 'അബൂഹുറൈറ(റ): ഹുദൈൽ ഗോത്രത്തിൽപ്പെട്ട രണ്ട് സ്ത്രീകളുടെ പ്രശ്നത്തിൽ നബി(സ) വിധി പറഞ്ഞു. അവരിരുവരും പോരടിക്കുകയും ഒരുത്തി മറ്റവളെ കല്ല് കൊണ്ടെറിയുകയും, ഗർഭിണിയായ അവളുടെ വയറിൽ പതിക്കുകയും ചെയ്തു. അങ്ങനെ അവളുടെ വയറ്റിലുണ്ടായിരുന്ന ശിശു മരിച്ചു. ജനങ്ങൾ പ്രശ്നം നബി(സ)യോടുന്നയിച്ചു. അവളുടെ ഗർഭത്തിലുള്ള ശിശുവിന്റെ നഷ്ടപരിഹാരം ഒരു അടിമയോ അടിമസ്ത്രീയോ ആണെന്ന് നബി(സ) വിധി പറഞ്ഞു. അപ്പോൾ കടക്കാരിയായ സ്ത്രീയുടെ കൈകാര്യകർത്താവ് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ശബ്ദമുണ്ടാക്കുകയോ സംസാരിക്കുകയോ ഭക്ഷിക്കുകയോ കുടിക്കുകയോ ചെയ്തിട്ടില്ലാത്ത ഒരുത്തന്റെ പേരിൽ ഞാനെങ്ങനെയാണ് കടക്കാരനാകുക? അതുപോലുള്ളതെല്ലാം നശിച്ചതാണല്ലേ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം ഇവൻ ജ്യോത്സന്മാരുടെ സഹോദരങ്ങളിൽപ്പെട്ടവനാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 671, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ثَمَنِ الْكَلْبِ، وَمَهْرِ الْبَغِيِّ، وَحُلْوَانِ الْكَاهِنِ. (ق,د,ت,ن,جه)', 'അബൂമസ്ഊദുൽ അൻസാരി(റ): നായയെ വിറ്റ കാശിനെയും, വേശ്യകൾക്ക് നൽകപ്പെടുന്ന വേദനത്തെയും ജ്യോതിഷന്മാരുടെ സമ്മാനത്തെയും നബി(സ) വിലക്കി. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബൂമസ്ഊദുൽ അൻസാരി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 671, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَتَى كَاهِنًا فَصَدَّقَهُ بِمَا يَقُولُ، أَوْ أَتَى امْرَأَتَهُ حَائِضًا، أَوْ أَتَى امْرَأَتَهُ فِي دُبُرِهَا، فَقَدْ بَرِئَ مِمَّا أُنْزِلَ عَلَى مُحَمَّدٍ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു ജ്യോത്സ്യനെ സമീപിക്കുകയും അയാൾ പറയുന്നത് വിശ്വസിക്കുകയും ചെയ്താൽ, അല്ലെങ്കിൽ ആർത്തവകാരിയായ തന്റെ ഭാര്യയുമായി ബന്ധപ്പെട്ടാൽ, അല്ലെങ്കിൽ തന്റെ ഭാര്യയെ പിൻദ്വാരത്തിലൂടെ ബന്ധപ്പെട്ടാൽ, തീർച്ചയായും അവൻ അല്ലാഹു മുഹമ്മദിന്റെ മേൽ ഇറക്കിയതിൽ നിന്ന് മുക്തനായിരിക്കുന്നു (കാഫിറായിരിക്കുന്നു)." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اقْتَبَسَ عِلْمًا مِنَ النُّجُومِ اقْتَبَسَ شُعْبَةً مِنَ السِّحْرِ، زَادَ مَا زَادَ". (د,جه)', 'ഇബ്നു അബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും നക്ഷത്രങ്ങളിൽ നിന്ന് വിജ്ഞാനം സമ്പാദിച്ചാൽ അവൻ സിഹ്റിൽ നിന്ന് ഒരു ഭാഗത്തെ സമ്പാദിച്ചിരിക്കുന്നു. ആ വിജ്ഞാനം കൂടുതലാകുന്നതിന് അനുസൃതമായി സിഹ്റിന്റെ തോതും കൂടും." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: صَلَّى لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الصُّبْحِ بِالْحُدَيْبِيَةِ فِي إِثْرِ سَمَاءٍ كَانَتْ مِنَ اللَّيْلِ، فَلَمَّا انْصَرَفَ أَقْبَلَ عَلَى النَّاسِ فَقَالَ: "هَلْ تَدْرُونَ مَاذَا قَالَ رَبُّكُمْ". قَالُوا: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "قَالَ: أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي وَكَافِرٌ: فَأَمَّا مَنْ قَالَ: مُطِرْنَا بِفَضْلِ اللهِ وَبِرَحْمَتِهِ، فَذَلِكَ مُؤْمِنٌ بِي كَافِرٌ بِالْكَوْكَبِ. وَأَمَّا مَنْ قَالَ: مُطِرْنَا بِنَوْءِ كَذَا وَكَذَا، فَذَلِكَ كَافِرٌ بِي مُؤْمِنٌ بِالْكَوْكَبِ". (ق,د)', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ): രാത്രിയിൽ വർഷിച്ച ഒരു മഴയുടെ പിറകെ, നബി(സ) ഞങ്ങൾക്ക് ഇമാമായിനിന്ന് ഹുദൈബിയ്യയിൽ വെച്ച് സുബ്ഹി നിസ്കരിച്ചു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ നബി(സ) ജനങ്ങളിലേക്ക് മുന്നിട്ട് ഇപ്രകാരം ചോദിച്ചു: "നിങ്ങളുടെ രക്ഷിതാവ് എന്താണ് പറയുന്നതെന്ന് നിങ്ങൾക്കറിയുമോ?" അവർ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ ദൂതനുമാണ് ഏറ്റവും അറിയുന്നവർ. നബി(സ) പറഞ്ഞു: "അല്ലാഹു പറയുന്നു: എന്റെ അടിമകളിൽ എന്നെക്കൊണ്ട് വിശ്വസിക്കുന്നവരും നിഷേധിക്കുന്നവരും ഉണ്ട്. അല്ലാഹുവിന്റെ ഔദാര്യംകൊണ്ടും കാരുണ്യംകൊണ്ടും നമുക്ക് മഴ നൽകപ്പെടുന്നു എന്നു പറഞ്ഞവരാണ് എന്നെക്കൊണ്ട് വിശ്വസിക്കുന്നവരും നക്ഷത്രങ്ങളെ നിഷേധിക്കുന്നവരും. ഇന്ന രാശി കാരണത്താലാണ് നമുക്ക് മഴ ലഭിച്ചതെന്ന് പറയുന്നവരാണ് എന്നെ നിഷേധിക്കുന്നവരും നക്ഷത്രങ്ങളെ വിശ്വസിക്കുന്നവരും." (ബു,മു,ദ)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الطِّيَرَةُ شِرْكٌ، الطِّيَرَةُ شِرْكٌ" ثَلَاثًا "وَمَا مِنَّا إِلَّا، وَلَكِنَّ اللهَ يُذْهِبُهُ بِالتَّوَكُّلِ". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പക്ഷിലക്ഷണം ശിർക്കാണ്. പക്ഷിലക്ഷണം ശിർക്കാണ്." മൂന്ന് പ്രാവശ്യം ആവർത്തിച്ചു. "അത് അൽപമെങ്കിലും മനസ്സിലില്ലാത്തവർ നമ്മിലുണ്ടാവില്ല. എന്നാൽ തവക്കുൽ (ഭരമേൽപിക്കൽ) കൊണ്ട് അല്ലാഹു അത് നീക്കിക്കളയും." (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا عَدْوَى، وَلَا هَامَةَ، وَلَا نَوْءَ، وَلَا صَفَرَ". (م,د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പകർച്ച വ്യാധിയില്ല, ഹാമത് ലക്ഷണവുമില്ല, രാശി നോട്ടമില്ല, മാസലക്ഷണവുമില്ല." (മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا طِيَرَةَ وَخَيْرُهَا الْفَأْلُ". قَالُوا: وَمَا الْفَأْلُ؟ قَالَ: "الْكَلِمَةُ الصَّالِحَةُ يَسْمَعُهَا أَحَدُكُمْ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പക്ഷിലക്ഷണമില്ല. അതിൽ ഏറ്റവും ഉത്തമം ശുഭാപ്തി വാക്കാണ്." അവർ ചോദിച്ചു: എന്താണ് ശുഭാപ്തി വാക്ക്? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ കേൾക്കുന്ന നല്ല വാക്കാണത്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعْجِبُهُ الْفَأْلُ الْحَسَنُ، وَيَكْرَهُ الطِّيَرَةَ. (جه)', 'അബൂഹുറൈറ(റ): ശുഭാപ്തി വാക്ക് നബി(സ)യെ അത്ഭുതപ്പെടുത്തുമായിരുന്നു. പക്ഷിലക്ഷണത്തെ അവിടുന്ന് വെറുത്തിരുന്നു. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا غُولَ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പൊട്ടിപിശാച് ഇല്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا عَدْوَى وَلَا طِيَرَةَ، وَيُعْجِبُنِي الْفَأْلُ الصَّالِحُ، وَالْفَأْلُ الصَّالِحُ الْكَلِمَةُ الْحَسَنَةُ". (ق,د,ت,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "പകർച്ചവ്യാധിയില്ല, പക്ഷിലക്ഷണമില്ല, ശുഭാപ്തി വാക്ക് എന്നെ അത്ഭുതപ്പെടുത്തുന്നു. അതുകൊണ്ടുദ്ദേശിക്കുന്നത് നല്ല വാക്കാണ്." (ബു,മു,ദ,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَمِعَ كَلِمَةً فَأَعْجَبَتْهُ، فَقَالَ: "أَخَذْنَا فَأْلَكَ مِنْ فِيكَ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) ഒരു വചനം കേട്ടു. നബി(സ)യെ അത് അത്ഭുതപ്പെടുത്തി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "താങ്കളുടെ വായിൽ നിന്നുള്ള ശകുനം ഞാൻ സ്വീകരിച്ചു." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ عُرْوَةَ بْنِ عَامِرٍ الْقُرَشِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: ذُكِرَتِ الطِّيَرَةُ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَحْسَنُهَا الْفَأْلُ، وَلَا تَرُدُّ مُسْلِمًا، فَإِذَا رَأَى أَحَدُكُمْ مَا يَكْرَهُ فَلْيَقُلِ: اللَّهُمَّ لَا يَأْتِي بِالْحَسَنَاتِ إِلَّا أَنْتَ وَلَا يَدْفَعُ السَّيِّئَاتِ إِلَّا أَنْتَ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِكَ". (د)', 'ഉർവതുബ്നു ആമിറുൽ ഖുറശി(റ): പക്ഷിലക്ഷണത്തെക്കുറിച്ച് നബി(സ)യുടെ സന്നിധിയിൽ വെച്ച് പറയപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവയിൽ ഏറ്റവും നല്ലത് ശുഭാപ്തി വാക്കാണ്. ഒരു മുസ്ലിമിനും അത് തട്ടുകയില്ല. നിങ്ങളാരെങ്കിലും വെറുപ്പുളവാക്കുന്ന വല്ലതും കണ്ടാൽ ചൊല്ലുക: അല്ലാഹുമ്മ ലാ യഅ്തീ ബിൽ ഹസനാത്തി ഇല്ലാ അൻത്ത, വലാ യദ്ഫഉസ്സയ്യിആത്തി ഇല്ലാ അൻത്ത, വലാ ഹൗല വലാ ഖുവ്വത്ത ഇല്ലാ ബിക്ക (അല്ലാഹുവേ, നന്മകളെ കൊണ്ടുവരുന്നവൻ നീ മാത്രമാണ്. തിന്മകളെ തടയുന്നവനും നീ മാത്രം. ശക്തിയും കഴിവും നിന്നെക്കൊണ്ട് മാത്രം)." (ദ)', 'عُرْوَةَ بْنِ عَامِرٍ الْقُرَشِيِّ', 'ഉർവതുബ്നു ആമിറുൽ ഖുറശി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَتَطَيَّرُ مِنْ شَيْءٍ، وَكَانَ إِذَا بَعَثَ عَامِلًا سَأَلَ عَنِ اسْمِهِ: فَإِذَا أَعْجَبَهُ اسْمُهُ فَرِحَ بِهِ وَرُئِيَ بِشْرُ ذَلِكَ فِي وَجْهِهِ، وَإِنْ كَرِهَ اسْمَهُ رُئِيَ كَرَاهِيَةُ ذَلِكَ فِي وَجْهِهِ، وَإِذَا دَخَلَ قَرْيَةً سَأَلَ عَنِ اسْمِهَا: فَإِنْ أَعْجَبَهُ اسْمُهَا فَرِحَ وَرُئِيَ بِشْرُ ذَلِكَ فِي وَجْهِهِ. وَإِنْ كَرِهَ اسْمَهَا رُئِيَ كَرَاهِيَةُ ذَلِكَ فِي وَجْهِهِ. (د)', 'ബുറൈദ(റ): നബി(സ) ഒരു വസ്തുവിലും പക്ഷിലക്ഷണം പറയുകയില്ല. ഒരു ഗവർണ്ണറെ അയച്ചാൽ നബി(സ) അയാളുടെ പേര് ചോദിക്കും. അവിടുത്തേക്ക് ഇഷ്ടപ്പെട്ടാൽ സന്തോഷിക്കും, സന്തോഷം മുഖത്ത് പ്രകടമാവുകയും ചെയ്യും. ഇഷ്ടപ്പെട്ടില്ലെങ്കിൽ നബി(സ)യുടെ മുഖത്ത് വെറുപ്പ് പ്രകടമാകും. ഒരു ഗ്രാമത്തിൽ പ്രവേശിച്ചാൽ തിരുമേനി(സ) അതിന്റെ പേര് ചോദിക്കും. പേര് ഇഷ്ടപ്പെട്ടാൽ സന്തോഷിക്കുകയും സന്തോഷം മുഖത്ത് പ്രകടമാകുകയും ചെയ്യും. ഇഷ്ടപ്പെട്ടില്ലെങ്കിൽ നബി(സ)യുടെ മുഖത്ത് വെറുപ്പ് പ്രകടമാകും. (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 673, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ سَعِيدِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "لَا هَامَةَ، وَلَا عَدْوَى، وَلَا طِيَرَةَ، وَإِنْ تَكُنِ الطِّيَرَةُ فِي شَيْءٍ فَفِي الْفَرَسِ وَالْمَرْأَةِ وَالدَّارِ". (د)', 'സഇൗദുബ്നു മാലിക്(റ): നബി(സ) പറയാറുണ്ടായിരുന്നു: "ഹാമത് (കൂമൻപക്ഷി വീട്ടിൻപുറത്ത് വന്നിരുന്നാൽ വിപത്ത് ഇറങ്ങുമെന്ന വിശ്വാസം) ശരിയല്ല. പകർച്ച വ്യാധിയുമില്ല. പക്ഷിലക്ഷണവുമില്ല. ഒരുപക്ഷേ, പക്ഷിലക്ഷണം സംഭവിക്കുകയാണെങ്കിൽ അത് കുതിരയിലും സ്ത്രീയിലും വീട് സംബന്ധമായും ആയിരിക്കും." (ദ)', 'سَعِيدِ بْنِ مَالِكٍ', 'സഇൗദുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الشُّؤْمُ فِي الدَّارِ وَالْمَرْأَةِ وَالْفَرَسِ". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "വീടിലും, സ്ത്രീയിലും, കുതിരയിലുമാണ് അവലക്ഷണമുള്ളത്." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ فَرْوَةَ بْنِ مُسَيْكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، أَرْضٌ عِنْدَنَا يُقَالُ لَهَا أَرْضُ أَبْيَنَ، هِيَ أَرْضُ رِيفِنَا وَمِيرَتِنَا، وَإِنَّهَا وَبِئَةٌ، أَوْ قَالَ: وَبَاؤُهَا شَدِيدٌ. فَقَالَ النَّبِيُّ: "دَعْهَا عَنْكَ، فَإِنَّ مِنَ الْقَرَفِ التَّلَفَ". (د)', 'ഫർവതുബ്നു മുസൈക്(റ): ഞാൻ നബി(സ)യോട് പറഞ്ഞു: തിരുദൂതരേ, ''അബ്യൻ'' എന്ന് പേരുള്ള സ്ഥലം ഞങ്ങളുടെ സമീപത്തുണ്ട്. ഞങ്ങളുടെ കൃഷിയും നിത്യഭക്ഷ്യധാന്യങ്ങളും അവിടെയാണുള്ളത്. അത് രോഗങ്ങളധികമുള്ള സ്ഥലമാണ് - അല്ലെങ്കിൽ, അവിടത്തെ ബുദ്ധിമുട്ടുകൾ അതിഭയങ്കരമാണ്. - അപ്പോൾ നബി(സ) പറഞ്ഞു: "താങ്കൾ അവിടം ഉപേക്ഷിക്കുക. രോഗത്തിനോടടുക്കുന്നതിലാണ് നാശം വരുന്നത്." (ദ)', 'فَرْوَةَ بْنِ مُسَيْكٍ', 'ഫർവതുബ്നു മുസൈക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَجُلٌ: يَا رَسُولَ اللهِ، إِنَّا كُنَّا فِي دَارٍ كَثِيرٌ فِيهَا عَدَدُنَا وَكَثِيرٌ فِيهَا أَمْوَالُنَا، فَتَحَوَّلْنَا إِلَى دَارٍ أُخْرَى، فَقَلَّ فِيهَا عَدَدُنَا وَقَلَّتْ فِيهَا أَمْوَالُنَا. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ذَرُوهَا، ذَمِيمَةً". (د)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ നബി(സ)യോട് പറഞ്ഞു: റസൂലേ, ഞങ്ങളാദ്യം ഒരു വീട്ടിൽ താമസിച്ചപ്പോൾ കൂടുതൽ ആളുകളും വളരെ സമ്പത്തും ഉണ്ടായിരുന്നു. പിന്നീട് ഞങ്ങൾ മറ്റൊരു വീട്ടിലേക്ക് മാറി. അപ്പോൾ ഞങ്ങളുടെ സമ്പത്തും ആളുകളുടെ എണ്ണവും കുറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "മോശമായ അവസ്ഥയിൽ നിങ്ങളതിനെ ഒഴിവാക്കുക." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ قَبِيصَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْعِيَافَةُ وَالطِّيَرَةُ وَالطَّرْقُ مِنَ الْجِبْتِ". (د)', 'ഖബീസ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "പക്ഷിലക്ഷണം (ചില പ്രത്യേകയിനം പക്ഷികളെ ആട്ടുമ്പോൾ വലതു ഭാഗത്തേക്ക് വന്നാൽ ശുഭാപ്തി വിശ്വാസവും ഇടതു ഭാഗത്തേക്ക് വന്നാൽ ദുശ്ശകുനവുമായി കരുതുന്ന വിശ്വാസം), ചില പക്ഷികളിൽ ദുശ്ശകുനം മാത്രമായി ഗണിക്കൽ, ചരൽക്കല്ല് വിതറി പ്രശ്നം വെക്കൽ മുതലായവ അസത്യ മാർഗ്ഗത്തിൽ പെട്ടതാണ്." (ദ)', 'قَبِيصَةَ', 'ഖബീസ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، وَمِنَّا رِجَالٌ يَخُطُّونَ. قَالَ: "كَانَ نَبِيٌّ مِنَ الْأَنْبِيَاءِ يَخُطُّ، فَمَنْ وَافَقَ خَطَّهُ فَذَاكَ". (م,د,ن)', 'മുആവിയതുബ്നുൽ ഹകമിസ്സുലമി(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഭൂമിയിൽ കള്ളിവരച്ച് പ്രശ്നം വെക്കുന്ന ചിലർ ഞങ്ങളുടെ സമൂഹത്തിലുണ്ട്. നബി(സ) പറഞ്ഞു: "പ്രവാചകന്മാരിലൊരാൾ കള്ളി വരക്കുന്നവരായിരുന്നു. അദ്ദേഹത്തോട് യോജിച്ചുകൊണ്ട് ആരെങ്കിലും അങ്ങനെ ചെയ്താൽ പ്രശ്നമില്ല." (മു,ദ,ന)', 'مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ', 'മുആവിയതുബ്നുൽ ഹകമിസ്സുലമി(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنِ ابْنِ شِهَابٍ: أَنَّ أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ حَدَّثَهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا عَدْوَى". وَيُحَدِّثُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُورِدُ مُمْرِضٌ عَلَى مُصِحٍّ". قَالَ أَبُو سَلَمَةَ: كَانَ أَبُو هُرَيْرَةَ يُحَدِّثُهُمَا كِلْتَيْهِمَا عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَمَتَ أَبُو هُرَيْرَةَ بَعْدَ ذَلِكَ عَنْ قَوْلِهِ: "لَا عَدْوَى". وَأَقَامَ عَلَى أَنْ: "لَا يُورِدُ مُمْرِضٌ عَلَى مُصِحٍّ". قَالَ: فَقَالَ الْحَارِثُ بْنُ أَبِي ذُبَابٍ - وَهُوَ ابْنُ عَمِّ أَبِي هُرَيْرَةَ - : قَدْ كُنْتُ أَسْمَعُكَ يَا أَبَا هُرَيْرَةَ تُحَدِّثُنَا مَعَ هَذَا الْحَدِيثِ حَدِيثًا آخَرَ قَدْ سَكَتَّ عَنْهُ، كُنْتَ تَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا عَدْوَى". فَأَبَى أَبُو هُرَيْرَةَ أَنْ يَعْرِفَ ذَلِكَ، وَقَالَ: "لَا يُورِدُ مُمْرِضٌ عَلَى مُصِحٍّ". فَمَارَاهُ الْحَارِثُ فِي ذَلِكَ حَتَّى غَضِبَ أَبُو هُرَيْرَةَ، فَرَطَنَ بِالْحَبَشِيَّةِ، فَقَالَ لِلْحَارِثِ: أَتَدْرِي مَاذَا قُلْتُ؟ قَالَ: لَا، قَالَ أَبُو هُرَيْرَةَ: إِنِّي قُلْتُ: أَبَيْتُ. قَالَ أَبُو سَلَمَةَ: وَلَعَمْرِي لَقَدْ كَانَ أَبُو هُرَيْرَةَ يُحَدِّثُنَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا عَدْوَى". فَلَا أَدْرِي: أَنَسِيَ أَبُو هُرَيْرَةَ، أَوْ نَسَخَ أَحَدُ الْقَوْلَيْنِ الْآخَرَ. (م)', 'ഇബ്നുശിഹാബ്(റ): അബൂസലമതുബ്നു അബ്ദിർറഹ്മാനിബ്നി ഔഫ്(റ) അദ്ദേഹത്തിന് ഹദീസ് ഉദ്ധരിച്ചുകൊടുത്തു: നബി(സ) പറഞ്ഞു: "പകർച്ച വ്യാധിയില്ല." മറ്റൊരു ഹദീസ് കൂടി അദ്ദേഹം ഉദ്ധരിച്ചു: റൂൽ(സ) പറഞ്ഞു: "ഒരു രോഗിയെ ഒരു ആരോഗ്യവാന്റെയടുത്തേക്ക് കൊണ്ടുവരരുത്." അബൂസലമ(റ) പറഞ്ഞു: അബൂഹുറൈറ(റ) ഈ രണ്ട് ഹദീസുകളും ഉദ്ധരിക്കാറുണ്ടായിരുന്നു. ശേഷം "പകർച്ചവ്യാധിയില്ല." എന്ന ഹദീസിനെക്കുറിച്ച് അദ്ദേഹം മൗനം പാലിക്കുകയും "ഒരു രോഗിയെ ഒരു ആരോഗ്യവാന്റെയടുത്തേക്ക് കൊണ്ടവരരുത്." എന്ന ഹദീസിനെക്കുറിച്ച് വാചാലനാവുകയും ചെയ്തു. അപ്പോൾ ഹാരിസുബ്നു ദുബാബ(റ) - അദ്ദേഹം അബൂഹുറൈറ(റ)വിന്റെ പിതൃവ്യ പുത്രനാണ് - ചോദിച്ചു: ഏ അബൂഹുറൈറ, താങ്കൾ ഈ ഹദീസിനോടൊപ്പം മറ്റൊരു ഹദീസുകൂടി പറയുന്നത് ഞാൻ കേൾക്കാറുണ്ടായിരുന്നല്ലോ, അതിനെക്കുറിച്ച് താങ്കളെന്താണ് മൗനം പാലിക്കുന്നത്? "പകർച്ചവ്യാധിയില്ല" എന്ന് നബി(സ) പറഞ്ഞിട്ടുണ്ടെന്ന് താങ്കൾ പറയാറുണ്ടായിരുന്നല്ലോ? അപ്പോൾ അക്കാര്യം സമ്മതിക്കാൻ അബൂഹുറൈറ(റ) വിസമ്മതിക്കുകയും "ഒരു രോഗിയെ ഒരു ആരോഗ്യവാന്റെയടുത്തേക്ക് കൊണ്ടുവരരുത്." എന്ന് പറയുകയും ചെയ്തു. ഹാരിസ്(റ) അദ്ദേഹത്തോട് ഇവ്വിഷയകമായി തർക്കിക്കുകയും അബൂഹുറൈറ(റ) ദേഷ്യപ്പെടുകും അവ്യക്തമായി എന്തോ പറയുകയും ചെയ്തു. പിന്നെ അബൂഹുറൈറ(റ) ഹാരിസിനോട് ചോദിച്ചു: ഞാനെന്താണ് പറഞ്ഞതെന്ന് നിനക്ക് മനസ്സിലായോ? അദ്ദേഹം പറഞ്ഞു: ഇല്ല. അബൂഹുറൈറ(റ) പറഞ്ഞു: ഞാൻ സമ്മതിക്കില്ല. അബൂസലമ(റ) പറഞ്ഞു: എന്റെ ആയുസ്സ് തന്നെ സത്യം, അബൂഹുറൈറ(റ) പറയാറുണ്ടായിരുന്നു: നബി(സ) പറഞ്ഞു: "പകർച്ചവ്യാധിയില്ല." അബൂഹുറൈറ(റ) മറന്നുപോയതാണോ അതോ രണ്ടുവാക്കുകളിൽ ഒന്ന് മറ്റേതിനെ ദുർബലപ്പെടുത്തിയതാണോ എന്നെനിക്കറിയില്ല. (മു)', 'ابْنِ شِهَابٍ', 'ഇബ്നുശിഹാബ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 675, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنِ الشَّرِيدِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ فِي وَفْدِ ثَقِيفٍ رَجُلٌ مَجْذُومٌ، فَأَرْسَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّا قَدْ بَايَعْنَاكَ، فَارْجِعْ". (م)', 'ശരീദ്(റ): സഖീഫ് ഗോത്രത്തിൽ നിന്ന് വന്ന സംഘത്തിൽ ഒരു കുഷ്ഠരോഗിയുണ്ടായിരുന്നു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തോട് ഇപ്രകാരം പറയാനായി ഒരാളെ അയച്ചു: "ഞാൻ താങ്കളുമായി ഉടമ്പടി ചെയ്തിരിക്കുന്നു. അതുകൊണ്ട് താങ്കൾ മടങ്ങിപ്പോകുക." (മു)', 'الشَّرِيدِ', 'ശരീദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 676, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُورَدَنَّ مُمْرِضٌ عَلَى مُصِحٍّ". (خ)', 'അബൂഹുറൈറ(റ): തിരുമേനി(സ) പറഞ്ഞു: "രോഗം ബാധിച്ച ഒട്ടകത്തെ രോഗം ബാധിക്കാത്ത ഒട്ടകത്തിന്റെയടുക്കലേക്ക് കൊണ്ടുപോകരുത്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 676, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا عَدْوَى، وَلَا طِيَرَةَ، وَلَا صَفَرَ، وَلَا هَامَةَ". فَقَالَ أَعْرَابِيٌّ: مَا بَالُ الْإِبِلِ تَكُونُ فِي الرَّمْلِ كَأَنَّهَا الظِّبَاءُ، فَيُخَالِطُهَا الْبَعِيرُ الْأَجْرَبُ فَيُجْرِبُهَا؟ قَالَ: "فَمَنْ أَعْدَى الْأَوَّلَ". قَالَ الزُّهْرِيُّ: فَحَدَّثَنِي رَجُلٌ عَنْ أَبِي هُرَيْرَةَ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يُورِدَنَّ مُمْرِضٌ عَلَى مُصِحٍّ". قَالَ: فَرَاجَعَهُ الرَّجُلُ فَقَالَ: أَلَيْسَ قَدْ حَدَّثَنَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا عَدْوَى وَلَا صَفَرَ وَلَا هَامَةَ". قَالَ: لَمْ أُحَدِّثْكُمُوهُ. قَالَ الزُّهْرِيُّ: قَالَ أَبُو سَلَمَةَ: قَدْ حَدَّثَ بِهِ، وَمَا سَمِعْتُ أَبَا هُرَيْرَةَ نَسِيَ حَدِيثًا قَطُّ غَيْرَهُ. (ق,د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പകർച്ച വ്യാധിയില്ല, പക്ഷിലക്ഷണമില്ല, പ്രത്യേക മാസത്തിൽ മാത്രം ബുദ്ധിമുട്ടിറങ്ങലില്ല, ഹാമ്മതും (കൂമൻ പക്ഷി, അത് വീട്ടിൻപുറത്ത് വന്നിരുന്നാൽ ബുദ്ധിമുട്ടിറങ്ങുമെന്ന വിശ്വാസം) ഇല്ല. അപ്പോൾ ഒരു അഅ്റാബി ചോദിച്ചു: മാനുകളെപ്പോലെ മണലിലൂടെ നടക്കുന്ന ഒട്ടകങ്ങളെക്കുറിച്ച് എന്ത് പറയുന്നു? ചൊറി പിടിച്ച ഒരു ഒട്ടകം കൂട്ടത്തിൽ പ്രവേശിക്കുമ്പോൾ ഈ ഒട്ടകങ്ങൾക്കും ചൊറിപിടിക്കുന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "ആദ്യത്തെ ഒട്ടകത്തിന് ചൊറി നൽകിയതാരാണ്?" സുഹ്രി(റ) പറഞ്ഞു: അബൂഹുറൈറ(റ)വിനെക്കുറിച്ച് ഒരാൾ എനിക്ക് ഇപ്രകാരം പറഞ്ഞുതന്നു: നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "രോഗം ബാധിച്ചവൻ രോഗം ബാധിക്കാത്തവന്റെയടുക്കലേക്ക് പോകരുത്. നിവേദകൻ പറയുന്നു: അപ്പോൾ ആ വ്യക്തി അദ്ദേഹത്തോട് ചോദിച്ചു: അദ്ദേഹം തന്നെയല്ലേ നമുക്ക് ഇപ്രകാരം ഹദീസ് പറഞ്ഞുന്നത്, റസൂൽ(സ) പറഞ്ഞിരിക്കുന്നു: "പകർച്ചവ്യാധിയില്ല, പ്രത്യേക മാസത്തിൽ മാത്രം ബുദ്ധിമുട്ടിറങ്ങലില്ല, ഹാമ്മത്തും ഇല്ല." അദ്ദേഹം പറഞ്ഞു: ഞാൻ നിങ്ങൾക്ക് അങ്ങനെ ഹദീസ് പറഞ്ഞുതന്നിട്ടില്ല. സുഹ്രി(റ) പറയുന്നു: അബൂസലമ(റ) പറഞ്ഞു: അബൂഹുറൈറ(റ) അപ്രകാരം ഹദീസ് പറഞ്ഞുതന്നിട്ടുണ്ട്. ഇതല്ലാത്ത മറ്റൊരു ഹദീസും അബൂഹുറൈറ(റ) മറന്നതായി ഞാൻ കേട്ടിട്ടില്ല. (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 676, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَخَذَ بِيَدِ مَجْذُومٍ فَوَضَعَهَا مَعَهُ فِي الْقَصْعَةِ، وَقَالَ: "كُلْ، ثِقَةً بِاللهِ وَتَوَكُّلًا عَلَيْهِ". (د,ت,جه)', 'ജാബിർ(റ): നബി(സ) ഒരു കുഷ്ഠരോഗിയുടെ കൈ പിടിച്ച് തന്റെകൂടെ തളികയിലേക്ക് വെച്ച് പറഞ്ഞു: "അല്ലാഹുവിന്റെ മേൽ ഭരമേൽപിച്ച് അവനിൽ ഉറപ്പിച്ചുകൊണ്ട് നീ തിന്നുക." (ദ,തു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "إِنَّ هَذَا الْوَجَعَ - أَوِ السَّقَمَ - رِجْزٌ عُذِّبَ بِهِ بَعْضُ الْأُمَمِ قَبْلَكُمْ، ثُمَّ بَقِيَ بَعْدُ بِالْأَرْضِ، فَيَذْهَبُ الْمَرَّةَ وَيَأْتِي الْأُخْرَى، فَمَنْ سَمِعَ بِهِ بِأَرْضٍ فَلَا يَقْدَمَنَّ عَلَيْهِ، وَمَنْ وَقَعَ بِأَرْضٍ وَهُوَ بِهَا فَلَا يُخْرِجَنَّهُ الْفِرَارُ مِنْهُ". (م)', 'ഉസാമതുബ്നു സൈദ്(റ): നബി(സ) പറഞ്ഞു: "ഈ വേദന അല്ലെങ്കിൽ ഈ രോഗം നിങ്ങളുടെ മുമ്പുണ്ടായിരുന്ന സമുദായങ്ങളിൽ ചിലർക്ക് നൽകപ്പെട്ട ശിക്ഷയാണ്. പിന്നീട് അത് ഭൂമിയിൽ അവശേഷിച്ചു. അത് ഒരിക്കൽ ഇല്ലാതാവുകയും മറ്റൊരിക്കൽ വരികയും ചെയ്യും. ഈ രോഗം ഏതെങ്കിലും നാട്ടിലുണ്ടെന്ന് ആരെങ്കിലും അറിഞ്ഞാൽ ആ നാട്ടിലേക്ക് പോകരുത്. ആ രോഗമുള്ള നാട്ടിൽ എത്തിയയാൾ അതിനെ പേടിച്ച് അവിടെനിന്ന് ഓടിപ്പോവുകയും അരുത്." (മു)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ خَرَجَ إِلَى الشَّامِ، حَتَّى إِذَا كَانَ بِسَرْغَ لَقِيَهُ أَهْلُ الْأَجْنَادِ: أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ وَأَصْحَابُهُ، فَأَخْبَرُوهُ أَنَّ الْوَبَاءَ قَدْ وَقَعَ بِالشَّامِ، قَالَ ابْنُ عَبَّاسٍ: فَقَالَ عُمَرُ: ادْعُ لِيَ الْمُهَاجِرِينَ الْأَوَّلِينَ. فَدَعَوْتُهُمْ، فَاسْتَشَارَهُمْ وَأَخْبَرَهُمْ أَنَّ الْوَبَاءَ [قَدْ] وَقَعَ بِالشَّامِ، فَاخْتَلَفُوا، فَقَالَ بَعْضُهُمْ: قَدْ خَرَجْتَ لِأَمْرٍ وَلَا نَرَى أَنْ تَرْجِعَ عَنْهُ، وَقَالَ بَعْضُهُمْ: مَعَكَ بَقِيَّةُ النَّاسِ وَأَصْحَابُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَا نَرَى أَنْ تُقْدِمَهُمْ عَلَى هَذَا الْوَبَاءِ. قَالَ: ارْتَفِعُوا عَنِّي، ثُمَّ قَالَ: ادْعُ لِيَ الْأَنْصَارَ. فَدَعَوْتُهُمْ لَهُ، فَاسْتَشَارَهُمْ، فَسَلَكُوا سَبِيلَ الْمُهَاجِرِينَ وَاخْتَلَفُوا كَاخْتِلَافِهِمْ، فَقَالَ: ارْتَفِعُوا عَنِّي، ثُمَّ قَالَ: ادْعُ لِي مَنْ كَانَ هَاهُنَا مِنْ مَشْيَخَةِ قُرَيْشٍ مِنْ مُهَاجِرَةِ الْفَتْحِ. فَدَعَوْتُهُمْ فَلَمْ يَخْتَلِفْ عَلَيْهِ رَجُلَانِ، فَقَالُوا: نَرَى أَنْ تَرْجِعَ بِالنَّاسِ، وَلَا تُقْدِمَهُمْ عَلَى هَذَا الْوَبَاءِ. فَنَادَى عُمَرُ فِي النَّاسِ: إِنِّي مُصْبِحٌ عَلَى ظَهْرٍ، فَأَصْبِحُوا عَلَيْهِ. فَقَالَ أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ: أَفِرَارًا مِنْ قَدَرِ اللهِ؟ فَقَالَ عُمَرُ: لَوْ غَيْرُكَ قَالَهَا يَا أَبَا عُبَيْدَةَ - وَكَانَ عُمَرُ يَكْرَهُ خِلَافَهُ - نَعَمْ، نَفِرُّ مِنْ قَدَرِ اللهِ إِلَى قَدَرِ اللهِ، أَرَأَيْتَ لَوْ كَانَتْ لَكَ إِبِلٌ فَهَبَطَتْ وَادِيًا لَهُ عُدْوَتَانِ: إِحْدَاهُمَا خَصْبَةٌ وَالْأُخْرَى جَدْبَةٌ، أَلَيْسَ إِنْ رَعَيْتَ الْخَصْبَةَ رَعَيْتَهَا بِقَدَرِ اللهِ، وَإِنْ رَعَيْتَ الْجَدْبَةَ رَعَيْتَهَا بِقَدَرِ اللهِ؟ قَالَ: فَجَاءَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ وَكَانَ مُتَغَيِّبًا فِي بَعْضِ حَاجَتِهِ، فَقَالَ: إِنَّ عِنْدِي مِنْ هَذَا عِلْمًا، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا سَمِعْتُمْ بِهِ بِأَرْضٍ فَلَا تَقْدَمُوا عَلَيْهِ، وَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا فِرَارًا مِنْهُ". قَالَ: فَحَمِدَ اللهَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، ثُمَّ انْصَرَفَ. (م)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) ശാമിലേക്ക് പുറപ്പെട്ടു. അങ്ങനെ ''സർഗ'' എന്ന സ്ഥലത്ത് വെച്ച് (മുസ്ലിം) സൈന്യങ്ങളിൽപെട്ട അബൂഉബൈദതുബ്നുൽ ജർറാഹ്(റ)വും അദ്ദേഹത്തിന്റെ ആളുകളും അദ്ദേഹത്തെ കണ്ടുമുട്ടി. അവർ അദ്ദേഹത്തോട് പറഞ്ഞു: ശാമിൽ പ്ലേഗ് പിടിപെട്ടിരിക്കുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ആദ്യമുഹാജിറുകളെ വിളിച്ചുകൊണ്ടുവരൂ. ഞാനവരെ വിളിച്ചു. അപ്പോൾ അദ്ദേഹം ശാമിൽ പ്ലേഗ് ബാധിച്ചിട്ടുണ്ടെന്ന് അവരെ അറിയിക്കുകയും (എന്ത് ചെയ്യണമെന്ന്) അവരോട് ചർച്ച നടത്തുകയും ചെയ്തു. പക്ഷേ, അവർ അഭിപ്രായ ഭിന്നരായി. ചിലർ പറഞ്ഞു: താങ്കൾ ഒരു കാര്യത്തിന് വേണ്ടി ഇറങ്ങിയതാണ്. അതിനാൽ (അതൊഴിവാക്കി) അങ്ങ് മടങ്ങിപ്പോകണമെന്ന് ഞങ്ങൾക്കഭിപ്രായമില്ല. മറ്റുചിലർ പറഞ്ഞു: അങ്ങയോടൊപ്പം ബാക്കിയുള്ള ജനങ്ങളും നബി(സ)യുടെ സ്വഹാബികളും ഉണ്ട്. അതിനാൽ അവരുമായി പ്ലേഗുബാധിച്ച മേഖലയിലേക്ക് പോകണമെന്ന് ഞങ്ങൾക്കഭിപ്രായമില്ല. ഉമർ(റ) പറഞ്ഞു: ഇനി നിങ്ങൾ പോകൂ. പിന്നെ ഉമർ(റ) പറഞ്ഞു: എനിക്ക് വേണ്ടി അൻസ്വാറുകളെ വിളിച്ച് വരുത്തൂ. അപ്പോൾ ഞാൻ അദ്ദേഹത്തിന് വേണ്ടി അവരെ വിളിച്ചു. ഉമർ(റ) അവരോടും ചർച്ച ചെയ്തു. അവരും മുഹാജിറുകളെപ്പോലെ ഭിന്നസ്വരങ്ങളുയർത്തി. അദ്ദേഹം അവരോട് പറഞ്ഞു: നിങ്ങൾക്ക് പോകാം. പിന്നീടദ്ദേഹം പറഞ്ഞു: ഇവിടെയുള്ള, ഫത്ഹ് മക്കയുടെ സമയത്ത് ഹിജ്റ ചെയ്തവരിൽ നിന്നുള്ള ഖുറൈശീ വൃദ്ധന്മാരെ എനിക്ക് വേണ്ടി വിളിക്കൂ. അങ്ങനെ ഞാനവരെ വിളിച്ചു. അപ്പോൾ അവരിൽ നിന്നാരും തന്നെ ഭിന്നാഭിപ്രായക്കാരായില്ല. അവർ പറഞ്ഞു: താങ്കൾ ജനങ്ങളുമായി പ്ലേഗ്ബാധിത സ്ഥലത്തേക്ക്പോകാതെ, അവരുമായി തിരിച്ചുപോകണമെന്നാണ് ഞങ്ങൾ അഭിപ്രായപ്പെടുന്നത്. അപ്പോൾ ഉമർ(റ) ജനങ്ങളോട് വിളിച്ചുപറഞ്ഞു: ഞാൻ നാളെ രാവിലെ (മദീനയിലേക്ക്) തിരിച്ച് പോകും. നിങ്ങളും അപ്രകാരം ചെയ്യുക. അപ്പോൾ അബൂഉബൈദതുബ്നുൽ ജർറാഹ്(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ വിധിയിൽ നിന്ന് താങ്കൾ പേടിച്ചോടുകയാണോ? അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ഏ, അബൂഉബൈദ, ഇത് പറഞ്ഞത് നീയല്ലാത്തവരായിരുന്നെങ്കിൽ - തന്നോട് എതിർത്ത് പറയുന്നത് ഉമർ(റ)വിന്ന് വെറുപ്പായിരുന്നു - അതെ, അല്ലാഹുവിന്റെ വിധിയിൽ നിന്ന് അല്ലാഹുവിന്റെ വിധിയിലേക്ക് തന്നെ ഞങ്ങൾ ഓടുന്നു. താങ്കൾക്ക് ഒരു ഒട്ടകമുണ്ടാവുകയും അങ്ങനെ അത് വരണ്ടതും പച്ചപിടിച്ചതുമായ രണ്ട് ഉയർന്ന സ്ഥലങ്ങളുള്ള ഒരു മലഞ്ചെരുവിലേക്ക് ഇറങ്ങുകയും ചെയ്താൽ അതിനെ നീ പച്ചപിടിച്ച സ്ഥലത്ത് മേച്ചാൽ അല്ലാഹുവിന്റെ വിധികൊണ്ടല്ലെയോ നീ മേക്കുന്നത്. അതിനെ വരണ്ട സ്ഥലത്ത് മേച്ചാലും, അല്ലാഹുവിന്റെ വിധികൊണ്ടല്ലെയോ നീ മേക്കുന്നത്? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ചില ആവശ്യങ്ങൾക്ക് വേണ്ടി പുറത്തുപോയിരുന്ന അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) അപ്പോൾ വന്നു. അദ്ദേഹം പറഞ്ഞു: ഇവ്വിഷയകമായി എന്റെ പക്കൽ ഒരു വിജ്ഞാനമുണ്ട്. നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "വല്ല സ്ഥലത്തും പ്ലേഗ് ഉണ്ടെന്ന് അറിഞ്ഞാൽ നിങ്ങളവിടേക്ക് പോകരുത്. നിങ്ങളുള്ള സ്ഥലത്ത് പ്ലേഗ് ബാധിച്ചാൽ അവിടെനിന്ന് നിങ്ങൾ പേടിച്ചോടുകയും അരുത്." ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അപ്പോൾ ഉമറുബ്നുൽഖത്താബ്(റ) അല്ലാഹുവിനെ സ്തുതിക്കുകയും പിന്നെ അവിടെ നിന്ന് തിരിഞ്ഞു പോവുകയും ചെയ്തു. (മു)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَدْ', null, 677, 678, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الطَّاعُونُ شَهَادَةٌ لِكُلِّ مُسْلِمٍ". (خ)', 'അനസുബ്നു മാലിക്(റ): തിരുമേനി(സ) അരുളി: "പ്ലേഗ് മൂലമുള്ള മരണം ഓരോ മുസ്ലിമിനും രക്തസാക്ഷിത്വമാണ്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 678, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنِ ابْنَةِ وَهْبٍ - وَهِيَ جُدَامَةُ رَضِيَ اللهُ عَنْهَا - قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَرَدْتُ أَنْ أَنْهَى عَنِ الْغِيَالِ، فَإِذَا فَارِسُ وَالرُّومُ يَفْعَلُونَ، وَلَا يَقْتُلُونَ أَوْلَادَهُمْ". وَفِي رِوَايَةٍ: "لَقَدْ هَمَمْتُ أَنْ أَنْهَى عَنِ الْغِيلَةِ، حَتَّى ذَكَرْتُ أَنَّ الرُّومَ وَفَارِسَ يَصْنَعُونَ ذَلِكَ فَلَا يَضُرُّ أَوْلَادَهُمْ". (م,د,ت,ن,جه)', 'വഹബിന്റെ മകൾ ജുദാമ(റ)യിൽ നിന്ന് ആഇശ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "മുലകൊടുക്കുന്ന തന്റെ ഭാര്യയുമായി ഒരു ഭർത്താവ് ബന്ധപ്പെടലിനെയും ഗർഭമുള്ള സമയത്ത് മുലകൊടുക്കുന്നതിനെയും(ഗീലത്ത്) വിലക്കാൻ ഞാൻ ഉദ്ദേശിച്ചു. പക്ഷെ റോമക്കാരും പേർഷ്യക്കാരും അങ്ങനെ ചെയ്യുന്നുണ്ടെങ്കിലും അവരുടെ കുട്ടികൾ മരിക്കുന്നില്ല (അതിനാൽ ഞാൻ അതിനെ വിലക്കുന്നില്ല)." മറ്റൊരു നിവേദനത്തിൽ: "മുലകൊടുക്കുന്ന തന്റെ ഭാര്യയുമായി ഒരു ഭർത്താവ് ബന്ധപ്പെടലിനെയും ഗർഭിണിയായിരിക്കെ അവൾ മുലകൊടുക്കലിനെയും(ഗീലത്ത്) വിലക്കാൻ ഞാൻ കരുതി. അപ്പോഴാണ് പേർഷ്യക്കാരും റോമക്കാരും അപ്രകാരം ചെയ്തിട്ടും അവരുടെ കുട്ടികൾക്ക് പ്രശ്നമൊന്നുമില്ലെന്ന് ഞാൻ ഓർത്തത്." (മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'വഹബിന്റെ മകൾ ജുദാമ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=11 and h.hadith_no=203), 1, 'وَفِي رِوَايَةٍ: "لَقَدْ هَمَمْتُ أَنْ أَنْهَى عَنِ الْغِيلَةِ، حَتَّى ذَكَرْتُ أَنَّ الرُّومَ وَفَارِسَ يَصْنَعُونَ ذَلِكَ فَلَا يَضُرُّ أَوْلَادَهُمْ". (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "മുലകൊടുക്കുന്ന തന്റെ ഭാര്യയുമായി ഒരു ഭർത്താവ് ബന്ധപ്പെടലിനെയും ഗർഭിണിയായിരിക്കെ അവൾ മുലകൊടുക്കലിനെയും(ഗീലത്ത്) വിലക്കാൻ ഞാൻ കരുതി. അപ്പോഴാണ് പേർഷ്യക്കാരും റോമക്കാരും അപ്രകാരം ചെയ്തിട്ടും അവരുടെ കുട്ടികൾക്ക് പ്രശ്നമൊന്നുമില്ലെന്ന് ഞാൻ ഓർത്തത്." (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ بْنِ السَّكَنِ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَقْتُلُوا أَوْلَادَكُمْ سِرًّا، فَإِنَّ الْغَيْلَ يُدْرِكُ الْفَارِسَ فَيُدَعْثِرُهُ عَنْ فَرَسِهِ". (د,جه)', 'അസ്മാഉബിൻതി യസീദിബ്നിസ്സകൻ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങളുടെ കുട്ടികളെ രഹസ്യമായി കൊല്ലരുത്. തീർച്ചയായും ഗിയൽ (മുലകൊടുക്കുന്ന ഭാര്യയുമായി ബന്ധപ്പെടലും ഗർഭമുള്ളപ്പോൾ മുലകൊടുക്കലും) കുതിരപ്പടയാളിയെ ബാധിക്കുകയും അതവനെ കുതിരയിൽ നിന്നും (ബലഹീനത മൂലം) തെറിപ്പിക്കുകയും ചെയ്യും." (ദ,ജ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ بْنِ السَّكَنِ', 'അസ്മാഉബിൻതി യസീദിബ്നിസ്സകൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فِي أَحَدِ جَنَاحَيِ الذُّبَابِ سُمٌّ، وَفِي الْآخَرِ شِفَاءٌ. فَإِذَا وَقَعَ فِي الطَّعَامِ فَامْقُلُوهُ فِيهِ، فَإِنَّهُ يُقَدِّمُ السُّمَّ وَيُؤَخِّرُ الشِّفَاءَ". (ن,جه)', 'അബൂസഇൗദ്(റ): നബി(സ) പറഞ്ഞു: "ഈച്ചയുടെ ചിറകിൽ വിഷവും രണ്ടാമത്തേതിൽ ശമനവുമുണ്ട്. ഒരു ഈച്ച ഭക്ഷണത്തിൽ വീണാൽ വീണ്ടും അതിലിട്ട് മുക്കുക. നിശ്ചയം ആദ്യ തവണ അത് വിഷം പുറപ്പെടിയിക്കും, രണ്ടാം തവണ ശമനം നൽകും." (ന,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഇൗദ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا وَقَعَ الذُّبَابُ فِي شَرَابِكُمْ فَلْيَغْمِسْهُ فِيهِ، ثُمَّ لِيَطْرَحْهُ، فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً، وَفِي الْآخَرِ شِفَاءً". (خ,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ പാനീയത്തിൽ ഈച്ച വീണാൽ വീണ്ടും അതിൽ മുക്കുക. പിന്നെ പുറത്തുകളയുക. നിശ്ചയം ഈച്ചയുടെ ഒരു ചിറകിൽ വിഷവും രണ്ടാമത്തേതിൽ ശമനവുമുണ്ട്." (ബു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 679, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَمَرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ ذِي الطُّفْيَتَيْنِ، فَإِنَّهُ يَلْتَمِسُ الْبَصَرَ وَيُصِيبُ الْحَبَلَ. (م,جه)', 'ആഇശ(റ): പുറത്ത് വെള്ള വരകളുള്ള പാമ്പിനെ കൊല്ലാൻ നബി(സ) കൽപിച്ചു. കാരണം അത് അതിന്റെ വിഷവുമായി കണ്ണിനെ ഉദ്ദേശിക്കുകയും അതിന്റെ വിഷം നാഡീ ഞരമ്പുകളെ ബാധിക്കുകുയം ചെയ്യും. (മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اقْتُلُوا الْحَيَّاتِ، وَاقْتُلُوا ذَا الطُّفْيَتَيْنِ وَالْأَبْتَرَ، فَإِنَّهُمَا يَلْتَمِسَانِ الْبَصَرَ وَيُسْقِطَانِ الْحَبَلَ". (ق,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പാമ്പുകളെ കൊല്ലുക, നിങ്ങൾ പുറത്ത് വരയുള്ള വിഷപ്പാമ്പുകളെയും കുറിയ (ചെറിയ വാലുള്ള) പാമ്പിനെയും കൊല്ലുക, കാരണം അവരണ്ടും (അവയുടെ വിഷവുമായി) നിങ്ങളുടെ കണ്ണിനെ ഉദ്ദേശിക്കുകയും നിങ്ങളുടെ നാഡീഞരമ്പുകളെ മുറിക്കുകയും ചെയ്യും." (ബു,മു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَطَبَّبَ وَلَا يُعْلَمُ مِنْهُ طِبٌّ فَهُوَ ضَامِنٌ". (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ചികിത്സ അറിയാത്ത ഒരുത്തൻ ചികിത്സിച്ചാൽ അവൻ അതിന് ഉത്തരവാദിയാണ്." (ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ عَبْدِ الْعَزِيزِ بْنِ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ رَضِيَ اللهُ عَنْهُ: حَدَّثَنِي بَعْضُ الْوَفْدِ الَّذِينَ قَدِمُوا عَلَى أَبِي قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا طَبِيبٍ تَطَبَّبَ عَلَى قَوْمٍ، لَا يُعْرَفُ لَهُ تَطَبُّبٌ قَبْلَ ذَلِكَ، فَأَعْنَتَ، فَهُوَ ضَامِنٌ". قَالَ عَبْدُ الْعَزِيزِ: أَمَا إِنَّهُ لَيْسَ بِالنَّعْتِ، إِنَّمَا هُوَ قَطْعُ الْعُرُوقِ وَالْبَطُّ وَالْكَيُّ. (د,ن,جه)', 'അബ്ദുൽ അസീസുബ്നു ഉമറുബ്നു അബ്ദുൽഅസീസ്(റ): എന്റെ പിതാവിനെ സന്ദർശിക്കാനെത്തിയ സംഘത്തിലെ ചിലയാളുകൾ എനിക്ക് ഹദീസ് പറഞ്ഞുതന്നു. റസൂൽ(സ) പറഞ്ഞു: "മുമ്പ് ചികിത്സ നടത്തിയതായി അറിയപ്പെടാത്ത ഒരു വൈദ്യൻ ഒരു സമൂഹത്തെ ചികിത്സിച്ചു. അത് രോഗിക്ക് ദോഷകരമായി ഭവിച്ചു. എങ്കിൽ ഈ വൈദ്യൻ അതിനുത്തരവാദിയായിരിക്കും." അബ്ദുൽ അസീസ്(റ) പറയുന്നു: ഇതുകൊണ്ടുള്ള ഉദ്ദേശം ഏതെങ്കിലും ചെറിയ പിഴവല്ല. മറിച്ച് ഞെരമ്പ് മുറിക്കൽ, കീറൽ, ചൂടുവെക്കൽ പോലോത്തതാണ്. (ദ,ന,ജ)', 'عَبْدِ الْعَزِيزِ بْنِ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ', 'അബ്ദുൽ അസീസുബ്നു ഉമറുബ്നു അബ്ദുൽഅസീസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ لِضُرٍّ أَصَابَهُ، فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلْ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي". (خ)', 'അനസുബ്നു മാലിക്(റ): തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് ബാധിച്ച ഒരു വിപത്തുമൂലം നിങ്ങൾ മരിക്കാനാഗ്രഹിക്കരുത്. അതല്ലാതെ മറ്റു മോചനമാർഗ്ഗമില്ലെന്ന് തോന്നുന്ന പക്ഷം അവൻ പ്രാർത്ഥിച്ചുകൊള്ളട്ടെ: അല്ലാഹുവേ, ജീവിതം എനിക്കുത്തമമായിരിക്കുന്ന കാലം വരെ നീ എന്നെ ജീവിപ്പിക്കേണമേ, മരണം എനിക്കുത്തമമായി വരുന്ന അവസരത്തിൽ എന്നെ മരിപ്പിക്കുകയും ചെയ്യേണമേ."(ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ خَبَّابٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ اكْتَوَى سَبْعَ كَيَّاتٍ فَقَالَ: إِنَّ أَصْحَابَنَا الَّذِينَ سَلَفُوا مَضَوْا وَلَمْ تَنْقُصْهُمُ الدُّنْيَا، وَإِنَّا أَصَبْنَا مَا لَا نَجِدُ لَهُ مَوْضِعًا إِلَّا التُّرَابَ، وَلَوْلَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَانَا أَنْ نَدْعُوَ بِالْمَوْتِ لَدَعَوْتُ بِهِ. (خ)', 'ഖബ്ബാബ്(റ): അദ്ദേഹത്തിന്റെ ശരീരത്തിൽ ചികിത്സാർത്ഥം ഏഴ് ചൂടുവെക്കൽ നടത്തിയിട്ടുണ്ടായിരുന്നു. അന്നേരം ഖബ്ബാബ്(റ) പറഞ്ഞു: എന്റെ പൂർവ്വ സുഹൃത്തുക്കളെല്ലാം എന്നെ വിട്ടുപോയിക്കഴിഞ്ഞു. ഐഹിക സൗകര്യങ്ങൾ മൂലം അവരുടെ പുണ്യങ്ങൾക്ക് യാതൊരു കുറവും വന്നില്ല. ഞങ്ങൾക്കിതാ വമ്പിച്ച സമ്പത്തുക്കൾ കൈവന്നിരിക്കുന്നു. മണ്ണിലല്ലാതെ അത് സൂക്ഷിക്കാൻ മറ്റൊരിടവും കാണുന്നില്ല. മരണത്തിന് വേണ്ടി പ്രാർത്ഥിക്കുന്നത് തിരുമേനി(സ) നിരോധിച്ചിട്ടുണ്ടായിരുന്നില്ലെങ്കിൽ തീർച്ചയായും ഞാൻ അത് ചെയ്യുമായിരുന്നു. (ബു)', 'خَبَّابٍ', 'ഖബ്ബാബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَنْ يُدْخِلَ أَحَدًا عَمَلُهُ الْجَنَّةَ". قَالُوا: وَلَا أَنْتَ يَا رَسُولَ اللهِ؟ قَالَ: "لَا وَلَا أَنَا، إِلَّا أَنْ يَتَغَمَّدَنِي اللهُ بِفَضْلٍ وَرَحْمَةٍ، فَسَدِّدُوا وَقَارِبُوا، وَلَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ، إِمَّا مُحْسِنًا فَلَعَلَّهُ أَنْ يَزْدَادَ خَيْرًا، وَإِمَّا مُسِيئًا فَلَعَلَّهُ أَنْ يَسْتَعْتِبَ". (خ)', 'അബൂഹുറൈറ(റ): തിരുമേനി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരാളെയും തന്റെ പ്രവർത്തനങ്ങൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയില്ല." സ്വഹാബികൾ ചോദിച്ചു: ദൈവദൂതരേ, അങ്ങയുടെ സ്ഥിതിയും അങ്ങനെത്തന്നെയാണോ? അവിടന്ന് അരുളി: "ഇല്ല, അല്ലാഹു കാരുണ്യവും ഔദാര്യവും ചെയ്ത് അനുഗ്രഹിച്ചില്ലെങ്കിൽ എന്നെയും പ്രവേശിപ്പിക്കുകയില്ല. അതുകൊണ്ട് നിങ്ങളുടെ പ്രവർത്തനങ്ങളെ നന്നാക്കിക്കൊണ്ടിരിക്കുക, പ്രവർത്തനങ്ങളിൽ മിതത്വം പാലിക്കുക. നിങ്ങളിലൊരാളും മരിക്കാൻ ആഗ്രഹിച്ചുകൊണ്ടിരിക്കരുത്. സദ്വൃത്തനാണെങ്കിൽ അവന് കൂടുതൽ നന്മ നേടാൻ അവസരം ലഭിക്കും. ദുർവൃത്തനാണെങ്കിലോ, തെറ്റുകളിൽ നിന്ന് അല്ലാഹുവിനോട് പാപമോചനത്തിനപേക്ഷിക്കാനും അവസരം ലഭിച്ചേക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: وَارَأْسَاهْ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ذَاكِ لَوْ كَانَ وَأَنَا حَيٌّ فَأَسْتَغْفِرَ لَكِ، وَأَدْعُوَ لَكِ". فَقَالَتْ عَائِشَةُ: وَا ثُكْلِيَاهْ، وَاللهِ إِنِّي لَأَظُنُّكَ تُحِبُّ مَوْتِي، وَلَوْ كَانَ ذَاكَ لَظَلَلْتَ آخِرَ يَوْمِكَ مُعَرِّسًا بِبَعْضِ أَزْوَاجِكَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَلْ أَنَا وَا رَأْسَاهْ، لَقَدْ هَمَمْتُ أَوْ أَرَدْتُ أَنْ أُرْسِلَ إِلَى أَبِي بَكْرٍ وَابْنِهِ، وَأَعْهَدَ أَنْ يَقُولَ الْقَائِلُونَ، أَوْ يَتَمَنَّى الْمُتَمَنُّونَ، ثُمَّ قُلْتُ: يَأْبَى اللهُ وَيَدْفَعُ الْمُؤْمِنُونَ، أَوْ يَدْفَعُ اللهُ وَيَأْبَى الْمُؤْمِنُونَ". (خ)', 'ആഇശ(റ): ഹാ! എന്റെ തല തകർന്നല്ലോ! (എനിക്ക് തലവേദനയുണ്ടായപ്പോൾ) എന്ന് ഞാൻ വിലപിച്ചു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഞാൻ ജീവിച്ചിരിക്കുമ്പോഴാണ് നിനക്ക് മരണം സംഭവിച്ചതെങ്കിൽ നിനക്ക് വേണ്ടി ഞാൻ പാപമോചനത്തിനപേക്ഷിക്കുകയും പ്രാർത്ഥിക്കുകയും ചെയ്യും." അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: ഹോ, എന്തൊരു സങ്കടം! അല്ലാഹുവാണ് സത്യം, അങ്ങ് എന്റെ മരണമാഗ്രഹിക്കുന്നുവെന്ന് ഞാൻ കരുതുന്നു. അങ്ങനെ വരുന്നപക്ഷം അങ്ങ് വൈകുന്നേരം തന്നെ മറ്റൊരു ഭാര്യയുമായി കൂടിക്കഴിയും. തിരുമേനി(സ) പറഞ്ഞു: "യഥാർത്ഥത്തിൽ എന്റെ തലക്കാണ് വേദന. ആളുകൾ അതുമിതും പറയാതിരിക്കാനും അതിമോഹികൾ ഭരണകാര്യത്തിൽ കണ്ണുവെക്കാതിരിക്കാനും വേണ്ടി അബൂബക്കറിന്റെയും അദ്ദേഹത്തിന്റെ പുത്രന്റേയുമടുക്കലേക്ക് ആളെയയക്കുവാൻ പോലും ഞാനുദ്ദേശിച്ചു. പിന്നീട് എനിക്ക് തോന്നി, അതല്ലാഹുവിന് സമ്മതമാവുകയില്ല. സത്യവിശ്വാസികൾ അത് നിരസിക്കുകയും ചെയ്തേക്കും. അല്ലെങ്കിൽ അല്ലാഹു അത് നിരസിക്കും, വിശ്വാസികൾക്ക് സമ്മതമാവുകയില്ല." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 681, 682, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَقُولَنَّ أَحَدُكُمْ: خَبُثَتْ نَفْسِي، وَلَكِنْ لِيَقُلْ: لَقِسَتْ نَفْسِي". (م)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "തന്റെ ശരീരം (ആത്മാവടക്കം) അശുദ്ധമാണെന്ന് നിങ്ങളാരും പറയരുത്. മറിച്ച് തന്റെ ശരീരം മടിയനാണെന്ന് പറയുക." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 682, 682, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
