മറ്റൊരു നിവേദനം: അദ്ദേഹം മൂന്ന് ദിവസം രാവിലെയും വൈകുന്നേരവും ആ മനുഷ്യനെ സൂറതുൽ ഫാതിഹ കൊണ്ട് മന്ത്രിച്ചു. സൂറത് അവസാനിക്കുമ്പോഴെല്ലാം അദ്ദേഹം തന്റെ ഉമിനീർ ഒരുമിച്ചുകൂട്ടി തുപ്പുമായിരുന്നു. അങ്ങനെ ആ മനുഷ്യന്റെ ഭ്രാന്ത് ഏറെക്കുറെ സുഖമായി. അപ്പോൾ അവർ അദ്ദേഹത്തിന് എന്തോ സമ്മാനിക്കുകയും അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വരികയും ചെയ്തു. ശേഷം ഈ ഹദീസിന്റെ ആശയം പറഞ്ഞു. (ദ)', 'خَارِجَةَ بْنِ الصَّلْتِ التَّمِيمِيِّ، عَنْ عَمِّهِ', 'ഖാരിജതുബ്നു സ്വൽതുത്തമീമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 661, 662, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
